INSERT INTO spell VALUES (14,'Gathering of Maggots','gathering of maggots','Conjuration','Healing',NULL,'49',NULL,'V, S, DF','7 days',NULL,'Dead creature touched',NULL,NULL,'Permanent','Fortitude negates (harmless)','Yes (harmless)',NULL,'441,000 gp; 9 days; 17,640 XP. Seeds: life (DC 27), transform (DC 21). Factors: change creature type to aberration (+5 DC); add worm that walks\' spell-like, extraordinary, and supernatural abilities (+40 DC). Mitigating factors: increase casting time by 10 minutes (-20 DC); increase casting time by 7 days (-14 DC).',NULL,NULL,NULL,'\n      <p>When this spell is cast, worms or maggots slither and crawl their way inexorably toward the corpse touched. Over the course of the next week, they consume the flesh of the corpse, and when the last bit of the corpse is devoured, the creature is returned to a semblance of life as a worm that walks.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Gathering of Maggots\" level=\"5\"><p><h5>Gathering of Maggots</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Healing)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>49<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, D F<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>7 days<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Dead creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Permanent<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Fortitude negates (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>To Develop:</b><br/></td><td>441,000 gp; 9 days; 17,640 XP. Seeds: life (DC 27), transform (DC 21). Factors: change creature type to aberration (+5 DC); add worm that walks\' spell-like, extraordinary, and supernatural abilities (+40 DC). Mitigating factors: increase casting time by 10 minutes (-20 DC); increase casting time by 7 days (-14 DC).<br/></td></tr></table><p>When this spell is cast, worms or maggots slither and crawl their way inexorably toward the corpse touched. Over the course of the next week, they consume the flesh of the corpse, and when the last bit of the corpse is devoured, the creature is returned to a semblance of life as a worm that walks.</p><p/>\n</div>\n    ','SRD 3.5 EpicMonsters(G-W)');
INSERT INTO spell VALUES (15,'Animus Blast','animus blast','Evocation',NULL,'Cold','50',NULL,'V, S','1 standard action','300 ft.',NULL,'20-ft. -radius hemisphere burst',NULL,'Instantaneous','Reflex half','Yes',NULL,'450,000 gp; 9 days; 18,000 XP. Seeds: energy (DC 19), animate dead (DC 23). Factors: set undead type to skeleton (-12 DC), 1-action casting time (+20 DC).',NULL,NULL,NULL,'\n      <p>When this spell is cast, enemies within range are dealt 10d6 points of cold damage. However, up to twenty of those victims that perish as a result of this blast are then instantly animated as Medium skeletons. These skeletons serve the character indefinitely. The character cannot exceed the normal limit for controlling undead through use of this spell, but other means that allow the character to exceed the normal limit for controlled undead work just as well with undead created with <i>animus blast</i>.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Animus Blast\" level=\"5\"><p><h5>Animus Blast</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Cold]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>50<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>300 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>20-ft. -radius hemisphere burst<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Reflex half<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>To Develop:</b><br/></td><td>450,000 gp; 9 days; 18,000 XP. Seeds: energy (DC 19), animate dead (DC 23). Factors: set undead type to skeleton (-12 DC), 1-action casting time (+20 DC).<br/></td></tr></table><p>When this spell is cast, enemies within range are dealt 10d6 points of cold damage. However, up to twenty of those victims that perish as a result of this blast are then instantly animated as Medium skeletons. These skeletons serve the character indefinitely. The character cannot exceed the normal limit for controlling undead through use of this spell, but other means that allow the character to exceed the normal limit for controlled undead work just as well with undead created with <i>animus blast</i>.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (16,'Animus Blizzard','animus blizzard','Evocation',NULL,'Cold','78',NULL,'V, S','1 minute','300 ft.',NULL,'20-ft. -radius hemisphere burst',NULL,'Instantaneous','Reflex half','Yes',NULL,'702,000 gp; 15 days; 28,080 XP. Seeds: energy (DC 19), animate dead (DC 23). Factors: increase damage to 30d6 (+40 DC), set undead type to wight (-4 DC).',NULL,NULL,NULL,'\n      <p>When this spell is cast, enemies within range are dealt 30d6 points of cold damage. However, up to five victims that perish as a result of this blast are then instantly animated as wights. These five wights serve the character indefinitely. The character cannot exceed the normal limit for controlling undead through use of this spell, but other means that allow the character to exceed the normal limit for controlled undead work just as well with undead created with <i>animus blizzard</i>.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Animus Blizzard\" level=\"5\"><p><h5>Animus Blizzard</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Cold]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>78<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 minute<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>300 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>20-ft. -radius hemisphere burst<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Reflex half<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>To Develop:</b><br/></td><td>702,000 gp; 15 days; 28,080 XP. Seeds: energy (DC 19), animate dead (DC 23). Factors: increase damage to 30d6 (+40 DC), set undead type to wight (-4 DC).<br/></td></tr></table><p>When this spell is cast, enemies within range are dealt 30d6 points of cold damage. However, up to five victims that perish as a result of this blast are then instantly animated as wights. These five wights serve the character indefinitely. The character cannot exceed the normal limit for controlling undead through use of this spell, but other means that allow the character to exceed the normal limit for controlled undead work just as well with undead created with <i>animus blizzard</i>.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (17,'Contingent Resurrection','contingent resurrection','Conjuration','Healing',NULL,'52',NULL,'V, S, DF','1 minute','Touch','You or creature touched',NULL,NULL,'Contingent until expended, then instantaneous','None (see text)','Yes (harmless)',NULL,'468,000 gp; 10 days; 18,720 XP. Seed: life (DC 27). Factor: activates when subject is slain (+25 DC).',NULL,NULL,NULL,'\n      <p><i>Contingent resurrection</i> returns the subject to life if he or she is slain. Once cast, the spell remains quiescent and does not activate until the trigger conditions have been met (but each day it remains untriggered, it uses up an epic spell slot, even if the character cast it on another creature). Once triggered, the spell is expended. If the subject is killed (the trigger), he or she is restored to life and complete health 1 minute later, so long as even a tiny bit of dust remains for <i>Contingent resurrection</i> to act upon. A shaft of light shines down from the heavens, illuminating the subject and everything within 20 feet. The creature is restored to full hit points, vigor, and health, with no loss of prepared spells. However, the subject loses one level (or 1 point of Constitution if the subject was 1st level). <i>Contingent resurrection</i> does not work on a creature that has died of old age.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Contingent Resurrection\" level=\"5\"><p><h5>Contingent Resurrection</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Healing)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>52<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, D F<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 minute<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You or creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Contingent until expended, then instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None (see text)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>To Develop:</b><br/></td><td>468,000 gp; 10 days; 18,720 XP. Seed: life (DC 27). Factor: activates when subject is slain (+25 DC).<br/></td></tr></table><p><i>Contingent resurrection</i> returns the subject to life if he or she is slain. Once cast, the spell remains quiescent and does not activate until the trigger conditions have been met (but each day it remains untriggered, it uses up an epic spell slot, even if the character cast it on another creature). Once triggered, the spell is expended. If the subject is killed (the trigger), he or she is restored to life and complete health 1 minute later, so long as even a tiny bit of dust remains for <i>Contingent resurrection</i> to act upon. A shaft of light shines down from the heavens, illuminating the subject and everything within 20 feet. The creature is restored to full hit points, vigor, and health, with no loss of prepared spells. However, the subject loses one level (or 1 point of Constitution if the subject was 1st level). <i>Contingent resurrection</i> does not work on a creature that has died of old age.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (18,'Create Living Vault (Ritual)','create living vault (ritual)','Conjuration','Creation',NULL,'58',NULL,'V, S, XP','100 days, 11 minutes','0 ft.',NULL,NULL,'One living vault, 50 ft. by 50 ft. by 10 ft.','Instantaneous','None','None',NULL,'540,000 gp; 11 days; 21,600 XP. Seeds: animate (DC 25) large chunk of stone, fortify (DC 27). Factors: allow vault to \'grow\' to proper size after created in 4d4 days (ad hoc +20 DC), increase HD of object by 92 (+184 DC), grant magical immunity (ad hoc +105 DC), increase damage reduction to 15 (+28 DC) and to /epic (+15 DC), make permanent (x5 DC). Mitigating factors: increase casting time by 10 minutes (-20 DC), increase casting time by 100 days (-200 DC), 9d6 backlash (-9 DC), seven additional casters contributing one epic spell slot (_133 DC), burn 20,000 XP per epic caster (_1,600 DC).',NULL,NULL,NULL,'\n      <p>The character creates a construct known as a living vault to protect and hide his or her treasures. Upon completion, the vault initially measures only 5 feet on a side, but it gradually increases to its proper size over the following 4d4 days. The vault is attuned to the character, allowing him or her alone entrance and egress in a manner similar to a <i>dimension door</i> spell. When the character desires the vault to hide itself, he or she gives it a simple command. To summon the vault, the character may cast a <i>sending</i> spell or arrange some other manner to contact it.</p>\n      <p/>\n    ','20,000 XP.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Create Living Vault\" level=\"5\"><p><h5>Create Living Vault (Ritual)</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Creation)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>58<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, XP<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>100 days, 11 minutes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>0 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>One living vault, 50 ft. by 50 ft. by 10 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>To Develop:</b><br/></td><td>540,000 gp; 11 days; 21,600 XP. Seeds: animate (DC 25) large chunk of stone, fortify (DC 27). Factors: allow vault to \'grow\' to proper size after created in 4d4 days (ad hoc +20 DC), increase HD of object by 92 (+184 DC), grant magical immunity (ad hoc +105 DC), increase damage reduction to 15 (+28 DC) and to /epic (+15 DC), make permanent (x5 DC). Mitigating factors: increase casting time by 10 minutes (-20 DC), increase casting time by 100 days (-200 DC), 9d6 backlash (-9 DC), seven additional casters contributing one epic spell slot (_133 DC), burn 20,000 XP per epic caster (_1,600 DC).<br/></td></tr></table><p>The character creates a construct known as a living vault to protect and hide his or her treasures. Upon completion, the vault initially measures only 5 feet on a side, but it gradually increases to its proper size over the following 4d4 days. The vault is attuned to the character, allowing him or her alone entrance and egress in a manner similar to a <i>dimension door</i> spell. When the character desires the vault to hide itself, he or she gives it a simple command. To summon the vault, the character may cast a <i>sending</i> spell or arrange some other manner to contact it.</p><p><i>XP Cost:</i> 20,000 XP.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (19,'Crown of Vermin','crown of vermin','Conjuration','Summoning',NULL,'56',NULL,'V, S','1 minute','Personal',NULL,NULL,'Aura of one thousand insects that surrounds you in a 10-ft. -radius spread','20 rounds (D)','None (see text)','No',NULL,'504,000 gp; 11 days; 20,160 XP. Seeds: summon (DC 14), fortify (DC 17). Factors: summon vermin mass instead of one creature (ad hoc +8 DC), grant damage reduction 1/epic (+15 DC), allow mass to move at your speed (ad hoc +2 DC), perfect control of vermin (ad hoc +2 DC). Mitigating factor: change range to personal (-2 DC).',NULL,NULL,NULL,'\n      <p>After casting <i>crown of vermin</i>,  one thousand venomous, biting and stinging spiders, scorpions, beetles, and centipedes erupt from the very air around the character. This swarm forms a living aura around the character to a radius of 10 feet. The character is immune to his or her own <i>crown of vermin</i>. The swarm goes where the character goes at his or her speed, even if the character takes to the air or water (though water drowns the vermin after 1 full round of immersion, unless the spell is cast underwater, in which case aquatic or marine vermin answer the call and cannot leave the water). Each vermin in the <i>crown of vermin</i> bites a creature who enters the area occupied by the effect (or the character forces the effect into an area occupied by another creature) for 1 point of damage, and then dies. Each victim takes enough points of damage to kill it, destroying that number of vermin in the process. Victims get a Reflex saving throw each round to avoid the full press, and if successful, take only 10d10 bites (and 10d10 points of damage). A total of 1,000 points of damage can be dealt to those who fall prey to the <i>crown of vermin</i>. The vermin have damage reduction 1/epic, so the vermin\'s natural weapons are treated as epic for the purpose of overcoming damage reduction. If there aren\'t enough vermin to kill all the creatures in the spell\'s effect, the creature with the fewest hit points is affected first, then the creature with the second fewest hit points, and so on. After all creatures that can be killed have been killed, any remaining damage is distributed among the survivors equally.</p>\n      <p>The character has utter control over the vermin in his or her aura, and can force them into areas that would normally deter common vermin. The character can completely suppress his or her vermin aura as a free action so that no vermin are visible at all. The time that vermin are suppressed does not count toward the spell\'s duration. Alternatively, the character can roughly shape and move the vermin in any fashion he or she desires within the limits of the 10-foot-radius spread as a move-equivalent action. The vermin cannot be wrested from the character\'s control through any means. The vermin make all saving throws to avoid damaging effects using the character\'s base saving throw bonuses. They gain the character\'s spell resistance, if any, and they get saving throws against spells that would otherwise automatically slay vermin. A character can see through his or her <i>crown of vermin</i> without difficulty, but gains one-half concealment against enemy attacks launched both outside and within the character\'s <i>crown of vermin</i>.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Crown of Vermin\" level=\"5\"><p><h5>Crown of Vermin</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Summoning)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>56<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 minute<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>Aura of one thousand insects that surrounds you in a 10-ft. -radius spread<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>20 rounds (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None (see text)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>To Develop:</b><br/></td><td>504,000 gp; 11 days; 20,160 XP. Seeds: summon (DC 14), fortify (DC 17). Factors: summon vermin mass instead of one creature (ad hoc +8 DC), grant damage reduction 1/epic (+15 DC), allow mass to move at your speed (ad hoc +2 DC), perfect control of vermin (ad hoc +2 DC). Mitigating factor: change range to personal (-2 DC).<br/></td></tr></table><p>After casting <i>crown of vermin</i>,  one thousand venomous, biting and stinging spiders, scorpions, beetles, and centipedes erupt from the very air around the character. This swarm forms a living aura around the character to a radius of 10 feet. The character is immune to his or her own <i>crown of vermin</i>. The swarm goes where the character goes at his or her speed, even if the character takes to the air or water (though water drowns the vermin after 1 full round of immersion, unless the spell is cast underwater, in which case aquatic or marine vermin answer the call and cannot leave the water). Each vermin in the <i>crown of vermin</i> bites a creature who enters the area occupied by the effect (or the character forces the effect into an area occupied by another creature) for 1 point of damage, and then dies. Each victim takes enough points of damage to kill it, destroying that number of vermin in the process. Victims get a Reflex saving throw each round to avoid the full press, and if successful, take only 10d10 bites (and 10d10 points of damage). A total of 1,000 points of damage can be dealt to those who fall prey to the <i>crown of vermin</i>. The vermin have damage reduction 1/epic, so the vermin\'s natural weapons are treated as epic for the purpose of overcoming damage reduction. If there aren\'t enough vermin to kill all the creatures in the spell\'s effect, the creature with the fewest hit points is affected first, then the creature with the second fewest hit points, and so on. After all creatures that can be killed have been killed, any remaining damage is distributed among the survivors equally.</p><p>The character has utter control over the vermin in his or her aura, and can force them into areas that would normally deter common vermin. The character can completely suppress his or her vermin aura as a free action so that no vermin are visible at all. The time that vermin are suppressed does not count toward the spell\'s duration. Alternatively, the character can roughly shape and move the vermin in any fashion he or she desires within the limits of the 10-foot-radius spread as a move-equivalent action. The vermin cannot be wrested from the character\'s control through any means. The vermin make all saving throws to avoid damaging effects using the character\'s base saving throw bonuses. They gain the character\'s spell resistance, if any, and they get saving throws against spells that would otherwise automatically slay vermin. A character can see through his or her <i>crown of vermin</i> without difficulty, but gains one-half concealment against enemy attacks launched both outside and within the character\'s <i>crown of vermin</i>.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (20,'Damnation','damnation','Enchantment [Mind-Affecting]','Compulsion','Teleportation','97',NULL,'V, S, XP','1 standard action',NULL,'Creature touched',NULL,NULL,'Instantaneous (20 hours for compulsion)','Will negates (see text)','Yes',NULL,'873,000 gp; 18 days; 34,920 XP. Seeds: foresee (to preview likely hellscape) (DC 17), Transport (DC 27), compel (to keep target in hell) (DC 19). Factors: interplanar travel (+4 DC), unwilling target (+4 DC), 1-action casting time (+20 DC), +15 to DC of subject\'s save (+30 DC). Mitigating factor: burn 2,400 XP (-24 DC).',NULL,NULL,NULL,'\n      <p>The character sends his or her foe to hell. If the character succeeds at a melee touch attack, the target must succeed at a Will saving throw (DC = the standard epic spell DC + 15). If he or she fails this saving throw, he or she is sent straight to a layer of a lawful evil plane (or a chaotic evil plane, at the character\'s option) swarming with fiends. The subject will not willingly leave the plane for 20 hours, believing that his or her predicament is a just reward for an ill-spent life. Even after the compulsion fades, he or she must devise his or her own escape from the plane. Unless the GM devises a specific location and scenario in the Nine Hells, the subject encounters a group of 1d4 pit fiends (or balors, if in a chaotic evil plane) every hour he or she spends in hell.</p>\n      <p/>\n    ','2,000 XP.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Damnation\" level=\"5\"><p><h5>Damnation</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Enchantment (Compulsion) [Teleportation] [Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>97<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, XP<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous (20 hours for compulsion)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (see text)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>To Develop:</b><br/></td><td>873,000 gp; 18 days; 34,920 XP. Seeds: foresee (to preview likely hellscape) (DC 17), Transport (DC 27), compel (to keep target in hell) (DC 19). Factors: interplanar travel (+4 DC), unwilling target (+4 DC), 1-action casting time (+20 DC), +15 to DC of subject\'s save (+30 DC). Mitigating factor: burn 2,400 XP (-24 DC).<br/></td></tr></table><p>The character sends his or her foe to hell. If the character succeeds at a melee touch attack, the target must succeed at a Will saving throw (DC = the standard epic spell DC + 15). If he or she fails this saving throw, he or she is sent straight to a layer of a lawful evil plane (or a chaotic evil plane, at the character\'s option) swarming with fiends. The subject will not willingly leave the plane for 20 hours, believing that his or her predicament is a just reward for an ill-spent life. Even after the compulsion fades, he or she must devise his or her own escape from the plane. Unless the GM devises a specific location and scenario in the Nine Hells, the subject encounters a group of 1d4 pit fiends (or balors, if in a chaotic evil plane) every hour he or she spends in hell.</p><p><i>XP Cost:</i> 2,000 XP.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (21,'Demise Unseen','demise unseen','Necromancy, Illusion (Figment)','Death, Evil',NULL,'80',NULL,'V, S','1 standard action','300 ft.','One creature of up to 80 HD',NULL,NULL,'Instantaneous','Fort negates','Yes',NULL,'738,000 gp; 15 days; 29,520 XP. Seeds: Slay (DC 25), animate dead (DC 23), delude (DC 14). Factors: change undead type to ghoul (-10 DC), apply to all five senses (+8 DC), 1-action casting time (+20 DC).',NULL,NULL,NULL,'\n      <p>The character instantly slays a single target and at the same moment animate the body so that it appears that nothing has happened to the creature. The target\'s companions (if any) do not immediately realize what has transpired. The target receives a Fortitude saving throw to survive the attack. If the save fails, the target remains in its exact position with no apparent ill effects. In reality, it is now a ghoul under the character\'s control. The target\'s companions notice nothing unusual about the state of the target until they interact with it, at which time each companion receives a Will saving throw to notice discrepancies. The ghoul serves the character indefinitely. The character cannot exceed the normal limit for controlling undead through use of this spell, but other means that allow the character to exceed the normal limit for controlled undead work just as well with undead created with <i>demise unseen</i>.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Demise Unseen\" level=\"5\"><p><h5>Demise Unseen</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Necromancy (Death, Evil), Illusion (Figment)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>80<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>300 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One creature of up to 80 HD<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Fort negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>To Develop:</b><br/></td><td>738,000 gp; 15 days; 29,520 XP. Seeds: Slay (DC 25), animate dead (DC 23), delude (DC 14). Factors: change undead type to ghoul (-10 DC), apply to all five senses (+8 DC), 1-action casting time (+20 DC).<br/></td></tr></table><p>The character instantly slays a single target and at the same moment animate the body so that it appears that nothing has happened to the creature. The target\'s companions (if any) do not immediately realize what has transpired. The target receives a Fortitude saving throw to survive the attack. If the save fails, the target remains in its exact position with no apparent ill effects. In reality, it is now a ghoul under the character\'s control. The target\'s companions notice nothing unusual about the state of the target until they interact with it, at which time each companion receives a Will saving throw to notice discrepancies. The ghoul serves the character indefinitely. The character cannot exceed the normal limit for controlling undead through use of this spell, but other means that allow the character to exceed the normal limit for controlled undead work just as well with undead created with <i>demise unseen</i>.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (22,'Dire Winter','dire winter','Evocation',NULL,'Cold','319',NULL,'V, S, XP','1 minute','1,000 ft.',NULL,'1,000-ft. -radius emanation',NULL,'20 hours','None','None',NULL,'2,871,000 gp; 58 days; 114,840 XP. Seed: energy (emanate 2d6 cold in 10-ft. radius) (DC 19). Factor: 100 times increase in base area (+400 DC). Mitigating factor: burn 10,000 XP (-100 DC).',NULL,NULL,NULL,'\n      <p>The creature or object targeted emanates bitter cold to a radius of 1,000 feet for 20 hours. The emanated cold deals 2d6 points of damage per round against unprotected creatures (the target is susceptible if not magically protected or otherwise resistant to the energy). The intense cold freezes water out of the air, causing constant snowfall and wind. The snow and wind produce a blizzard effect within the area.</p>\n      <p/>\n    ','10,000 XP.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Dire Winter\" level=\"5\"><p><h5>Dire Winter</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Cold]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>319<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, X P<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 minute<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>1,000 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>1,000-ft. -radius emanation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>20 hours<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>To Develop:</b><br/></td><td>2,871,000 gp; 58 days; 114,840 XP. Seed: energy (emanate 2d6 cold in 10-ft. radius) (DC 19). Factor: 100 times increase in base area (+400 DC). Mitigating factor: burn 10,000 XP (-100 DC).<br/></td></tr></table><p>The creature or object targeted emanates bitter cold to a radius of 1,000 feet for 20 hours. The emanated cold deals 2d6 points of damage per round against unprotected creatures (the target is susceptible if not magically protected or otherwise resistant to the energy). The intense cold freezes water out of the air, causing constant snowfall and wind. The snow and wind produce a blizzard effect within the area.</p><p><i>XP Cost:</i> 10,000 XP.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (23,'Dragon Knight (Ritual)','dragon knight (ritual)','Conjuration','Summoning','Fire','38',NULL,'V, S, Ritual','1 standard action','75 ft.',NULL,NULL,'One summoned adult red dragon','20 rounds (D)','None (see text)','No',NULL,'342,000 gp; 7 days; 13,680 XP. Seed: summon (DC 14). Factors: summon creature other than outsider (+10 DC), summon CR 14 creature (+24 DC), 1-action casting time (+20 DC). Mitigating factor: two additional casters contributing 8th-level spell slots (-30 DC).',NULL,NULL,NULL,'\n      <p>This spell summons an adult red dragon. It appears where the character designates and acts immediately. It attacks the character\'s opponents to the best of its abilities (on the first round, it prefers to breathe fire on an enemy, if possible). The character can direct the dragon not to attack, to attack particular enemies, or to perform other actions. This is a ritual spell requiring two other spellcasters, each of which must contribute an unused 8th-level spell slot to the casting.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Dragon Knight\" level=\"5\"><p><h5>Dragon Knight (Ritual)</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Summoning) [Fire]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>38<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, Ritual<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>75 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>One summoned adult red dragon<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>20 rounds (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None (see text)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>To Develop:</b><br/></td><td>342,000 gp; 7 days; 13,680 XP. Seed: summon (DC 14). Factors: summon creature other than outsider (+10 DC), summon CR 14 creature (+24 DC), 1-action casting time (+20 DC). Mitigating factor: two additional casters contributing 8th-level spell slots (-30 DC).<br/></td></tr></table><p>This spell summons an adult red dragon. It appears where the character designates and acts immediately. It attacks the character\'s opponents to the best of its abilities (on the first round, it prefers to breathe fire on an enemy, if possible). The character can direct the dragon not to attack, to attack particular enemies, or to perform other actions. This is a ritual spell requiring two other spellcasters, each of which must contribute an unused 8th-level spell slot to the casting.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (24,'Dragon Strike (Ritual)','dragon strike (ritual)','Conjuration','Summoning','Fire','50',NULL,'V, S, Ritual, XP','1 standard action','75 ft.',NULL,NULL,'Ten summoned adult red dragons','20 rounds (D)','None (see text)','No',NULL,'450,000 gp; 9 days; 18,000 XP. Seed: summon (DC 14). Factors: summon creature other than outsider (+10 DC), summon CR 14 creature (+24 DC), summon ten creatures (x10 DC), 1-action casting time (+20 DC). Mitigating factors: eleven additional casters contributing 9th-level spell slots (-187 DC), burn 2,000 XP per caster (-240 DC), 3d6 backlash (_3 DC).',NULL,NULL,NULL,'\n      <p>This spell summons ten adult red dragons. They appear where the character designates and act immediately. They attack the character\'s opponents to the best of their abilities (on the first round, they all prefer to simultaneously breathe fire on an enemy, if possible). The character can direct the dragons not to attack, to attack particular enemies, or to perform other actions.</p>\n      <p/>\n    ','2,000 XP (per caster).',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Dragon Strike\" level=\"5\"><p><h5>Dragon Strike (Ritual)</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Summoning) [Fire]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>50<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, Ritual, XP<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>75 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>Ten summoned adult red dragons<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>20 rounds (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None (see text)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>To Develop:</b><br/></td><td>450,000 gp; 9 days; 18,000 XP. Seed: summon (DC 14). Factors: summon creature other than outsider (+10 DC), summon CR 14 creature (+24 DC), summon ten creatures (x10 DC), 1-action casting time (+20 DC). Mitigating factors: eleven additional casters contributing 9th-level spell slots (-187 DC), burn 2,000 XP per caster (-240 DC), 3d6 backlash (_3 DC).<br/></td></tr></table><p>This spell summons ten adult red dragons. They appear where the character designates and act immediately. They attack the character\'s opponents to the best of their abilities (on the first round, they all prefer to simultaneously breathe fire on an enemy, if possible). The character can direct the dragons not to attack, to attack particular enemies, or to perform other actions.</p><p><i>XP Cost:</i> 2,000 XP (per caster).</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (25,'Dreamscape','dreamscape','Conjuration',NULL,'Teleportation','29',NULL,'V, S','1 minute','Touch','You and other touched willing creatures weighing up to 1,000 lb.',NULL,NULL,'Instantaneous (D)','Yes (harmless) (see text)','Yes (harmless)',NULL,'261,000 gp; 6 days; 10,400 XP. Seed: Transport (DC 27). Factor: transport to region of dreams (+2 DC).',NULL,NULL,NULL,'\n      <p>The character and any creatures he or she touches are drawn into the region of dreams. The character can take more than one creature along (subject to the character\'s weight limit), but all must be touching each other. The character physically enters the land of dreams, leaving nothing behind. For every minute the character moves through the dream landscape, he or she can \'wake\' to find him or her self five miles displaced in the waking world. The character does not know precisely where he or she will come out in the waking world, nor the conditions of the waking world through which the character travels. The character knows approximately where he or she will end up based on time spent traveling in dream. <i>Dreamscape</i> can also be used to travel to other planes that contain creatures that dream, but doing this requires crossing into the dreams of outsiders, where the character is subject to the dangers of alien dream realities. This is a potentially perilous proposition. Transferring to another plane of existence requires 1d4 hours of uninterrupted journey. Any creatures touched by the character when <i>Dreamscape</i> is cast also make the transition to the borders of unconscious thought. They may opt to follow the character, wander off into the dreams of others, or stumble back into the waking world (50% chance for either of the latter results if they are lost or abandoned by the character). Creatures unwilling to accompany the character into the region of dreams receive a Will save, negating the effect if successful.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Dreamscape\" level=\"5\"><p><h5>Dreamscape</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration [Teleportation]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>29<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 minute<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You and other touched willing creatures weighing up to 1,000 lb.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Yes (harmless) (see text) <br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>To Develop:</b><br/></td><td>261,000 gp; 6 days; 10,400 XP. Seed: Transport (DC 27). Factor: transport to region of dreams (+2 DC).<br/></td></tr></table><p>The character and any creatures he or she touches are drawn into the region of dreams. The character can take more than one creature along (subject to the character\'s weight limit), but all must be touching each other. The character physically enters the land of dreams, leaving nothing behind. For every minute the character moves through the dream landscape, he or she can \'wake\' to find him or her self five miles displaced in the waking world. The character does not know precisely where he or she will come out in the waking world, nor the conditions of the waking world through which the character travels. The character knows approximately where he or she will end up based on time spent traveling in dream. <i>Dreamscape</i> can also be used to travel to other planes that contain creatures that dream, but doing this requires crossing into the dreams of outsiders, where the character is subject to the dangers of alien dream realities. This is a potentially perilous proposition. Transferring to another plane of existence requires 1d4 hours of uninterrupted journey. Any creatures touched by the character when <i>Dreamscape</i> is cast also make the transition to the borders of unconscious thought. They may opt to follow the character, wander off into the dreams of others, or stumble back into the waking world (50% chance for either of the latter results if they are lost or abandoned by the character). Creatures unwilling to accompany the character into the region of dreams receive a Will save, negating the effect if successful.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (26,'Eclipse','eclipse','Conjuration','Creation','Transportation','42',NULL,'V, S, XP','10 minutes','200 miles',NULL,'5-mile radius, centered on you',NULL,'Up to 8 hours (D)','None','No',NULL,'378,000 gp; 8 days; 15,1200 XP. Seeds: Conjure (DC 21), Transport (to move disk into position 100 miles up) (DC 27). Factors: increase mass by 1,000% (+40 DC), spread mass into paper-thin disk (ad hoc +2 DC), keep disk in place for 8 hours (ad hoc +10 DC). Mitigating factors: increase casting time by 9 minutes (-18 DC), burn 4,000 XP (-40 DC).',NULL,NULL,NULL,'\n      <p>With this spell, the character can create a limited eclipse, as though a heavenly body moves between the sun and the earth. The landscape within a five-mile radius of the character\'s location experiences the dimming of the sun as a disk the character creates passes in front of it, culminating in a complete blackout and accompanying coronal ring. The eclipse follows the character across the landscape for up to 8 hours, or until the sun goes down, or until the character dismisses the eclipse. The character does not need to concentrate on the eclipse while it lasts.</p>\n      <p/>\n    ','4,000 XP.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Eclipse\" level=\"5\"><p><h5>Eclipse</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Creation) [Transportation]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>42<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, X P<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>10 minutes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>200 miles<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>5-mile radius, centered on you<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Up to 8 hours (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>To Develop:</b><br/></td><td>378,000 gp; 8 days; 15,1200 XP. Seeds: Conjure (DC 21), Transport (to move disk into position 100 miles up) (DC 27). Factors: increase mass by 1,000% (+40 DC), spread mass into paper-thin disk (ad hoc +2 DC), keep disk in place for 8 hours (ad hoc +10 DC). Mitigating factors: increase casting time by 9 minutes (-18 DC), burn 4,000 XP (-40 DC).<br/></td></tr></table><p>With this spell, the character can create a limited eclipse, as though a heavenly body moves between the sun and the earth. The landscape within a five-mile radius of the character\'s location experiences the dimming of the sun as a disk the character creates passes in front of it, culminating in a complete blackout and accompanying coronal ring. The eclipse follows the character across the landscape for up to 8 hours, or until the sun goes down, or until the character dismisses the eclipse. The character does not need to concentrate on the eclipse while it lasts.</p><p><i>XP Cost:</i> 4,000 XP.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (27,'Eidolon','eidolon','Conjuration','Creation','Transportation','79',NULL,'V, S, XP','1 minute','5 ft.',NULL,NULL,'One duplicate of caster','8 hours','None','No',NULL,'711,000 gp; 15 days; 28,440 XP. Seed: Conjure (to make base substance) (DC 21), transform (DC 21), Transport (to move part of caster\'s soul into duplicate) (DC 27). Factors: nonliving substance to humanoid (+10 DC), transform into specific individual (+25 DC). Mitigating factor: burn 2,500 XP (-25 DC).',NULL,NULL,NULL,'\n      <p>Upon casting <i>eidolon</i>,  the character creates a duplicate version of him or her self as the character was when he or she was a 21st-level character, and the character gains one negative level while the duplicate persists. For each additional negative level the character bestow upon him or her self at the time of casting, the eidolon has one additional character level. No matter how many negative levels the character bestows on him or her self, the eidolon can never have more character levels than the character has (taking the negative levels into account). Treat the duplicate as the character with a number of negative levels conferred that would lower him or her to the character level of the eidolon. The eidolon is considered fresh and rested when created. It may cast any spell the character has access to, including an epic spell. Use the eidolon\'s Spellcraft modifier as the basis for the number of epic spells it can cast in a day, and its effective character level as a basis for its skills, feats, and other abilities. The eidolon is effectively lower level than the character and probably can\'t cast all the spells he or she knows. A powerful enough eidolon might conceivably cast the <i>eidolon</i> spell itself. The eidolon appears in whatever mundane clothing the character desires when initially conjured, but it has no other possessions. It shares part of the character\'s soul, so it is the character for all intents and purposes. The character and his or her <i>eidolon</i> communicate with each other normally. Usually, the eidolon does not begrudge its brief existence, because it is still part of the character. If the eidolon is killed prior to the expiration of the spell\'s duration, the character immediately regains the lost levels. Normally, the eidolon does not last long enough to threaten the character with permanent level drain.</p>\n      <p/>\n    ','2,500 XP.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Eidolon\" level=\"5\"><p><h5>Eidolon</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Creation) [Transportation]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>79<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, X P<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 minute<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>5 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>One duplicate of caster<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>8 hours<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>To Develop:</b><br/></td><td>711,000 gp; 15 days; 28,440 XP. Seed: Conjure (to make base substance) (DC 21), transform (DC 21), Transport (to move part of caster\'s soul into duplicate) (DC 27). Factors: nonliving substance to humanoid (+10 DC), transform into specific individual (+25 DC). Mitigating factor: burn 2,500 XP (-25 DC).<br/></td></tr></table><p>Upon casting <i>eidolon</i>,  the character creates a duplicate version of him or her self as the character was when he or she was a 21st-level character, and the character gains one negative level while the duplicate persists. For each additional negative level the character bestow upon him or her self at the time of casting, the eidolon has one additional character level. No matter how many negative levels the character bestows on him or her self, the eidolon can never have more character levels than the character has (taking the negative levels into account). Treat the duplicate as the character with a number of negative levels conferred that would lower him or her to the character level of the eidolon. The eidolon is considered fresh and rested when created. It may cast any spell the character has access to, including an epic spell. Use the eidolon\'s Spellcraft modifier as the basis for the number of epic spells it can cast in a day, and its effective character level as a basis for its skills, feats, and other abilities. The eidolon is effectively lower level than the character and probably can\'t cast all the spells he or she knows. A powerful enough eidolon might conceivably cast the <i>eidolon</i> spell itself. The eidolon appears in whatever mundane clothing the character desires when initially conjured, but it has no other possessions. It shares part of the character\'s soul, so it is the character for all intents and purposes. The character and his or her <i>eidolon</i> communicate with each other normally. Usually, the eidolon does not begrudge its brief existence, because it is still part of the character. If the eidolon is killed prior to the expiration of the spell\'s duration, the character immediately regains the lost levels. Normally, the eidolon does not last long enough to threaten the character with permanent level drain.</p><p><i>XP Cost:</i> 2,500 XP.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (28,'Enslave (Ritual)','enslave (ritual)','Enchantment','Compulsion','Mind-Affecting','80',NULL,'V, S, XP','1 standard action','75 ft.','One living creature',NULL,NULL,'Permanent','Will negates','Yes',NULL,'720,000 gp; 15 days; 28,800 XP. Seed: compel (DC 19). Factors: stricter compulsion of any creature (ad hoc +11 DC), 1-action casting time (+20 DC), permanent (x5 DC). Mitigating factors: 2d6 backlash (-2 DC), four additional casters contributing one 9th-level spell slot (-68 DC), burn 2,000 XP per caster (-100 DC).',NULL,NULL,NULL,'\n      <p>The character makes a permanent thrall of any living creature. The character establishes a telepathic link with the subject\'s mind. If the creature has a language, the character can generally force the subject to perform as he or she desires, within the limits of its abilities. If the creature has no language, the character can communicate only basic commands. The character knows what the subject is experiencing, but does not receive direct sensory input from it. A subject forced to take an action against its nature receives a saving throw with a penalty of -10 to resist taking that particular action, but if it succeeds, it still remains the character\'s thrall despite its minor mutiny. Once a subject makes a successful saving throw to resist a specific order, it makes all future saving throws to resist taking that specific action without a penalty. <i>Protection from evil</i> or a similar spell can prevent the character from exercising control or using the telepathic link while the subject is so protected, but it does not prevent the establishment of <i>enslave</i> or dispel it.</p>\n      <p/>\n    ','2,000 XP.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Enslave\" level=\"5\"><p><h5>Enslave (Ritual)</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Enchantment (Compulsion) [Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>80<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, XP<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>75 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One living creature<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Permanent<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>To Develop:</b><br/></td><td>720,000 gp; 15 days; 28,800 XP. Seed: compel (DC 19). Factors: stricter compulsion of any creature (ad hoc +11 DC), 1-action casting time (+20 DC), permanent (x5 DC). Mitigating factors: 2d6 backlash (-2 DC), four additional casters contributing one 9th-level spell slot (-68 DC), burn 2,000 XP per caster (-100 DC).<br/></td></tr></table><p>The character makes a permanent thrall of any living creature. The character establishes a telepathic link with the subject\'s mind. If the creature has a language, the character can generally force the subject to perform as he or she desires, within the limits of its abilities. If the creature has no language, the character can communicate only basic commands. The character knows what the subject is experiencing, but does not receive direct sensory input from it. A subject forced to take an action against its nature receives a saving throw with a penalty of -10 to resist taking that particular action, but if it succeeds, it still remains the character\'s thrall despite its minor mutiny. Once a subject makes a successful saving throw to resist a specific order, it makes all future saving throws to resist taking that specific action without a penalty. <i>Protection from evil</i> or a similar spell can prevent the character from exercising control or using the telepathic link while the subject is so protected, but it does not prevent the establishment of <i>enslave</i> or dispel it.</p><p><i>XP Cost:</i> 2,000 XP.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (29,'Epic Counterspell','epic counterspell','Abjuration',NULL,NULL,'69',NULL,'V, S','1 standard action','300 ft.','One creature or object',NULL,NULL,'Instantaneous','None','No',NULL,'621,000 gp; 13 days; 24,840 XP. Seed: Dispel (DC 19). Factors: +30 to dispel check (+30 DC), 1-action casting time (+20 DC).',NULL,NULL,NULL,'\n      <p>To use <i>epic counterspell</i>, select an opponent as the target. The character does this by readying an action, electing to wait to complete his or her action until the opponent tries to cast a spell (the character may still move his or her speed, because readying a counterspell is a standard action). If the target tries to cast a spell, make a dispel check: Roll d20+40 against a DC of 11 + the foe\'s caster level. If the check is successful, the character\'s spell negates the foe\'s spell.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Epic Counterspell\" level=\"5\"><p><h5>Epic Counterspell</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Abjuration<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>69<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>300 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One creature or object<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>To Develop:</b><br/></td><td>621,000 gp; 13 days; 24,840 XP. Seed: Dispel (DC 19). Factors: +30 to dispel check (+30 DC), 1-action casting time (+20 DC).<br/></td></tr></table><p>To use <i>epic counterspell</i>, select an opponent as the target. The character does this by readying an action, electing to wait to complete his or her action until the opponent tries to cast a spell (the character may still move his or her speed, because readying a counterspell is a standard action). If the target tries to cast a spell, make a dispel check: Roll d20+40 against a DC of 11 + the foe\'s caster level. If the check is successful, the character\'s spell negates the foe\'s spell.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (30,'Epic Mage Armor','epic mage armor','Conjuration','Creation','Force','46',NULL,'V, S','1 minute','Touch','Creature touched',NULL,NULL,'24 hours (D)','Will negates (harmless)','Yes (harmless)',NULL,'414,000 gp; 9 days; 16,560 XP. Seed: Armor (DC 14). Factor: +16 additional armor bonus (+32 DC).',NULL,NULL,NULL,'\n      <p>An invisible but tangible field of force surrounds the subject of <i>epic mage armor</i>,  providing a +20 armor bonus to Armor Class. Unlike mundane armor, <i>epic mage armor</i> entails no armor check penalty, arcane spell failure chance, or speed reduction. Because <i>epic mage armor</i> is made of force, incorporeal creatures can\'t bypass it the way they do normal armor.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Epic Mage Armor\" level=\"5\"><p><h5>Epic Mage Armor</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Creation) [Force]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>46<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 minute<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>24 hours (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>To Develop:</b><br/></td><td>414,000 gp; 9 days; 16,560 XP. Seed: Armor (DC 14). Factor: +16 additional armor bonus (+32 DC).<br/></td></tr></table><p>An invisible but tangible field of force surrounds the subject of <i>epic mage armor</i>,  providing a +20 armor bonus to Armor Class. Unlike mundane armor, <i>epic mage armor</i> entails no armor check penalty, arcane spell failure chance, or speed reduction. Because <i>epic mage armor</i> is made of force, incorporeal creatures can\'t bypass it the way they do normal armor.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (31,'Epic Repulsion','epic repulsion','Abjuration',NULL,NULL,'52',NULL,'V, S','10 minutes','Touch','Object or creature touched',NULL,NULL,'Permanent','None','Yes',NULL,'468,000 gp; 10 days; 18,720 XP. Seed: Ward (DC 14). Factor: permanent 5 DC). Mitigating factor: increase casting time by 9 minutes (-18 DC).',NULL,NULL,NULL,'\n      <p>The character can create a permanent ward against a specific creature type. Any creature of the specified type cannot attack or touch the warded creature or object. The protection ends if the warded creature makes an attack against or intentionally moves to within 5 feet of a specified creature. Spell resistance can allow a creature to overcome this protection and touch the warded creature.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Epic Repulsion\" level=\"5\"><p><h5>Epic Repulsion</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Abjuration<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>52<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>10 minutes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Object or creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Permanent<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>To Develop:</b><br/></td><td>468,000 gp; 10 days; 18,720 XP. Seed: Ward (DC 14). Factor: permanent 5 DC). Mitigating factor: increase casting time by 9 minutes (-18 DC).<br/></td></tr></table><p>The character can create a permanent ward against a specific creature type. Any creature of the specified type cannot attack or touch the warded creature or object. The protection ends if the warded creature makes an attack against or intentionally moves to within 5 feet of a specified creature. Spell resistance can allow a creature to overcome this protection and touch the warded creature.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (32,'Epic Spell Reflection','epic spell reflection','Abjuration',NULL,NULL,'68',NULL,'V, S, XP','41 days, 11 minutes','Touch','Object or creature touched',NULL,NULL,'Permanent','None','Yes',NULL,'630,000 gp; 13 days; 25,200 XP. Seed: reflect (DC 27). Factors: reflect up to 9th-level spells (+160 DC), change range to touch (+2 DC), permanent (x5 DC). Mitigating factors: increase casting time by 10 minutes (-20 DC), increase casting time by 41 days (-82 DC), 20d6 backlash (-20 DC), six additional casters contributing one 8th-level spell slot (-90 DC), burn 9,500 XP per caster (-665 DC).',NULL,NULL,NULL,'\n      <p>The character can create a permanent ward against all spells of 1st through 9th level that target the subject. These spells are reflected back on the caster. Spells that affect an area are not affected by this spell.</p>\n      <p/>\n    ','9,500 XP.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Epic Spell Reflection\" level=\"5\"><p><h5>Epic Spell Reflection</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Abjuration<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>68<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, X P<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>41 days, 11 minutes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Object or creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Permanent<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>To Develop:</b><br/></td><td>630,000 gp; 13 days; 25,200 XP. Seed: reflect (DC 27). Factors: reflect up to 9th-level spells (+160 DC), change range to touch (+2 DC), permanent (x5 DC). Mitigating factors: increase casting time by 10 minutes (-20 DC), increase casting time by 41 days (-82 DC), 20d6 backlash (-20 DC), six additional casters contributing one 8th-level spell slot (-90 DC), burn 9,500 XP per caster (-665 DC).<br/></td></tr></table><p>The character can create a permanent ward against all spells of 1st through 9th level that target the subject. These spells are reflected back on the caster. Spells that affect an area are not affected by this spell.</p><p><i>XP Cost:</i> 9,500 XP.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (33,'Eternal Freedom','eternal freedom','Abjuration',NULL,NULL,'150',NULL,'V, S, Ritual, XP','1 minute','Touch','Touched creature or object of 2,000 lb. or less',NULL,NULL,'Permanent','Will negates','Yes',NULL,'1,350,000 gp; 27 days; 54,000 XP. Seed: Ward (DC 14). Factors: specific protections entangle (+0 DC), hold monster (+8 DC), hold person (+4 DC), imprisonment (+16 DC), paralysis (ad hoc +6 DC), petrification (ad hoc +6 DC), sleep (+0 DC), slow (+4 DC), stunning (ad hoc +6 DC), temporal stasis (+16 DC), and web (+4 DC); permanent 5 DC). Mitigating factors: ten additional casters contributing 9th-level spell slots (-170 DC), burn 10,000 XP (-100 DC).',NULL,NULL,NULL,'\n      <p>The subject becomes permanently immune to the following specific spells, effects, and spell-like abilities: <i>entangle</i>, <i>hold</i>, <i>imprisonment</i>, paralysis, petrification, <i>sleep</i>, <i>slow</i>, stunning, <i>temporal stasis</i>, and <i>web</i>. This is a ritual spell requiring ten other spellcasters, each of whom must contribute an unused 9th-level spell slot to the casting.</p>\n      <p/>\n    ','10,000 XP.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Eternal Freedom\" level=\"5\"><p><h5>Eternal Freedom</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Abjuration<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>150<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, Ritual, XP<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 minute<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Touched creature or object of 2,000 lb. or less<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Permanent<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>To Develop:</b><br/></td><td>1,350,000 gp; 27 days; 54,000 XP. Seed: Ward (DC 14). Factors: specific protections entangle (+0 DC), hold monster (+8 DC), hold person (+4 DC), imprisonment (+16 DC), paralysis (ad hoc +6 DC), petrification (ad hoc +6 DC), sleep (+0 DC), slow (+4 DC), stunning (ad hoc +6 DC), temporal stasis (+16 DC), and web (+4 DC); permanent 5 DC). Mitigating factors: ten additional casters contributing 9th-level spell slots (-170 DC), burn 10,000 XP (-100 DC).<br/></td></tr></table><p>The subject becomes permanently immune to the following specific spells, effects, and spell-like abilities: <i>entangle</i>, <i>hold</i>, <i>imprisonment</i>, paralysis, petrification, <i>sleep</i>, <i>slow</i>, stunning, <i>temporal stasis</i>, and <i>web</i>. This is a ritual spell requiring ten other spellcasters, each of whom must contribute an unused 9th-level spell slot to the casting.</p><p><i>XP Cost:</i> 10,000 XP.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (34,'Greater Spell Resistance','greater spell resistance','Transmutation',NULL,NULL,'45',NULL,'V, S, Ritual','1 minute','Touch','Creature touched',NULL,NULL,'20 hours','Will negates (harmless)','Yes (harmless)',NULL,'405,000 gp; 9 days; 16,200 XP. Seed: fortify (DC 27). Factor: +10 additional SR (+40 DC). Mitigating factor: two additional casters contributing 6th-level spell slots (-22 DC).',NULL,NULL,NULL,'\n      <p>The character grants the subject touched spell resistance 35 until the duration expires. The spell resistance granted does not stack, but overlaps with, any previous spell resistance. This is a ritual spell, requiring two other spellcasters, each of whom must contribute an unused 6th-level spell slot to the casting.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Greater Spell Resistance\" level=\"5\"><p><h5>Greater Spell Resistance</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>45<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, Ritual<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 minute<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>20 hours<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>To Develop:</b><br/></td><td>405,000 gp; 9 days; 16,200 XP. Seed: fortify (DC 27). Factor: +10 additional SR (+40 DC). Mitigating factor: two additional casters contributing 6th-level spell slots (-22 DC).<br/></td></tr></table><p>The character grants the subject touched spell resistance 35 until the duration expires. The spell resistance granted does not stack, but overlaps with, any previous spell resistance. This is a ritual spell, requiring two other spellcasters, each of whom must contribute an unused 6th-level spell slot to the casting.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (35,'Greater Ruin','greater ruin','Transmutation',NULL,NULL,'59',NULL,'V, S, XP','1 standard action','12,000 ft.','One creature, or up to a 10-foot cube of nonliving matter',NULL,NULL,'Instantaneous','Fortitude half','Yes',NULL,'531,000 gp; 11 days; 21,240 XP. Seed: Destroy (DC 29). Factors: increase damage to 35d6 (+30 DC), 1-action casting time (+20 DC). Mitigating factor: burn 2,000 XP (-20 DC).',NULL,NULL,NULL,'\n      <p>The character deals 35d6 points of damage to a single target within range and line of sight. If the target is reduced to -10 hit points or less (or a construct, object, or undead is reduced to 0 hit points), it is utterly destroyed as if disintegrated. Only a trace of fine dust remains. <i>XP Cost:</i> 2,000 XP.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Greater Ruin\" level=\"5\"><p><h5>Greater Ruin</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>59<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, X P<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>12,000 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One creature, or up to a 10-foot cube of nonliving matter<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Fortitude half<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>To Develop:</b><br/></td><td>531,000 gp; 11 days; 21,240 XP. Seed: Destroy (DC 29). Factors: increase damage to 35d6 (+30 DC), 1-action casting time (+20 DC). Mitigating factor: burn 2,000 XP (-20 DC).<br/></td></tr></table><p>The character deals 35d6 points of damage to a single target within range and line of sight. If the target is reduced to -10 hit points or less (or a construct, object, or undead is reduced to 0 hit points), it is utterly destroyed as if disintegrated. Only a trace of fine dust remains. <i>XP Cost:</i> 2,000 XP.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (36,'Hellball','hellball','Evocation',NULL,'Acid, Fire, Electricity, Sonic','90',NULL,'V, S, XP','1 standard action','300 ft.',NULL,'40-ft. -radius spread',NULL,'Instantaneous','Reflex half','Yes',NULL,'810,000 gp; 17 days; 32,400 XP. Seed: energy (deals 10d6 each of acid, fire, electricity, sonic) (DC 76). Factors: double base area (+6 DC), 1-action casting time (+20 DC). Mitigating factors: 10d6 backlash (-10 DC), burn 200 XP (-2 DC).',NULL,NULL,NULL,'\n      <p>A <i>hellball</i> deals 10d6 points of acid damage, 10d6 points of fire damage, 10d6 points of electricity damage, and 10d6 points of sonic damage to all creatures within the area. Unattended objects also take this damage. The character takes 10d6 points of damage upon casting (in addition to burning 200 XP). The character points his or her finger and determine the range (distance and height) at which the <i>hellball</i> is to detonate. A sun-bright, fist-sized globe of energy streaks forth and, unless it impacts a material body or solid barrier prior to attaining the indicated range, expands into its full area.</p>\n      <p/>\n    ','200 XP.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Hellball\" level=\"5\"><p><h5>Hellball</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Acid, Fire, Electricity, Sonic]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>90<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, X P<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>300 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>40-ft. -radius spread<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Reflex half<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>To Develop:</b><br/></td><td>810,000 gp; 17 days; 32,400 XP. Seed: energy (deals 10d6 each of acid, fire, electricity, sonic) (DC 76). Factors: double base area (+6 DC), 1-action casting time (+20 DC). Mitigating factors: 10d6 backlash (-10 DC), burn 200 XP (-2 DC).<br/></td></tr></table><p>A <i>hellball</i> deals 10d6 points of acid damage, 10d6 points of fire damage, 10d6 points of electricity damage, and 10d6 points of sonic damage to all creatures within the area. Unattended objects also take this damage. The character takes 10d6 points of damage upon casting (in addition to burning 200 XP). The character points his or her finger and determine the range (distance and height) at which the <i>hellball</i> is to detonate. A sun-bright, fist-sized globe of energy streaks forth and, unless it impacts a material body or solid barrier prior to attaining the indicated range, expands into its full area.</p><p><i>XP Cost: 2</i>00 XP.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (37,'Kinetic Control','kinetic control','Abjuration',NULL,NULL,'100',NULL,'V, S','1 minute','Personal; touch','You; creature or object touched',NULL,NULL,'12 hours or until discharged',NULL,NULL,NULL,'927,000 gp; 19 days; 37,080 XP. Seeds: Ward (5 points against bludgeoning and piercing) (DC 14), reflect (DC 27). Factors: also against slashing (+4 DC), additional 15 points of protection (+30 DC), contingent reflection of damage on creature touched (+25 DC).',NULL,NULL,NULL,'\n      <p>Once a character has cast this spell, he or she can absorb, store, and redirect the energy contained in any physical (melee or ranged) attack. The character absorbs 20 points of each separate slashing, bludgeoning, and piercing attack made against him or her, saving it for later. A character can absorb up to 150 points of damage in this fashion; however, if the stored damage is not discharged prior to reaching the 150-point limit, the spell automatically discharges, dealing the 150 points of damage to the character. The character keeps track of the number of points of damage he or she has absorbed (the character doesn\'t have to keep track of the type of damage). At any time during the spell\'s duration, the character can make a touch attack against another creature or object. If successful, the character deals the target some or all (character\'s choice) of the points of damage he or she has stored. The damage delivered is considered bludgeoning damage. A character can absorb and discharge damage any number of times during the spell\'s duration, so long as the character doesn\'t absorb more than 150 points at a time. When the spell expires, any stored damage the character has not redirected is discharged into the character.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Kinetic Control\" level=\"5\"><p><h5>Kinetic Control</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Abjuration<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>100<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 minute<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal; touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You; creature or object touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>12 hours or until discharged<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>To Develop:</b><br/></td><td>927,000 gp; 19 days; 37,080 XP. Seeds: Ward (5 points against bludgeoning and piercing) (DC 14), reflect (DC 27). Factors: also against slashing (+4 DC), additional 15 points of protection (+30 DC), contingent reflection of damage on creature touched (+25 DC).<br/></td></tr></table><p>Once a character has cast this spell, he or she can absorb, store, and redirect the energy contained in any physical (melee or ranged) attack. The character absorbs 20 points of each separate slashing, bludgeoning, and piercing attack made against him or her, saving it for later. A character can absorb up to 150 points of damage in this fashion; however, if the stored damage is not discharged prior to reaching the 150-point limit, the spell automatically discharges, dealing the 150 points of damage to the character. The character keeps track of the number of points of damage he or she has absorbed (the character doesn\'t have to keep track of the type of damage). At any time during the spell\'s duration, the character can make a touch attack against another creature or object. If successful, the character deals the target some or all (character\'s choice) of the points of damage he or she has stored. The damage delivered is considered bludgeoning damage. A character can absorb and discharge damage any number of times during the spell\'s duration, so long as the character doesn\'t absorb more than 150 points at a time. When the spell expires, any stored damage the character has not redirected is discharged into the character.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (38,'Let Go of Me','let go of me','Transmutation',NULL,NULL,'43',NULL,'None','1 free action','Touch (see text)','One creature or force grappling you',NULL,NULL,'Instantaneous','Fortitude half','Yes',NULL,'387,000 gp; 8 days; 15,480 XP. Seed: Destroy (DC 29). Factors: quickened (+28 DC), no verbal or somatic components (+4 DC). Mitigating factors: limited circumstance (ad hoc -8 DC), 10d6 backlash (-10 DC).',NULL,NULL,NULL,'\n      <p>The character deals 20d6 points of damage to any creature grappling him or her. The damage dealt is of no particular type or energy-it is a purely destructive impulse. If grappled by a magical force the force is automatically destroyed.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Let Go of Me\" level=\"5\"><p><h5>Let Go of Me</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>43<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 free action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch (see text)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One creature or force grappling you<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Fortitude half<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>To Develop:</b><br/></td><td>387,000 gp; 8 days; 15,480 XP. Seed: Destroy (DC 29). Factors: quickened (+28 DC), no verbal or somatic components (+4 DC). Mitigating factors: limited circumstance (ad hoc -8 DC), 10d6 backlash (-10 DC).<br/></td></tr></table><p>The character deals 20d6 points of damage to any creature grappling him or her. The damage dealt is of no particular type or energy-it is a purely destructive impulse. If grappled by a magical force the force is automatically destroyed.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (39,'Living Lightning','living lightning','Evocation',NULL,'Electricity','140',NULL,'None','1 standard action','300 ft. or 150 ft.',NULL,'A bolt 5 ft. wide by 300 ft. long, or 10 ft. wide by 150 ft. long',NULL,'Instantaneous','Reflex half','Yes',NULL,'1,260,000 gp; 26 days; 50,400 XP. Seeds: life (DC 27), energy (DC 19). Factors: 1-action casting time (+20 DC), no verbal or somatic components (+4 DC), giving life to a spell (ad hoc x2 DC).',NULL,NULL,NULL,'\n      <p>The character develops a spell that he or she can cast; thereafter, the spell can effectively \'cast itself.\' When the character casts the spell, a stroke of energy deals 10d6 points of electricity damage to each creature within the spell\'s area. <i>Living lightning</i> follows all the standard rules for epic spell casting when the character casts it. <i>Living lightning</i> is sentient and generally friendly toward the character. It has the character\'s mental ability scores, but it has no physical ability scores. It senses the world through the character\'s senses and communicates with him or her by thought. As a self-triggering spell, it isn\'t truly alive but is a fragment of the character\'s personality. It cares little for the world around it, but at the character\'s urging (and sometimes at its own discretion) it casts itself at his or her foes. Casters who prepare spells before casting must prepare <i>Living lightning</i> normally in order for it to cast itself. When the spell casts itself, it acts on the character\'s initiative but does not count against his or her own actions in the round. The character cannot simultaneously cast <i>Living lightning</i> while it is casting its own effect, even if it has been prepared more than once. <i>Living lightning</i> uses up one of the character\'s epic spell slots for the day whenever it casts itself. When the character has used up all his or her epic spell slots for the day (or has cast all his or her prepared <i>Living lightning</i> spells, if a caster who must prepare spells), <i>Living lightning</i> becomes quiescent. It remains so until the character has rested to regain his or her epic spell slots for the next day.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Living Lightning\" level=\"5\"><p><h5>Living Lightning</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Electricity]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>140<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>300 ft. or 150 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>A bolt 5 ft. wide by 300 ft. long, or 10 ft. wide by 150 ft. long<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Reflex half<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>To Develop:</b><br/></td><td>1,260,000 gp; 26 days; 50,400 XP. Seeds: life (DC 27), energy (DC 19). Factors: 1-action casting time (+20 DC), no verbal or somatic components (+4 DC), giving life to a spell (ad hoc x2 DC).<br/></td></tr></table><p>The character develops a spell that he or she can cast; thereafter, the spell can effectively \'cast itself.\' When the character casts the spell, a stroke of energy deals 10d6 points of electricity damage to each creature within the spell\'s area. <i>Living lightning</i> follows all the standard rules for epic spell casting when the character casts it. <i>Living lightning</i> is sentient and generally friendly toward the character. It has the character\'s mental ability scores, but it has no physical ability scores. It senses the world through the character\'s senses and communicates with him or her by thought. As a self-triggering spell, it isn\'t truly alive but is a fragment of the character\'s personality. It cares little for the world around it, but at the character\'s urging (and sometimes at its own discretion) it casts itself at his or her foes. Casters who prepare spells before casting must prepare <i>Living lightning</i> normally in order for it to cast itself. When the spell casts itself, it acts on the character\'s initiative but does not count against his or her own actions in the round. The character cannot simultaneously cast <i>Living lightning</i> while it is casting its own effect, even if it has been prepared more than once. <i>Living lightning</i> uses up one of the character\'s epic spell slots for the day whenever it casts itself. When the character has used up all his or her epic spell slots for the day (or has cast all his or her prepared <i>Living lightning</i> spells, if a caster who must prepare spells), <i>Living lightning</i> becomes quiescent. It remains so until the character has rested to regain his or her epic spell slots for the next day.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (40,'Lord of Nightmares','lord of nightmares','Conjuration','Summoning',NULL,'50',NULL,'V, S, XP','1 standard action','75 ft.',NULL,NULL,'One summoned creature','20 rounds','None','No',NULL,'450,000 gp; 9 days; 18,000 XP. Seed: summon (DC 14). Factors: summon CR 31 creature (+58 DC), allow creature to possess body and act at its own discretion (ad hoc -20 DC), 1-action casting time (+20 DC). Mitigating factors: 12d6 backlash (-12 DC), burn 1,000 XP (-10 DC).',NULL,NULL,NULL,'\n      <p>The character is possessed by a dream larva. For 20 rounds, the dream larva\'s body physically replaces the character\'s, though the dream larva has the character\'s equipment. The dream larva is free to call on all its own powers and abilities, or use the character\'s equipment. The character\'s consciousness and physical form are suppressed for the duration of the possession. The character has no way to dismiss the spell, communicate, or otherwise maintain awareness once possession has commenced. The dream larva, temporarily freed from its imprisonment in some distant nightmare, will attempt to slay and incapacitate any creature it can see or find, whether it is a friend or foe of the caster. Casting <i>lord of nightmares</i> entails some risk for the caster, since it\'s unknown what a dream larva might do over the course of 20 rounds. The larva will dispatch all enemies it can find before turning to its own concerns. Sometimes a dream larva will attempt to place itself in a dangerous or precarious situation prior to the end of the spell, leaving the caster to extricate him or herself. If the dream larva is slain during the duration of the spell, the character\'s consciousness is instantly restored to aware-ness within his or her own body. The character\'s condition remains what it was when he or she completed casting <i>lord of nightmares</i>, regardless of what damage the dream larva received. However, magic item charges used, potions consumed, and other physical resources used up by the dream larva are permanent.</p>\n      <p/>\n    ','1,000 XP.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Lord of Nightmares\" level=\"5\"><p><h5>Lord of Nightmares</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Summoning)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>50<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, X P<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>75 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>One summoned creature<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>20 rounds<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>To Develop:</b><br/></td><td>450,000 gp; 9 days; 18,000 XP. Seed: summon (DC 14). Factors: summon CR 31 creature (+58 DC), allow creature to possess body and act at its own discretion (ad hoc -20 DC), 1-action casting time (+20 DC). Mitigating factors: 12d6 backlash (-12 DC), burn 1,000 XP (-10 DC).<br/></td></tr></table><p>The character is possessed by a dream larva. For 20 rounds, the dream larva\'s body physically replaces the character\'s, though the dream larva has the character\'s equipment. The dream larva is free to call on all its own powers and abilities, or use the character\'s equipment. The character\'s consciousness and physical form are suppressed for the duration of the possession. The character has no way to dismiss the spell, communicate, or otherwise maintain awareness once possession has commenced. The dream larva, temporarily freed from its imprisonment in some distant nightmare, will attempt to slay and incapacitate any creature it can see or find, whether it is a friend or foe of the caster. Casting <i>lord of nightmares</i> entails some risk for the caster, since it\'s unknown what a dream larva might do over the course of 20 rounds. The larva will dispatch all enemies it can find before turning to its own concerns. Sometimes a dream larva will attempt to place itself in a dangerous or precarious situation prior to the end of the spell, leaving the caster to extricate him or herself. If the dream larva is slain during the duration of the spell, the character\'s consciousness is instantly restored to aware-ness within his or her own body. The character\'s condition remains what it was when he or she completed casting <i>lord of nightmares</i>, regardless of what damage the dream larva received. However, magic item charges used, potions consumed, and other physical resources used up by the dream larva are permanent.</p><p><i>XP Cost:</i> 1,000 XP.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (41,'Mass Frog','mass frog','Transmutation',NULL,NULL,'55',NULL,'V, S','1 standard action','300 ft.',NULL,'40-ft. -radius hemisphere',NULL,'Permanent','Fortitude negates','Yes',NULL,'495,000 gp; 10 days; 19,800 XP. Seed: transform (DC 21). Factors: change target to area of 20-ft. hemisphere (+10 DC), increase area by 100% (+4 DC), 1 action casting time (+20 DC).',NULL,NULL,NULL,'\n      <p>This epic spell turns all Medium or smaller creatures in the area into frogs. The transformed creatures retain their mental faculties, including personality, Intelligence, Wisdom, and Charisma scores, level and class, hit points (despite any change in Consitution score), alignment, base attack bonus, base save bonuses, extraordinary abilities, spells, and spell-like abilities, but not supernatural abilities. They assume the physical characteristics of frogs, including natural size and Strength, Dexterity, and Constitution scores. (Use the statistics for the toad.) All the creatures\' equipment drops to the ground upon transformation.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Mass Frog\" level=\"5\"><p><h5>Mass Frog</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>55<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>300 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>40-ft. -radius hemisphere<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Permanent<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Fortitude negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>To Develop:</b><br/></td><td>495,000 gp; 10 days; 19,800 XP. Seed: transform (DC 21). Factors: change target to area of 20-ft. hemisphere (+10 DC), increase area by 100% (+4 DC), 1 action casting time (+20 DC).<br/></td></tr></table><p>This epic spell turns all Medium or smaller creatures in the area into frogs. The transformed creatures retain their mental faculties, including personality, Intelligence, Wisdom, and Charisma scores, level and class, hit points (despite any change in Consitution score), alignment, base attack bonus, base save bonuses, extraordinary abilities, spells, and spell-like abilities, but not supernatural abilities. They assume the physical characteristics of frogs, including natural size and Strength, Dexterity, and Constitution scores. (Use the statistics for the toad.) All the creatures\' equipment drops to the ground upon transformation.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (42,'Momento Mori','momento mori','Necromancy',NULL,'Death','86',NULL,'None','1 quickened action','300 ft.','One living creature',NULL,NULL,'Instantaneous','Fortitude partial (see text)','Yes',NULL,'774,000 gp; 16 days; 30,960 XP. Seed: Slay (DC 25). Factor: increase to 160 HD (+8 DC), quickened (+28 DC), no verbal or somatic components (+4 DC), +10 to DC of subject\'s save (+20 DC).',NULL,NULL,NULL,'\n      <p>As a free action that counts as a quickened spell, the character wills the target dead without a word or gesture. The character\'s thought snuffs out the life force of a living creature of 160 or fewer HD, killing it instantly. The subject is entitled to a Fortitude saving throw (DC 30 + relevant ability modifier) to have a chance of surviving the attack. If the save is successful, the target instead takes 3d6+20 points of damage.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Momento Mori\" level=\"5\"><p><h5>Momento Mori</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Necromancy [Death]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>86<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 quickened action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>300 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One living creature<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Fortitude partial (see text)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>To Develop:</b><br/></td><td>774,000 gp; 16 days; 30,960 XP. Seed: Slay (DC 25). Factor: increase to 160 HD (+8 DC), quickened (+28 DC), no verbal or somatic components (+4 DC), +10 to DC of subject\'s save (+20 DC).<br/></td></tr></table><p>As a free action that counts as a quickened spell, the character wills the target dead without a word or gesture. The character\'s thought snuffs out the life force of a living creature of 160 or fewer HD, killing it instantly. The subject is entitled to a Fortitude saving throw (DC 30 + relevant ability modifier) to have a chance of surviving the attack. If the save is successful, the target instead takes 3d6+20 points of damage.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (43,'Mummy Dust','mummy dust','Necromancy',NULL,'Evil','35',NULL,'V, S ,M, XP','1 standard action','Touch',NULL,NULL,'Two 18-HD mummies','Instantaneous','None','No',NULL,'315,000 gp; 7 days; 12,600 XP. Seed: animate dead (DC 23). Factors: 1-action casting time (+20 DC). Mitigating factors: burn 400 XP (-4 DC), expensive material component (ad hoc -4 DC).','Specially prepared mummy dust (10,000 gp).',NULL,NULL,'\n      <p>When the character sprinkles the dust of ground mummies in conjunction with casting <i>mummy dust</i>, two Large 18-HD mummies (see below) spring up from the dust in an area adjacent to the character. The mummies follow the character\'s every command according to their abilities, until they are destroyed or the character loses control of them by attempting to control more Hit Dice of undead than he or she has caster levels.</p>\n      <p>Mummy, Advanced: CR 8; Large undead; HD 18d12+3; hp 120; Init -1; Spd 20 ft.; AC 20, touch 8, flat-footed 20; Base Atk +9; Grp +24; Atk +20 melee (1d8+16 plus mummy rot); Full Atk +20 melee (1d8+16 plus mummy rot); Space/Reach 10 ft./10 ft.; SA Despair, mummy rot; SQ Damage reduction 5/-, darkvision 60 ft., undead traits, vulnerability to fire; AL LE; SV Fort +8, Ref +7, Will +13; Str 32, Dex 8, Con --, Int 6, Wis 14, Cha 15. <i>Skills and Feats:</i> Hide -5, Listen +9, Move Silently +10, Spot +9; Alertness, Blind-Fight, Great Fortitude, Lightning Reflexes, Power Attack, Toughness, Weapon Focus (slam).</p>\n      <p>Despair (Su): At the sight of a mummy, the viewer must succeed at a Will save (DC 21), or be paralyzed with fear for 1d4 rounds. Whether or not the save is successful, that creature cannot be affected again by that mummy\'s despair ability for one day. Mummy Rot (Su): Supernatural disease-slam, Fortitude save (DC 21), incubation period 1 minute; damage 1d6 Con and 1d6 Cha. The save DC is Charisma-based. Unlike normal diseases, mummy rot continues until the victim reaches Constitution 0 (and dies) or is cured as described below.  Mummy rot is a powerful curse, not a natural disease. A character attempting to cast any conjuration (healing) spell on a creature afflicted with mummy rot must succeed on a DC 20 caster level check, or the spell has no effect on the afflicted character. To eliminate mummy rot, the curse must first be broken with <i>break enchantment</i> or <i>remove curse</i> (requiring a DC 20 caster level check for either spell), after which a caster level check is no longer necessary to cast healing spells on the victim, and the mummy rot can be magically cured as any normal disease.</p>\n      <p>An afflicted creature who dies of mummy rot shrivels away into sand and dust that blow away into nothing at the first wind.</p>\n      <p/>\n    ','2,000 XP.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Mummy Dust\" level=\"5\"><p><h5>Mummy Dust</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Necromancy [Evil]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>35<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S ,M, XP<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>Two 18-HD mummies<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>To Develop:</b><br/></td><td>315,000 gp; 7 days; 12,600 XP. Seed: animate dead (DC 23). Factors: 1-action casting time (+20 DC). Mitigating factors: burn 400 XP (-4 DC), expensive material component (ad hoc -4 DC).<br/></td></tr></table><p>When the character sprinkles the dust of ground mummies in conjunction with casting <i>mummy dust</i>, two Large 18-HD mummies (see below) spring up from the dust in an area adjacent to the character. The mummies follow the character\'s every command according to their abilities, until they are destroyed or the character loses control of them by attempting to control more Hit Dice of undead than he or she has caster levels.</p><p><i>Material Component:</i> Specially prepared mummy dust (10,000 gp).</p><p><i>XP Cost:</i> 2,000 XP.</p><p>Mummy, Advanced: CR 8; Large undead; HD 18d12+3; hp 120; Init -1; Spd 20 ft.; AC 20, touch 8, flat-footed 20; Base Atk +9; Grp +24; Atk +20 melee (1d8+16 plus mummy rot); Full Atk +20 melee (1d8+16 plus mummy rot); Space/Reach 10 ft./10 ft.; SA Despair, mummy rot; SQ Damage reduction 5/-, darkvision 60 ft., undead traits, vulnerability to fire; AL LE; SV Fort +8, Ref +7, Will +13; Str 32, Dex 8, Con --, Int 6, Wis 14, Cha 15. <i>Skills and Feats:</i> Hide -5, Listen +9, Move Silently +10, Spot +9; Alertness, Blind-Fight, Great Fortitude, Lightning Reflexes, Power Attack, Toughness, Weapon Focus (slam).</p><p>Despair (Su): At the sight of a mummy, the viewer must succeed at a Will save (DC 21), or be paralyzed with fear for 1d4 rounds. Whether or not the save is successful, that creature cannot be affected again by that mummy\'s despair ability for one day. Mummy Rot (Su): Supernatural disease-slam, Fortitude save (DC 21), incubation period 1 minute; damage 1d6 Con and 1d6 Cha. The save DC is Charisma-based. Unlike normal diseases, mummy rot continues until the victim reaches Constitution 0 (and dies) or is cured as described below.  Mummy rot is a powerful curse, not a natural disease. A character attempting to cast any conjuration (healing) spell on a creature afflicted with mummy rot must succeed on a DC 20 caster level check, or the spell has no effect on the afflicted character. To eliminate mummy rot, the curse must first be broken with <i>break enchantment</i> or <i>remove curse</i> (requiring a DC 20 caster level check for either spell), after which a caster level check is no longer necessary to cast healing spells on the victim, and the mummy rot can be magically cured as any normal disease.</p><p>An afflicted creature who dies of mummy rot shrivels away into sand and dust that blow away into nothing at the first wind.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (44,'Nailed to the Sky','nailed to the sky','Conjuration',NULL,'Teleportation','62',NULL,'V, S ,XP','1 standard action','300 ft.','Creature or object weighing up to 1,000 lb.',NULL,NULL,'Instantaneous','Will negates','Yes',NULL,'558,000 gp; 12 days; 22,320 XP. Seeds: foresee (to preview endpoint of teleportation) (DC 17), Transport (DC 27). Factors: unwilling target (+4 DC), increase range from touch (+4 DC), 1-action casting time (+20 DC). Mitigating factor: burn 1,000 XP (-10 DC).',NULL,NULL,NULL,'\n      <p><i>Nailed to the sky</i> actually places the target so far from the surface of the world and at such a speed that it keeps missing the surface as it falls back, so it enters an eternal orbit. Unless the target can magically fly or has some other form of non-physical propulsion available, the target is stuck until someone else rescues it. Even if the target can fly, the surface is 2 to 4 hours away, assuming a <i>fly</i> spell, which allows a maximum speed of 720 feet per round while descending. The target may not survive that long. Depending on the world where <i>Nailed to the sky</i> is cast, conditions so far from its surface may be deadly. Deleterious effects include scorching heat, cold, and vacuum. Targets subject to these conditions take 2d6 points of damage each from heat or cold and 1d4 points of damage from the vacuum each round. The target immediately begins to suffocate.</p>\n      <p/>\n    ','1,000 XP.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Nailed to the Sky\" level=\"5\"><p><h5>Nailed to the Sky</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration [Teleportation]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>62<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S ,XP<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>300 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Creature or object weighing up to 1,000 lb.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>To Develop:</b><br/></td><td>558,000 gp; 12 days; 22,320 XP. Seeds: foresee (to preview endpoint of teleportation) (DC 17), Transport (DC 27). Factors: unwilling target (+4 DC), increase range from touch (+4 DC), 1-action casting time (+20 DC). Mitigating factor: burn 1,000 XP (-10 DC).<br/></td></tr></table><p><i>Nailed to the sky</i> actually places the target so far from the surface of the world and at such a speed that it keeps missing the surface as it falls back, so it enters an eternal orbit. Unless the target can magically fly or has some other form of non-physical propulsion available, the target is stuck until someone else rescues it. Even if the target can fly, the surface is 2 to 4 hours away, assuming a <i>fly</i> spell, which allows a maximum speed of 720 feet per round while descending. The target may not survive that long. Depending on the world where <i>Nailed to the sky</i> is cast, conditions so far from its surface may be deadly. Deleterious effects include scorching heat, cold, and vacuum. Targets subject to these conditions take 2d6 points of damage each from heat or cold and 1d4 points of damage from the vacuum each round. The target immediately begins to suffocate.</p><p><i>XP Cost:</i> 1,000 XP.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (45,'Origin of Species: Achaierai','origin of species: achaierai','Conjuration','Creation, Healing',NULL,'38',NULL,'V, S, DF, XP','100 days, 11 minutes','0 ft.',NULL,NULL,'One constructed creature up to Medium (20 cu. ft.)','Permanent','None','No',NULL,'360,000 gp; 8 days; 14,400 XP. Seeds: conjure (DC 21), life (DC 27), fortify (DC 17). Factors: +4 HD (5 hp per HD) (+20 DC), +6 to natural AC (+12 DC), add three more natural attacks (ad hoc +6 DC), add black cloud spell-like ability (+33 DC), add spell resistance 19 (+15 DC), permanent (x5 DC). Mitigating factors: 50d6 backlash (-50 DC), increase casting time by 10 minutes (-20 DC), increase casting time by 100 days (-200 DC), burn 10,000 XP (-100 DC), eleven additional casters contributing 9th-level spell slots (-187 DC), ten additional casters contributing 8th-level spell slots (-150 DC), ten additional casters contributing 1st-level spell slots (-10 DC).',NULL,NULL,NULL,'\n      <p>This spell creates a new creature: an achaierai. When first created, the achaierai is Medium, but it grows to Large size in 1d4 days. A created achaierai does not possess the treasure, culture, or specific knowledge of a normal achaierai. If released to be among its own kind, it quickly picks up achaierai traits and alignment.</p>\n      <p/>\n    ','10,000 XP.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Origin of Species: Achaierai\" level=\"5\"><p><h5>Origin of Species: Achaierai</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Creation, Healing)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>38<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF, XP<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>100 days, 11 minutes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>0 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>One constructed creature up to Medium (20 cu. ft.)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Permanent<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>To Develop:</b><br/></td><td>360,000 gp; 8 days; 14,400 XP. Seeds: conjure (DC 21), life (DC 27), fortify (DC 17). Factors: +4 HD (5 hp per HD) (+20 DC), +6 to natural AC (+12 DC), add three more natural attacks (ad hoc +6 DC), add black cloud spell-like ability (+33 DC), add spell resistance 19 (+15 DC), permanent (x5 DC). Mitigating factors: 50d6 backlash (-50 DC), increase casting time by 10 minutes (-20 DC), increase casting time by 100 days (-200 DC), burn 10,000 XP (-100 DC), eleven additional casters contributing 9th-level spell slots (-187 DC), ten additional casters contributing 8th-level spell slots (-150 DC), ten additional casters contributing 1st-level spell slots (-10 DC).<br/></td></tr></table><p>This spell creates a new creature: an achaierai. When first created, the achaierai is Medium, but it grows to Large size in 1d4 days. A created achaierai does not possess the treasure, culture, or specific knowledge of a normal achaierai. If released to be among its own kind, it quickly picks up achaierai traits and alignment.</p><p><i>XP Cost:</i> 10,000 XP.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (46,'Peripety','peripety','Abjuration',NULL,NULL,'27',NULL,'V, S','1 minute','Personal','You',NULL,NULL,'12 hours',NULL,NULL,NULL,'243,000 gp; 5 days; 9,720 XP. Seed: reflect (DC 27).',NULL,NULL,NULL,'\n      <p>Ranged attacks targeted against the character rebound on the original attacker. Any time during the duration, five attacks are automatically reflected back on the original attacker; the character decides which attacks before damage is rolled. The reflected attack rebounds on the attacker using the same attack roll. Once five attacks are so reflected, the spell ends.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Peripety\" level=\"5\"><p><h5>Peripety</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Abjuration<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>27<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 minute<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>12 hours<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>To Develop:</b><br/></td><td>243,000 gp; 5 days; 9,720 XP. Seed: reflect (DC 27).<br/></td></tr></table><p>Ranged attacks targeted against the character rebound on the original attacker. Any time during the duration, five attacks are automatically reflected back on the original attacker; the character decides which attacks before damage is rolled. The reflected attack rebounds on the attacker using the same attack roll. Once five attacks are so reflected, the spell ends.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (47,'Pestilence','pestilence','Conjuration, Necromancy',NULL,NULL,'104',NULL,'V, S, Ritual, XP','10 minutes','0 ft.',NULL,'1,000-ft. -radius hemisphere',NULL,'Instantaneous','Fortitude negates','Yes',NULL,'936,000 gp; 19 days; 37,440 XP. Seed: afflict (DC 19). Factors: additional target type (plants) (+10 DC). change target to area (+10 DC), change 20-ft. radius to 1,000-ft. radius (+200 DC), disease effects (as per contagion spell) (ad hoc +21 DC). Mitigating factors: casting time increased by 9 minutes (-18 DC), two additional casters contributing epic spell slots (-38 DC), burn 10,000 XP (-100 DC).',NULL,NULL,NULL,'\n      <p>When <i>pestilence</i> is successfully cast, a wave of illness radites outward from the site of the ritual, instantly infecting every living thing in the area with the debilitating disease known as slimy doom. Within 24 hours, everything in the area begins to show signs of rot and decay.</p>\n      <p>Each day that a victim fails a Fortitude save, it takes 1d4 points of temporary Constitution damage. If the victim then fails a second save, 1 point of that damage is permanent drain. If the victim succeeds at the first saving throw of the day on consecutive days, he or she has recovered from the disease. This magical form of the disease is not contagious and will not spread beyond those initially infected. Fruits and vegetables infected with slimy doom are unfit for consumption, as are disease-ridden livestock. This is a ritual spell requiring two other spellcasters, each of whom must expend an unused epic spell slot for the casting. The primary caster must also burn 10,000 XP.</p>\n      <p/>\n    ','10,000 XP.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Pestilence\" level=\"5\"><p><h5>Pestilence</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration, Necromancy<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>104<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, Ritual, XP<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>10 minutes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>0 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>1,000-ft. -radius hemisphere<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Fortitude negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>To Develop:</b><br/></td><td>936,000 gp; 19 days; 37,440 XP. Seed: afflict (DC 19). Factors: additional target type (plants) (+10 DC). change target to area (+10 DC), change 20-ft. radius to 1,000-ft. radius (+200 DC), disease effects (as per contagion spell) (ad hoc +21 DC). Mitigating factors: casting time increased by 9 minutes (-18 DC), two additional casters contributing epic spell slots (-38 DC), burn 10,000 XP (-100 DC).<br/></td></tr></table><p>When <i>pestilence</i> is successfully cast, a wave of illness radites outward from the site of the ritual, instantly infecting every living thing in the area with the debilitating disease known as slimy doom. Within 24 hours, everything in the area begins to show signs of rot and decay.</p><p>Each day that a victim fails a Fortitude save, it takes 1d4 points of temporary Constitution damage. If the victim then fails a second save, 1 point of that damage is permanent drain. If the victim succeeds at the first saving throw of the day on consecutive days, he or she has recovered from the disease. This magical form of the disease is not contagious and will not spread beyond those initially infected. Fruits and vegetables infected with slimy doom are unfit for consumption, as are disease-ridden livestock. This is a ritual spell requiring two other spellcasters, each of whom must expend an unused epic spell slot for the casting. The primary caster must also burn 10,000 XP.</p><p><i>XP Cost:</i> 10,000 XP.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (48,'Rain of Fire','rain of fire','Evocation',NULL,'Fire','50',NULL,'V, S','1 minute','0 ft.',NULL,'2-mile-radius emanation',NULL,'20 hours','Reflex negates (see text)','Yes',NULL,'450,000 gp; 9 days; 18,000 XP. Seeds: energy (fire) (DC 19), energy (weather) (DC 19). Factor: change rain to wisps of flame (ad hoc +12 DC).',NULL,NULL,NULL,'\n      <p>This spell summons a swirling thunderstorm that rains fire rather than raindrops down on the character and everything within a two-mile radius of him or her. Everything caught unprotected or unsheltered in the flaming deluge takes 1 point of fire damage each round. A successful Reflex save results in no damage, but the save must be repeated each round. Unless the ground is exceedingly damp, all vegetation is eventually blackened and destroyed, leaving behind a barren wasteland similar to the aftermath of a grass or forest fire. The fiery storm is stationary and persists even if the caster leaves.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Rain of Fire\" level=\"5\"><p><h5>Rain of Fire</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Fire]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>50<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 minute<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>0 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>2-mile-radius emanation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>20 hours<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Reflex negates (see text)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>To Develop:</b><br/></td><td>450,000 gp; 9 days; 18,000 XP. Seeds: energy (fire) (DC 19), energy (weather) (DC 19). Factor: change rain to wisps of flame (ad hoc +12 DC).<br/></td></tr></table><p>This spell summons a swirling thunderstorm that rains fire rather than raindrops down on the character and everything within a two-mile radius of him or her. Everything caught unprotected or unsheltered in the flaming deluge takes 1 point of fire damage each round. A successful Reflex save results in no damage, but the save must be repeated each round. Unless the ground is exceedingly damp, all vegetation is eventually blackened and destroyed, leaving behind a barren wasteland similar to the aftermath of a grass or forest fire. The fiery storm is stationary and persists even if the caster leaves.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (49,'Raise Island','raise island','Conjuration','Creation',NULL,'38',NULL,'V, S, XP, Ritual','65 days, 11 minutes','0 ft.',NULL,'100-ft. -radius hemispherical island',NULL,'Permanent','None','No',NULL,'360,000 gp; 8 days; 14,400 XP. Seed: conjure (DC 21). Factors: change area to 10-ft. radius, 30-ft. high cylinder (+2 DC), change radius to 100 ft. (+40 DC), change height to 1,000 feet (+133 DC), permanent (x5 DC). Mitigating factors: increase casting time by 10 minutes (-20 DC), increase casting time by 65 days (-130 DC), nineteen additional casters contributing epic spell slots (-361 DC), one additional caster contributing one 6th-level spell slot (-11 DC), burn 2,000 XP per epic caster (-400 DC), spell only works on liquid (ad hoc -20 DC).',NULL,NULL,NULL,'\n      <p>The character can literally raise a new island from out of the sea, bringing to the surface a sandy or rocky but otherwise barren protrusion that is solid, stable, and permanently established. The island is roughly circular and about 200 feet in diameter. <i>Raise island</i> only works if the ocean is less than 1,000 feet deep where the spell is cast.</p>\n      <p/>\n    ','2,000 XP.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Raise Island\" level=\"5\"><p><h5>Raise Island</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Creation)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>38<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, XP, Ritual<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>65 days, 11 minutes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>0 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>100-ft. -radius hemispherical island<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Permanent<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>To Develop:</b><br/></td><td>360,000 gp; 8 days; 14,400 XP. Seed: conjure (DC 21). Factors: change area to 10-ft. radius, 30-ft. high cylinder (+2 DC), change radius to 100 ft. (+40 DC), change height to 1,000 feet (+133 DC), permanent (x5 DC). Mitigating factors: increase casting time by 10 minutes (-20 DC), increase casting time by 65 days (-130 DC), nineteen additional casters contributing epic spell slots (-361 DC), one additional caster contributing one 6th-level spell slot (-11 DC), burn 2,000 XP per epic caster (-400 DC), spell only works on liquid (ad hoc -20 DC).<br/></td></tr></table><p>The character can literally raise a new island from out of the sea, bringing to the surface a sandy or rocky but otherwise barren protrusion that is solid, stable, and permanently established. The island is roughly circular and about 200 feet in diameter. <i>Raise island</i> only works if the ocean is less than 1,000 feet deep where the spell is cast.</p><p><i>XP Cost:</i> 2,000 XP.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (50,'Ruin','ruin','Transmutation',NULL,NULL,'27',NULL,'V, S, XP','1 full round','12,000 ft.','One creature, or up to a 10-foot cube of nonliving matter',NULL,NULL,'Instantaneous','Fortitude half','Yes',NULL,'243,000 gp; 5 days; 9,720 XP. Seed: Destroy (DC 29). Factor: reduce casting time by 9 rounds (+18 DC). Mitigating factor: burn 2,000 XP (-20 DC).',NULL,NULL,NULL,'\n      <p>The character deals 20d6 points of damage to a single target within range and line of sight. If the target is reduced to -10 hit points or less (or a construct, object, or undead is reduced to 0 hit points), it is utterly destroyed as if disintegrated. Only a trace of fine dust remains.</p>\n      <p/>\n    ','2,000 XP.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Ruin\" level=\"5\"><p><h5>Ruin</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>27<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, X P<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 full round<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>12,000 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One creature, or up to a 10-foot cube of nonliving matter<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Fortitude half<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>To Develop:</b><br/></td><td>243,000 gp; 5 days; 9,720 XP. Seed: Destroy (DC 29). Factor: reduce casting time by 9 rounds (+18 DC). Mitigating factor: burn 2,000 XP (-20 DC).<br/></td></tr></table><p>The character deals 20d6 points of damage to a single target within range and line of sight. If the target is reduced to -10 hit points or less (or a construct, object, or undead is reduced to 0 hit points), it is utterly destroyed as if disintegrated. Only a trace of fine dust remains.</p><p><i>XP Cost:</i> 2,000 XP.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (51,'Safe Time','safe time','Conjuration',NULL,'Teleportation','64',NULL,'V, S','1 minute','Touch','You or creature touched',NULL,NULL,'Contingent until expended, then 1 round of safe time','None','No',NULL,'576,000 gp; 12 days; 23,040 XP. Seed: Transport (DC 27). Factors: move to time stream (+8 DC), reduce static time to 1 round (ad hoc +4 DC), activates when you would otherwise take 50 or more points of damage (+25 DC).',NULL,NULL,NULL,'\n      <p><i>Safe time</i> can move the character (or the target) out of harm\'s way by shunting him or her into a static time stream. Once cast, the spell remains quiescent and does not activate until the trigger conditions have been met. Each day it remains untriggered, it uses up an epic spell slot, even if you cast it on another creature. Once triggered, the spell is expended normally. When the character would otherwise be subject to any instantaneous effect that would deal him or her 50 or more points of damage, he or she is instead transported to a static time stream where time ceases to flow. The character\'s condition becomes fixed-no force or effect can harm him or her until 1 round of real time has passed. Thus, the character avoids the damage he or she would otherwise receive, but the character also misses out on one round of activity. To the character, no time passes at all, but to onlookers who are part of real time, the character stands frozen and fixed in space for 1 full round.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Safe Time\" level=\"5\"><p><h5>Safe Time</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration [Teleportation]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>64<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 minute<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You or creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Contingent until expended, then 1 round of safe time<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>To Develop:</b><br/></td><td>576,000 gp; 12 days; 23,040 XP. Seed: Transport (DC 27). Factors: move to time stream (+8 DC), reduce static time to 1 round (ad hoc +4 DC), activates when you would otherwise take 50 or more points of damage (+25 DC).<br/></td></tr></table><p><i>Safe time</i> can move the character (or the target) out of harm\'s way by shunting him or her into a static time stream. Once cast, the spell remains quiescent and does not activate until the trigger conditions have been met. Each day it remains untriggered, it uses up an epic spell slot, even if you cast it on another creature. Once triggered, the spell is expended normally. When the character would otherwise be subject to any instantaneous effect that would deal him or her 50 or more points of damage, he or she is instead transported to a static time stream where time ceases to flow. The character\'s condition becomes fixed-no force or effect can harm him or her until 1 round of real time has passed. Thus, the character avoids the damage he or she would otherwise receive, but the character also misses out on one round of activity. To the character, no time passes at all, but to onlookers who are part of real time, the character stands frozen and fixed in space for 1 full round.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (52,'Soul Dominion','soul dominion','Divination, Enchantment','Compulsion','Mind-Affecting','72',NULL,'V, S','10 minutes','See text','One other living creature',NULL,NULL,'20 minutes (D)','Will negates (see text)','No',NULL,'648,000 gp; 13 days; 25,920 XP. Seeds: contact (DC 23), reveal (DC 19), compel (DC 19). Factors: apply to all five senses (+8 DC), total compulsory control (+10 DC), stricter compulsion of any creature (ad hoc +11 DC). Mitigating factor: increase casting time by 9 minutes (-18 DC).',NULL,NULL,NULL,'\n      <p>When a character casts this spell, he or she is temporarily able to take control of another sentient creature with whom the character is familiar (by meeting, observing, or successfully scrying the subject). The target receives a Will save, and if successful, prevents the character from making the telepathic connection. The target is aware of the attempted takeover as a strange, momentary tingling. If the Will save fails, the character is able to control the subject\'s body as if it were his or her own, hearing, seeing, feeling, smelling, and tasting everything the target senses. Once the character dismisses the spell or its duration ends, the target resumes control of its body, fully aware of all events that occurred, having been a helpless witness trapped inside its own body. The target knows the name and general nature of its possessor if it succeeds at an additional Will saving throw. A character cannot control undead or incorporeal creatures with <i>soul dominion</i>.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Soul Dominion\" level=\"5\"><p><h5>Soul Dominion</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Divination, Enchantment (Compulsion) [Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>72<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>10 minutes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>See text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One other living creature<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>20 minutes (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (see text)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>To Develop:</b><br/></td><td>648,000 gp; 13 days; 25,920 XP. Seeds: contact (DC 23), reveal (DC 19), compel (DC 19). Factors: apply to all five senses (+8 DC), total compulsory control (+10 DC), stricter compulsion of any creature (ad hoc +11 DC). Mitigating factor: increase casting time by 9 minutes (-18 DC).<br/></td></tr></table><p>When a character casts this spell, he or she is temporarily able to take control of another sentient creature with whom the character is familiar (by meeting, observing, or successfully scrying the subject). The target receives a Will save, and if successful, prevents the character from making the telepathic connection. The target is aware of the attempted takeover as a strange, momentary tingling. If the Will save fails, the character is able to control the subject\'s body as if it were his or her own, hearing, seeing, feeling, smelling, and tasting everything the target senses. Once the character dismisses the spell or its duration ends, the target resumes control of its body, fully aware of all events that occurred, having been a helpless witness trapped inside its own body. The target knows the name and general nature of its possessor if it succeeds at an additional Will saving throw. A character cannot control undead or incorporeal creatures with <i>soul dominion</i>.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (53,'Soul Scry','soul scry','Divination',NULL,NULL,'55',NULL,'V, S','10 minutes','See text','One other living creature',NULL,NULL,'20 minutes (D)','Will negates','No',NULL,'495,000 gp; 10 days; 19,800 XP. Seeds: contact (DC 23), reveal (DC 19), conceal (DC 17). Factors: apply to all five senses (+8 DC), conceal detection (ad hoc +6 DC). Mitigating factor: increase casting time by 9 minutes (-18 DC).',NULL,NULL,NULL,'\n      <p>When a character casts this spell, he or she is temporarily able to tap the consciousness of another sentient creature with whom the character is familiar (by meeting, observing, or successfully scrying the subject), experiencing everything he or she does with all five senses. The target receives a Will save, and if successful, prevents the character from making the telepathic connection. Whether the saving throw is successful or not, the target is unaware of the attempted intrusion. Once the subject is tapped, the character is able to hear, see, feel, smell, and taste everything the subject senses. The character cannot control the subject, however. The character can only see what the subject chooses to look at, and the character tastes something only if the subject eats or drinks it during the spell\'s duration. During this time, the character\'s own body remains in a trance-like state. If the subject takes damage, the character senses the injuries, although his or her own body does not actually suffer any ill effects. If the subject is knocked unconscious or killed, the spell immediately ends.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Soul Scry\" level=\"5\"><p><h5>Soul Scry</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Divination<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>55<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>10 minutes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>See text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One other living creature<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>20 minutes (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>To Develop:</b><br/></td><td>495,000 gp; 10 days; 19,800 XP. Seeds: contact (DC 23), reveal (DC 19), conceal (DC 17). Factors: apply to all five senses (+8 DC), conceal detection (ad hoc +6 DC). Mitigating factor: increase casting time by 9 minutes (-18 DC).<br/></td></tr></table><p>When a character casts this spell, he or she is temporarily able to tap the consciousness of another sentient creature with whom the character is familiar (by meeting, observing, or successfully scrying the subject), experiencing everything he or she does with all five senses. The target receives a Will save, and if successful, prevents the character from making the telepathic connection. Whether the saving throw is successful or not, the target is unaware of the attempted intrusion. Once the subject is tapped, the character is able to hear, see, feel, smell, and taste everything the subject senses. The character cannot control the subject, however. The character can only see what the subject chooses to look at, and the character tastes something only if the subject eats or drinks it during the spell\'s duration. During this time, the character\'s own body remains in a trance-like state. If the subject takes damage, the character senses the injuries, although his or her own body does not actually suffer any ill effects. If the subject is knocked unconscious or killed, the spell immediately ends.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (54,'Spell Worm','spell worm','Enchantment','Compulsion','Mind-Affecting','45',NULL,'V, S','1 standard action','75 ft.','One living creature',NULL,NULL,'20 hours or until completed','Will negates','Yes',NULL,'405,000 gp; 9 days; 16,200 XP. Seed: compel (DC 19). Factors: unobtrusive (ad hoc +6 DC), 1-action casting time (+20 DC).',NULL,NULL,NULL,'\n      <p>On a failed save, the subject must spend a standard action each round abandoning his or her highest-level spell (or losing his or her highest-level unused spell slot). Each round, the subject eliminates another spell or spell slot, moving to lower-level spells once all the higher-level spells are gone. In the case of prepared spells, the subject decides which spells to abandon at each level. If the subject has more than one standard action allowed in the round, he or she may spend those actions as he or she desires. The subject doesn\'t realize the spells or spell slots are gone until he or she tries to cast a spell and finds it unavailable. Abandoning a spell slot or losing a spell is standard action, but it does not draw an attack of opportunity. It is a purely mental exercise not obvious to observers.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Spell Worm\" level=\"5\"><p><h5>Spell Worm</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Enchantment (Compulsion) [Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>45<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>75 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One living creature<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>20 hours or until completed<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>To Develop:</b><br/></td><td>405,000 gp; 9 days; 16,200 XP. Seed: compel (DC 19). Factors: unobtrusive (ad hoc +6 DC), 1-action casting time (+20 DC).<br/></td></tr></table><p>On a failed save, the subject must spend a standard action each round abandoning his or her highest-level spell (or losing his or her highest-level unused spell slot). Each round, the subject eliminates another spell or spell slot, moving to lower-level spells once all the higher-level spells are gone. In the case of prepared spells, the subject decides which spells to abandon at each level. If the subject has more than one standard action allowed in the round, he or she may spend those actions as he or she desires. The subject doesn\'t realize the spells or spell slots are gone until he or she tries to cast a spell and finds it unavailable. Abandoning a spell slot or losing a spell is standard action, but it does not draw an attack of opportunity. It is a purely mental exercise not obvious to observers.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (55,'Summon Behemoth','summon behemoth','Conjuration','Summoning',NULL,'72',NULL,'V, S','1 standard action','75 ft.',NULL,NULL,'Summoned creature','20 rounds (D)','None','No',NULL,'648,000 gp; 13 days; 25,920 XP. Seed: summon (DC 14). Factors: summon CR 21 creature (DC +38), 1-action casting time (+20 DC).',NULL,NULL,NULL,'\n      <p>The character can summon a behemoth to attack his or her enemies. It appears where the character designates and acts immediately, on the character\'s turn. It attacks the character\'s opponents to the best of its ability. If the character can communicate with the creature, he or she can direct it not to attack, to attack particular enemies, or to perform other actions. Summoned creatures act normally on the last round of the spell and disappear at the end of their turn.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Summon Behemoth\" level=\"5\"><p><h5>Summon Behemoth</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Summoning)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>72<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>75 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>Summoned creature<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>20 rounds (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>To Develop:</b><br/></td><td>648,000 gp; 13 days; 25,920 XP. Seed: summon (DC 14). Factors: summon CR 21 creature (DC +38), 1-action casting time (+20 DC).<br/></td></tr></table><p>The character can summon a behemoth to attack his or her enemies. It appears where the character designates and acts immediately, on the character\'s turn. It attacks the character\'s opponents to the best of its ability. If the character can communicate with the creature, he or she can direct it not to attack, to attack particular enemies, or to perform other actions. Summoned creatures act normally on the last round of the spell and disappear at the end of their turn.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (56,'Superb Dispelling','superb dispelling','Abjuration',NULL,NULL,'59',NULL,'V, S','1 standard action','300 ft.','One creature or object',NULL,NULL,'Instantaneous','None','No',NULL,'531,000 gp; 11 days; 21,240 XP. Seed: Dispel (DC 19). Factors: additional +30 to dispel check (+30 DC), 1-action casting time (+20 DC). Mitigating factor: 10d6 backlash (-10 DC).',NULL,NULL,NULL,'\n      <p>As <i>greater dispel magic</i>, except that the maximum bonus on the dispel check is +40, and the character takes 10d6 points of backlash damage.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Superb Dispelling\" level=\"5\"><p><h5>Superb Dispelling</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Abjuration<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>59<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>300 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One creature or object<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>To Develop:</b><br/></td><td>531,000 gp; 11 days; 21,240 XP. Seed: Dispel (DC 19). Factors: additional +30 to dispel check (+30 DC), 1-action casting time (+20 DC). Mitigating factor: 10d6 backlash (-10 DC).<br/></td></tr></table><p>As <i>greater dispel magic</i>, except that the maximum bonus on the dispel check is +40, and the character takes 10d6 points of backlash damage.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (57,'Time Duplicate','time duplicate','Conjuration',NULL,'Teleportation','71',NULL,'V, S','1 free action',NULL,NULL,NULL,'You','1 round (see text)','None (harmless)','None (harmless)',NULL,'639,000 gp; 13 days; 25,560 XP. Seed: Transport (to move future you back in time 1 round) (DC 27). Factors: move to time stream (+8 DC), stretch the base temporal effect (ad hoc +8 DC), quickened (+28 DC).',NULL,NULL,NULL,'\n      <p>The character snatches him or her self from 1 round in the future, depositing this future self in an adjacent space as a free action that counts as a quickened spell. The character\'s future self is technically only a possible future self (the time stream is a maelstrom of multiple probabilities), but snatching that future self from 1 round in the future collapses probability, and the possible future becomes the definite future. The character and his or her future self are both free to act normally this round (the character has already used up the limit of one quickened spell per round, but his or her duplicate hasn\'t). The future self has all the resources the character has at the moment he or she finishes casting <i>time duplicate</i>. Because the future self was previously only a possibility, his or her resources are not depleted as a result of whatever might occur this round (even if the character dies this round). Likewise, he or she doesn\'t have any special knowledge of what might occur during this round. Because the future self is still part of the time stream, the round it spends with the character is a round it misses in its own future. Because the chracter\'s future duplicate is also the character, the character misses the next round as well. He or she simply isn\'t there. Tampering with the time stream is a tricky business. Here is a round-by-round summary.</p>\n      <p><i>Round One:</i> The character casts <i>time duplicate</i>, the future self from round two arrives, and both act normally.</p>\n      <p><i>Round Two:</i> The future self-the character-gets snatched back in time to help the past self. During this round, there are no versions of the character present.</p>\n      <p><i>Round Three:</i> The character rejoins the time stream. The character arrives in the same location and condition that the future self ended with at the end of the first round. Any resources (spells, damage, staff charges) the future self used up in round one are gone for real. Record them now. Using this spell to snatch a single future self stretches time and probability to its limit; more powerful versions of <i>time duplicate</i> are not possible. A character cannot bring more than a single future version of him or her self back at one time, nor can a character snatch a version of him or her from farther in the future.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Time Duplicate\" level=\"5\"><p><h5>Time Duplicate</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration [Teleportation]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>71<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 free action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round (see text)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>None (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>To Develop:</b><br/></td><td>639,000 gp; 13 days; 25,560 XP. Seed: Transport (to move future you back in time 1 round) (DC 27). Factors: move to time stream (+8 DC), stretch the base temporal effect (ad hoc +8 DC), quickened (+28 DC).<br/></td></tr></table><p>The character snatches him or her self from 1 round in the future, depositing this future self in an adjacent space as a free action that counts as a quickened spell. The character\'s future self is technically only a possible future self (the time stream is a maelstrom of multiple probabilities), but snatching that future self from 1 round in the future collapses probability, and the possible future becomes the definite future. The character and his or her future self are both free to act normally this round (the character has already used up the limit of one quickened spell per round, but his or her duplicate hasn\'t). The future self has all the resources the character has at the moment he or she finishes casting <i>time duplicate</i>. Because the future self was previously only a possibility, his or her resources are not depleted as a result of whatever might occur this round (even if the character dies this round). Likewise, he or she doesn\'t have any special knowledge of what might occur during this round. Because the future self is still part of the time stream, the round it spends with the character is a round it misses in its own future. Because the chracter\'s future duplicate is also the character, the character misses the next round as well. He or she simply isn\'t there. Tampering with the time stream is a tricky business. Here is a round-by-round summary.</p><p><i>Round One:</i> The character casts <i>time duplicate</i>, the future self from round two arrives, and both act normally.</p><p><i>Round Two:</i> The future self-the character-gets snatched back in time to help the past self. During this round, there are no versions of the character present.</p><p><i>Round Three:</i> The character rejoins the time stream. The character arrives in the same location and condition that the future self ended with at the end of the first round. Any resources (spells, damage, staff charges) the future self used up in round one are gone for real. Record them now. Using this spell to snatch a single future self stretches time and probability to its limit; more powerful versions of <i>time duplicate</i> are not possible. A character cannot bring more than a single future version of him or her self back at one time, nor can a character snatch a version of him or her from farther in the future.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (58,'Vengeful Gaze of God','vengeful gaze of god','Transmutation',NULL,NULL,'419',NULL,'V, S','1 standard action','12,000 ft.','One creature, or up to a 10-foot cube of nonliving matter in line of sight',NULL,NULL,'Instantaneous','Fortitude half','Yes',NULL,'3,771,000 gp; 76 days; 150,840 XP. Seed: Destroy (DC 29). Factor: increase damage to 305d6 (+570 DC), 1-action casting time (+20 DC). Mitigating factor: 200d6 backlash (-200 DC).',NULL,NULL,NULL,'\n      <p>The target of this spell is subject to 305d6 points of damage (or half of that if a Fortitude save succeeds). If the target is reduced to -10 hit points or less (or a construct, object, or undead is reduced to 0 hit points), it is utterly destroyed as if disintegrated, leaving behind only a trace of fine dust. The caster is likewise dealt 200d6 points of damage</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Vengeful Gaze of God\" level=\"5\"><p><h5>Vengeful Gaze of God</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>419<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>12,000 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One creature, or up to a 10-foot cube of nonliving matter in line of sight<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Fortitude half<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>To Develop:</b><br/></td><td>3,771,000 gp; 76 days; 150,840 XP. Seed: Destroy (DC 29). Factor: increase damage to 305d6 (+570 DC), 1-action casting time (+20 DC). Mitigating factor: 200d6 backlash (-200 DC).<br/></td></tr></table><p>The target of this spell is subject to 305d6 points of damage (or half of that if a Fortitude save succeeds). If the target is reduced to -10 hit points or less (or a construct, object, or undead is reduced to 0 hit points), it is utterly destroyed as if disintegrated, leaving behind only a trace of fine dust. The caster is likewise dealt 200d6 points of damage</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (59,'Verdigris','verdigris','Conjuration','Creation',NULL,'58',NULL,'V, S','1 minute','300 ft.',NULL,'100-ft. -radius hemisphere',NULL,'24 hours','Reflex half','No',NULL,'522,000 gp; 11 days; 20,880 XP. Seed: Conjure (DC 21). Factors: change area to 20-ft. radius hemisphere (+2 DC), increase radius to 100 ft. (+16 DC), deal 10d6 damage during growth (ad hoc +19 DC).',NULL,NULL,NULL,'\n      <p>This spell creates a tsunami of grass, shrubs, and trees that overgrows the area like a tidal wave. The plant growth creeps and curls across every-thing in the area, ensnaring it and coiling around it as if it had been growing there for a century or more. Creatures in the area must make a Reflex saving throw to avoid the fast-moving growth, which otherwise deals 10d6 points of damage from the crushing press. Buildings are engulfed and they likewise take 10d6 points of damage. Those destroyed by the damage have their foundations uprooted and walls crumbled. The plant growth remains for 24 hours, after which it vanishes.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Verdigris\" level=\"5\"><p><h5>Verdigris</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Creation)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>58<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 minute<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>300 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>100-ft. -radius hemisphere<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>24 hours<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Reflex half<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>To Develop:</b><br/></td><td>522,000 gp; 11 days; 20,880 XP. Seed: Conjure (DC 21). Factors: change area to 20-ft. radius hemisphere (+2 DC), increase radius to 100 ft. (+16 DC), deal 10d6 damage during growth (ad hoc +19 DC).<br/></td></tr></table><p>This spell creates a tsunami of grass, shrubs, and trees that overgrows the area like a tidal wave. The plant growth creeps and curls across every-thing in the area, ensnaring it and coiling around it as if it had been growing there for a century or more. Creatures in the area must make a Reflex saving throw to avoid the fast-moving growth, which otherwise deals 10d6 points of damage from the crushing press. Buildings are engulfed and they likewise take 10d6 points of damage. Those destroyed by the damage have their foundations uprooted and walls crumbled. The plant growth remains for 24 hours, after which it vanishes.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (60,'Verdigris Tsunami','verdigris tsunami','Conjuration','Creation',NULL,'170',NULL,'V, S, Ritual, XP','10 minutes','1,500 ft.',NULL,'1,000-ft. -radius hemisphere',NULL,'Permanent','Reflex half','No',NULL,'1,530,000 gp; 31 days; 61,200 XP. Seed: conjure (DC 21). Factor: change area to 20-ft. -radius hemisphere (+2 DC), increase radius to 1,000 ft. (+196 DC), increase range to 1,500 ft. (+8 DC), deal 10d6 damage during growth (ad hoc +19 DC), increase damage to 40d6 (+60 DC), permanent (x5 DC). Mitigating factors: increase casting time by 9 minutes (-18 DC), eleven additional casters contributing 6th-level spell slots (-121 DC), three additional casters contributing 4th-level spell slots (-21 DC), burn 10,000 XP per 6th-level spell contributor plus caster (-1,200 DC).',NULL,NULL,NULL,'\n      <p>This spell creates a tsunami of grass, shrubs, and trees that overgrows the area like a tidal wave. The plant growth creeps and curls across every-thing in the area, ensnaring it and coiling around it as if it had been growing there for a century or more. Creatures in the area must make a Reflex saving throw to avoid the fast-moving growth, which otherwise deals 40d6 points of damage from the crushing press. Buildings are engulfed and they likewise take 40d6 points of damage. Those destroyed by the damage have their foundations uprooted and walls crumbled. The plant growth is permanent. This is a ritual spell requiring fourteen other spellcasters, each of whom must contribute an unused 6th-level spell slot to the casting.</p>\n      <p/>\n    ','10,000 XP.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Verdigris Tsunami\" level=\"5\"><p><h5>Verdigris Tsunami</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Creation)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>170<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, Ritual, XP<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>10 minutes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>1,500 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>1,000-ft. -radius hemisphere<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Permanent<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Reflex half<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>To Develop:</b><br/></td><td>1,530,000 gp; 31 days; 61,200 XP. Seed: conjure (DC 21). Factor: change area to 20-ft. -radius hemisphere (+2 DC), increase radius to 1,000 ft. (+196 DC), increase range to 1,500 ft. (+8 DC), deal 10d6 damage during growth (ad hoc +19 DC), increase damage to 40d6 (+60 DC), permanent (x5 DC). Mitigating factors: increase casting time by 9 minutes (-18 DC), eleven additional casters contributing 6th-level spell slots (-121 DC), three additional casters contributing 4th-level spell slots (-21 DC), burn 10,000 XP per 6th-level spell contributor plus caster (-1,200 DC).<br/></td></tr></table><p>This spell creates a tsunami of grass, shrubs, and trees that overgrows the area like a tidal wave. The plant growth creeps and curls across every-thing in the area, ensnaring it and coiling around it as if it had been growing there for a century or more. Creatures in the area must make a Reflex saving throw to avoid the fast-moving growth, which otherwise deals 40d6 points of damage from the crushing press. Buildings are engulfed and they likewise take 40d6 points of damage. Those destroyed by the damage have their foundations uprooted and walls crumbled. The plant growth is permanent. This is a ritual spell requiring fourteen other spellcasters, each of whom must contribute an unused 6th-level spell slot to the casting.</p><p><i>XP Cost:</i> 10,000 XP.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (61,'Seed: Afflict','seed: afflict','Enchantment','Compulsion','Fear, Mind-Affecting','14',NULL,'V, S','1 standard action','300 ft.','One living creature',NULL,NULL,'20 minutes','Will negates','Yes',NULL,NULL,NULL,NULL,NULL,'\n      <p>Afflicts the target with a -2 morale penalty on attack rolls, checks, and saving throws. For each additional -1 penalty assessed on either the target\'s attack rolls, checks, or saving throws, increase the Spellcraft DC by +2. A character may also develop a spell with this seed that afflicts the target with a -1 penalty on caster level checks, a -1 penalty to an ability score, a -1 penalty to spell resistance, or a -1 penalty to some other aspect of the target. For each additional -1 penalty assessed in one of the above categories, increase the Spell-craft DC by +4. This seed can afflict a character\'s ability scores to the point where they reach 0, except for Constitution where 1 is the minimum. If a factor is applied to increase the duration of this seed, ability score penalties instead become temporary ability damage. If a factor is applied to make the duration permanent, any ability score penalties become permanent ability drain. Finally, by increasing the Spellcraft DC by +2, one of the target\'s senses can be afflicted: sight, smell, hearing, taste, touch, or a special sense the target possesses. If the target fails its saving throw, the sense selected doesn\'t function for the spell\'s duration, with all attendant penalties that apply for losing the specified sense.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Seed: Afflict\" level=\"3\"><p><h3>Seed: Afflict</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Enchantment (Compulsion) [Fear, Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>14<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>300 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One living creature<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>20 minutes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>Afflicts the target with a -2 morale penalty on attack rolls, checks, and saving throws. For each additional -1 penalty assessed on either the target\'s attack rolls, checks, or saving throws, increase the Spellcraft DC by +2. A character may also develop a spell with this seed that afflicts the target with a -1 penalty on caster level checks, a -1 penalty to an ability score, a -1 penalty to spell resistance, or a -1 penalty to some other aspect of the target. For each additional -1 penalty assessed in one of the above categories, increase the Spell-craft DC by +4. This seed can afflict a character\'s ability scores to the point where they reach 0, except for Constitution where 1 is the minimum. If a factor is applied to increase the duration of this seed, ability score penalties instead become temporary ability damage. If a factor is applied to make the duration permanent, any ability score penalties become permanent ability drain. Finally, by increasing the Spellcraft DC by +2, one of the target\'s senses can be afflicted: sight, smell, hearing, taste, touch, or a special sense the target possesses. If the target fails its saving throw, the sense selected doesn\'t function for the spell\'s duration, with all attendant penalties that apply for losing the specified sense.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (62,'Seed: Animate','seed: animate','Transmutation',NULL,NULL,'25',NULL,'V, S','1 minute','300 ft.','Object or 20 cu. ft. of matter',NULL,NULL,'20 rounds','None','No',NULL,NULL,NULL,NULL,NULL,'\n      <p>This seed can imbue inanimate objects with mobility and a semblance of life (not actual life). The animated object attacks whomever or whatever the caster initially designates. The animated object can be of any nonmagical material. The caster can also animate part of a larger mass of raw matter, such as a volume of water in the ocean, part of a stony wall, or the earth itself, as long as the volume of material does not exceed 20 cubic feet. For each additional 10 cubic feet of matter animated, increase the Spellcraft DC by +1, up to 1,000 cubic feet. For each additional 100 cubic feet of matter animated after the first 1,000 cubic feet, increase the spellcraft DC by +1. For each additional Hit Die granted to an animated object of a given size, increase the Spellcraft DC by +2. To animate attended objects (objects carried or worn by another creature), increase the Spellcraft DC by +10.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Seed: Animate\" level=\"3\"><p><h3>Seed: Animate</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>25<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 minute<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>300 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Object or 20 cu. ft. of matter<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>20 rounds<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>This seed can imbue inanimate objects with mobility and a semblance of life (not actual life). The animated object attacks whomever or whatever the caster initially designates. The animated object can be of any nonmagical material. The caster can also animate part of a larger mass of raw matter, such as a volume of water in the ocean, part of a stony wall, or the earth itself, as long as the volume of material does not exceed 20 cubic feet. For each additional 10 cubic feet of matter animated, increase the Spellcraft DC by +1, up to 1,000 cubic feet. For each additional 100 cubic feet of matter animated after the first 1,000 cubic feet, increase the spellcraft DC by +1. For each additional Hit Die granted to an animated object of a given size, increase the Spellcraft DC by +2. To animate attended objects (objects carried or worn by another creature), increase the Spellcraft DC by +10.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (63,'Seed: Animate Dead','seed: animate dead','Necromancy',NULL,'Evil','23',NULL,'V, S','1 minute','Touch','One or more corpses touched',NULL,NULL,'Instantaneous','None','No',NULL,NULL,NULL,NULL,NULL,'\n      <p>The caster can turn the bones or bodies of dead creatures into undead that follow his or her spoken commands. The undead can follow the caster, or they can remain in an area and attack any creature (or a specific type of creature) entering the place. The undead remain animated until they are destroyed. (A destroyed undead can\'t be animated again.) Intelligent undead can follow more sophisticated commands. The <i>animate dead</i> seed allows a character to create 20 HD of undead. For each additional 1 HD of undead created, increase the Spellcraft DC by +1. The undead created remain under the caster\'s control indefinitely. A caster can naturally control 1 HD per caster level of undead creatures he or she has personally created, regardless of the method used. If the caster exceeds this number, newly created creatures fall under his or her control, and excess undead from previous castings become uncontrolled (the caster chooses which creatures are released). If the caster is a cleric, any undead he or she commands through his or her ability to command or rebuke undead do not count toward the limit. For each additional 2 HD of undead to be controlled, increase the Spellcraft DC by +1. Only undead in excess of 20 HD created with this seed can be controlled using this DC adjustment. To both create and control more than 20 HD of undead, increase the Spellcraft DC by +3 per additional 2 HD of undead.</p>\n      <p>Type of Undead: All types of undead can be created with the <i>animate dead</i> seed, although creating more powerful undead increases the Spellcraft DC of the epic spell, according to the table below. The GM must set the Spellcraft DC for undead not included on the table, using similar undead as a basis for comparison.</p>\n      <table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"5\" curcol=\"5\">\n<td><b>Undead</b><br/></td>\n<td><b>Spellcraft DC Modifier</b><br/></td>\n<td><b>Undead</b><br/></td>\n<td><b>Spellcraft DC Modifier</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Skeleton<br/></td>\n<td>-12<br/></td>\n<td>Wraith<br/></td>\n<td>-2<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Zombie<br/></td>\n<td>-12<br/></td>\n<td>Mummy<br/></td>\n<td>+0<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Ghoul<br/></td>\n<td>-10<br/></td>\n<td>Spectre<br/></td>\n<td>+2<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Shadow<br/></td>\n<td>-8<br/></td>\n<td>Morhg<br/></td>\n<td>+4<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Ghast<br/></td>\n<td>-6<br/></td>\n<td>Vampire<br/></td>\n<td>+6<br/></td>\n\n</tr>\n\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Wight<br/></td>\n<td>-4<br/></td>\n<td>Ghost<br/></td>\n<td>+8<br/></td>\n\n</tr>\n</table>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Seed: Animate Dead\" level=\"3\"><p><h3>Seed: Animate Dead</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Necromancy [Evil]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>23<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 minute<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One or more corpses touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>The caster can turn the bones or bodies of dead creatures into undead that follow his or her spoken commands. The undead can follow the caster, or they can remain in an area and attack any creature (or a specific type of creature) entering the place. The undead remain animated until they are destroyed. (A destroyed undead can\'t be animated again.) Intelligent undead can follow more sophisticated commands. The <i>animate dead</i> seed allows a character to create 20 HD of undead. For each additional 1 HD of undead created, increase the Spellcraft DC by +1. The undead created remain under the caster\'s control indefinitely. A caster can naturally control 1 HD per caster level of undead creatures he or she has personally created, regardless of the method used. If the caster exceeds this number, newly created creatures fall under his or her control, and excess undead from previous castings become uncontrolled (the caster chooses which creatures are released). If the caster is a cleric, any undead he or she commands through his or her ability to command or rebuke undead do not count toward the limit. For each additional 2 HD of undead to be controlled, increase the Spellcraft DC by +1. Only undead in excess of 20 HD created with this seed can be controlled using this DC adjustment. To both create and control more than 20 HD of undead, increase the Spellcraft DC by +3 per additional 2 HD of undead.</p><p>Type of Undead: All types of undead can be created with the <i>animate dead</i> seed, although creating more powerful undead increases the Spellcraft DC of the epic spell, according to the table below. The GM must set the Spellcraft DC for undead not included on the table, using similar undead as a basis for comparison.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"5\" curcol=\"5\">\n<td><b>Undead</b><br/></td>\n<td><b>Spellcraft DC Modifier</b><br/></td>\n<td><b>Undead</b><br/></td>\n<td><b>Spellcraft DC Modifier</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Skeleton<br/></td>\n<td>-12<br/></td>\n<td>Wraith<br/></td>\n<td>-2<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Zombie<br/></td>\n<td>-12<br/></td>\n<td>Mummy<br/></td>\n<td>+0<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Ghoul<br/></td>\n<td>-10<br/></td>\n<td>Spectre<br/></td>\n<td>+2<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Shadow<br/></td>\n<td>-8<br/></td>\n<td>Morhg<br/></td>\n<td>+4<br/></td>\n\n</tr>\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Ghast<br/></td>\n<td>-6<br/></td>\n<td>Vampire<br/></td>\n<td>+6<br/></td>\n\n</tr>\n\n<tr maxcol=\"5\" curcol=\"5\">\n<td>Wight<br/></td>\n<td>-4<br/></td>\n<td>Ghost<br/></td>\n<td>+8<br/></td>\n\n</tr>\n</table><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (64,'Seed: Armor','seed: armor','Conjuration','Creation','Force','14',NULL,'V, S','1 minute','Touch','Creature touched',NULL,NULL,'24 hours (D)','Will negates (harmless)','Yes (harmless)',NULL,NULL,NULL,NULL,NULL,'\n      <p>This seed grants a creature additional armor, providing a +4 bonus to Armor Class. The bonus is either an armor bonus or a natural armor bonus, whichever the caster selects. Unlike mundane armor, the <i>Armor</i> seed provides an intangible protection that entails no armor check penalty, arcane spell failure chance, or speed reduction. Incorporeal creatures can\'t bypass the <i>Armor</i> seed the way they can ignore normal armor. For each additional point of Armor Class bonus, increase the Spellcraft DC by +2. The caster can also grant a creature a +1 bonus to Armor Class using a different bonus type, such as deflection, divine, or insight. For each additional point of bonus to Armor Class of one of these types, increase the Spellcraft DC by +10.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Seed: Armor\" level=\"3\"><p><h3>Seed: Armor</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Creation) [Force]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>14<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 minute<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>24 hours (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr></table><p>This seed grants a creature additional armor, providing a +4 bonus to Armor Class. The bonus is either an armor bonus or a natural armor bonus, whichever the caster selects. Unlike mundane armor, the <i>Armor</i> seed provides an intangible protection that entails no armor check penalty, arcane spell failure chance, or speed reduction. Incorporeal creatures can\'t bypass the <i>Armor</i> seed the way they can ignore normal armor. For each additional point of Armor Class bonus, increase the Spellcraft DC by +2. The caster can also grant a creature a +1 bonus to Armor Class using a different bonus type, such as deflection, divine, or insight. For each additional point of bonus to Armor Class of one of these types, increase the Spellcraft DC by +10.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (65,'Seed: Banish','seed: banish','Abjuration',NULL,NULL,'27',NULL,'V, S','1 minute','75 ft.','One or more extraplanar creatures, no two of which can be more than 30 ft. apart',NULL,NULL,'Instantaneous','Will negates','Yes',NULL,NULL,NULL,NULL,NULL,'\n      <p>This seed forces extraplanar creatures out of the caster\'s home plane. The caster can banish up to 14 HD of extraplanar creatures. For each additional 2 HD of extraplanar creatures banished, increase the Spellcraft DC by +1. To specify a type or sub-type of creature other than outsider to be banished, increase the Spellcraft DC by +20.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Seed: Banish\" level=\"3\"><p><h3>Seed: Banish</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Abjuration<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>27<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 minute<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>75 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One or more extraplanar creatures, no two of which can be more than 30 ft. apart<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>This seed forces extraplanar creatures out of the caster\'s home plane. The caster can banish up to 14 HD of extraplanar creatures. For each additional 2 HD of extraplanar creatures banished, increase the Spellcraft DC by +1. To specify a type or sub-type of creature other than outsider to be banished, increase the Spellcraft DC by +20.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (66,'Seed: Compel','seed: compel','Enchantment','Compulsion','Mind-Affecting','19',NULL,'V, M','1 minute','75 ft.','One living creature',NULL,NULL,'20 hours or until completed','Will negates','Yes',NULL,NULL,NULL,NULL,NULL,'\n      <p>This seed compels a target to follow a course of activity. At the basic level of effect, a spell using the <i>compel</i> seed must be worded in such a manner as to make the activity sound reasonable. Asking the creature to do an obviously harmful act automatically negates the effect (unless the Spellcraft DC has been increased to avoid this limitation; see below). To compel a creature to follow an outright unreasonable course of action, increase the Spellcraft DC by +10. The compelled course of activity can continue for the entire duration. If the compelled activity can be completed in a shorter time, the spell ends when the subject finishes what he or she was asked to do. The caster can instead specify conditions that will trigger a special activity during the duration. If the condition is not met before the spell using this seed expires, the activity is not performed.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Seed: Compel\" level=\"3\"><p><h3>Seed: Compel</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Enchantment (Compulsion) [Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>19<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 minute<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>75 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One living creature<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>20 hours or until completed<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>This seed compels a target to follow a course of activity. At the basic level of effect, a spell using the <i>compel</i> seed must be worded in such a manner as to make the activity sound reasonable. Asking the creature to do an obviously harmful act automatically negates the effect (unless the Spellcraft DC has been increased to avoid this limitation; see below). To compel a creature to follow an outright unreasonable course of action, increase the Spellcraft DC by +10. The compelled course of activity can continue for the entire duration. If the compelled activity can be completed in a shorter time, the spell ends when the subject finishes what he or she was asked to do. The caster can instead specify conditions that will trigger a special activity during the duration. If the condition is not met before the spell using this seed expires, the activity is not performed.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (67,'Seed: Conceal','seed: conceal','Illusion','Glamer',NULL,'17',NULL,'V, S','1 minute','Personal or touch','You or a creature or object of up to 2,000 lb.',NULL,NULL,'200 minutes or until expended (D)','None or Will negates (harmless, object)','No or Yes (harmless, object)',NULL,NULL,NULL,NULL,NULL,'\n      <p>This seed can conceal a creature or object touched from sight, even from darkvision. If the subject is a creature carrying gear, the gear vanishes too, rendering the creature invisible. A spell using the <i>conceal</i> seed ends if the subject attacks any creature. Actions directed at unattended objects do not break the spell, and causing harm indirectly is not an attack. To create invisibility that lasts regardless of the actions of the subject, increase the Spellcraft DC by +4. Alternatively, this seed can conceal the exact location of the subject so that it appears to be about 2 feet away from its true location; this increases the Spellcraft DC by +2. The subject benefits from a 50% miss chance as if it had total concealment. However, unlike actual total concealment, this displacement effect does not prevent enemies from targeting him or her normally. The <i>conceal</i> seed can also be used to block divination spells, spell-like effects, and epic spells developed using the <i>reveal</i> seed; this increases the Spellcraft DC by +6. In all cases where divination magic of any level, including epic level, is employed against the subject of a spell using the <i>conceal</i> seed for this purpose, an opposed caster level check determines which spell works.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Seed: Conceal\" level=\"3\"><p><h3>Seed: Conceal</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Illusion (Glamer)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>17<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 minute<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal or touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You or a creature or object of up to 2,000 lb.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>200 minutes or until expended (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None or Will negates (harmless, object)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No or Yes (harmless, object)<br/></td></tr></table><p>This seed can conceal a creature or object touched from sight, even from darkvision. If the subject is a creature carrying gear, the gear vanishes too, rendering the creature invisible. A spell using the <i>conceal</i> seed ends if the subject attacks any creature. Actions directed at unattended objects do not break the spell, and causing harm indirectly is not an attack. To create invisibility that lasts regardless of the actions of the subject, increase the Spellcraft DC by +4. Alternatively, this seed can conceal the exact location of the subject so that it appears to be about 2 feet away from its true location; this increases the Spellcraft DC by +2. The subject benefits from a 50% miss chance as if it had total concealment. However, unlike actual total concealment, this displacement effect does not prevent enemies from targeting him or her normally. The <i>conceal</i> seed can also be used to block divination spells, spell-like effects, and epic spells developed using the <i>reveal</i> seed; this increases the Spellcraft DC by +6. In all cases where divination magic of any level, including epic level, is employed against the subject of a spell using the <i>conceal</i> seed for this purpose, an opposed caster level check determines which spell works.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (68,'Seed: Conjure','seed: conjure','Conjuration','Creation',NULL,'21',NULL,'V, S','1 minute','0 ft.',NULL,NULL,'Unattended, nonmagical object of nonliving matter up to 20 cu. ft.','8 hours','None','No',NULL,NULL,NULL,NULL,NULL,'\n      <p>This seed creates a nonmagical, unattended object of nonliving matter of up to 20 cubic feet in volume. The caster must succeed at an appropriate skill check to make a complex item. The seed can create matter ranging in hardness and rarity from vegetable matter all the way up to mithral and even adamantine. Simple objects have a natural duration of 24 hours. For each additional cubic foot of matter created, increase the Spellcraft DC by +2. Attempting to use any created object as a material component or a resource during epic spell development causes the spell to fail and the object to disappear.</p>\n      <p>The <i>Conjure</i> seed can be used in conjunction with the <i>life</i> and <i>fortify</i> seeds for an epic spell that creates an entirely new creature, if made permanent. To give a creature spell-like abilities, apply other epic seeds to the epic spell that replicate the desired ability. To give the creature a supernatural or extraordinary ability rather than a spell-like ability, double the cost of the relevant seed. Remember that two doublings equals a tripling, and so forth. To give a creature Hit Dice, use the <i>fortify</i> seed. Each 5 hit points granted to the creature gives it an additional 1 HD. Once successfully created, the new creature will breed true.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Seed: Conjure\" level=\"3\"><p><h3>Seed: Conjure</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Creation)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>21<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 minute<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>0 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>Unattended, nonmagical object of nonliving matter up to 20 cu. ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>8 hours<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>This seed creates a nonmagical, unattended object of nonliving matter of up to 20 cubic feet in volume. The caster must succeed at an appropriate skill check to make a complex item. The seed can create matter ranging in hardness and rarity from vegetable matter all the way up to mithral and even adamantine. Simple objects have a natural duration of 24 hours. For each additional cubic foot of matter created, increase the Spellcraft DC by +2. Attempting to use any created object as a material component or a resource during epic spell development causes the spell to fail and the object to disappear.</p><p>The <i>Conjure</i> seed can be used in conjunction with the <i>life</i> and <i>fortify</i> seeds for an epic spell that creates an entirely new creature, if made permanent. To give a creature spell-like abilities, apply other epic seeds to the epic spell that replicate the desired ability. To give the creature a supernatural or extraordinary ability rather than a spell-like ability, double the cost of the relevant seed. Remember that two doublings equals a tripling, and so forth. To give a creature Hit Dice, use the <i>fortify</i> seed. Each 5 hit points granted to the creature gives it an additional 1 HD. Once successfully created, the new creature will breed true.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (69,'Seed: Contact','seed: contact','Divination',NULL,NULL,'23',NULL,'V, S','1 minute','See text','One creature',NULL,NULL,'200 minutes','None','No',NULL,NULL,NULL,NULL,NULL,'\n      <p>This seed forges a telepathic bond with a particular creature with which the caster is familiar (or one that the caster can currently see directly or through magical means) and can converse back and forth. The subject recognizes the caster if it knows him or her. It can answer in like manner immediately, though it does not have to. The caster can forge a communal bond among more than two creatures. For each additional creature contacted, increase the Spellcraft DC by +1. The bond can be established only among willing subjects, which therefore receive no saving throw or spell resistance. For telepathic communication through the bond regardless of language, increase the Spellcraft DC by +4. No special influence is established as a result of the bond, only the power to communicate at a distance.</p>\n      <p>At the base Spellcraft DC of 20, a caster can also use the <i>contact</i> seed to imbue an object (or creature) with a message he or she prepares that appears as written text for the spell\'s duration or is spoken aloud in a language the caster knows. The spoken message can be of any length, but the length of written text is limited to what can be contained (as text of a readable size) on the surface of the target. The message is delivered when specific conditions are fulfilled according to the caster\'s desire when the spell is cast.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Seed: Contact\" level=\"3\"><p><h3>Seed: Contact</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Divination<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>23<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 minute<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>See text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One creature<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>200 minutes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>This seed forges a telepathic bond with a particular creature with which the caster is familiar (or one that the caster can currently see directly or through magical means) and can converse back and forth. The subject recognizes the caster if it knows him or her. It can answer in like manner immediately, though it does not have to. The caster can forge a communal bond among more than two creatures. For each additional creature contacted, increase the Spellcraft DC by +1. The bond can be established only among willing subjects, which therefore receive no saving throw or spell resistance. For telepathic communication through the bond regardless of language, increase the Spellcraft DC by +4. No special influence is established as a result of the bond, only the power to communicate at a distance.</p><p>At the base Spellcraft DC of 20, a caster can also use the <i>contact</i> seed to imbue an object (or creature) with a message he or she prepares that appears as written text for the spell\'s duration or is spoken aloud in a language the caster knows. The spoken message can be of any length, but the length of written text is limited to what can be contained (as text of a readable size) on the surface of the target. The message is delivered when specific conditions are fulfilled according to the caster\'s desire when the spell is cast.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (70,'Seed: Delude','seed: delude','Illusion','Figment',NULL,'14',NULL,'V, S','1 minute','12,000 ft.',NULL,NULL,'Visual figment that can extend for up to twenty 30-ft. cubes (S)','Concentration plus 20 hours','Will disbelief (if interacted with)','No',NULL,NULL,NULL,NULL,NULL,'\n      <p>A spell developed with the <i>delude</i> seed creates the visual illusion of an object, creature, or force, as visualized by the caster. The caster can move the image within the limits of the size of the effect by concentrating (the image is otherwise stationary). The image disappears when struck by an opponent unless the caster causes the illusion to react appropriately. For an illusion that includes audible, olfactory, tactile, taste, and thermal aspects, increase the Spellcraft DC by +2 per extra aspect. Even realistic tactile and thermal illusions can\'t deal damage, however. For each additional image to be created, increase the Spellcraft DC by +1. For an illusion that follows a script determined by the caster, increase the Spellcraft DC by +9. The figment follows the script without the caster having to concentrate on it. The illusion can include intelligible speech if desired. For an illusion that makes any area appear to be something other than it is, increase the Spellcraft DC by +4. Additional components, such as sounds, can be added as noted above. Concealing creatures requires additional spell development using this or other seeds.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Seed: Delude\" level=\"3\"><p><h3>Seed: Delude</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Illusion (Figment)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>14<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 minute<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>12,000 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>Visual figment that can extend for up to twenty 30-ft. cubes (S)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Concentration plus 20 hours<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will disbelief (if interacted with)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>A spell developed with the <i>delude</i> seed creates the visual illusion of an object, creature, or force, as visualized by the caster. The caster can move the image within the limits of the size of the effect by concentrating (the image is otherwise stationary). The image disappears when struck by an opponent unless the caster causes the illusion to react appropriately. For an illusion that includes audible, olfactory, tactile, taste, and thermal aspects, increase the Spellcraft DC by +2 per extra aspect. Even realistic tactile and thermal illusions can\'t deal damage, however. For each additional image to be created, increase the Spellcraft DC by +1. For an illusion that follows a script determined by the caster, increase the Spellcraft DC by +9. The figment follows the script without the caster having to concentrate on it. The illusion can include intelligible speech if desired. For an illusion that makes any area appear to be something other than it is, increase the Spellcraft DC by +4. Additional components, such as sounds, can be added as noted above. Concealing creatures requires additional spell development using this or other seeds.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (71,'Seed: Destroy','seed: destroy','Transmutation',NULL,NULL,'29',NULL,'V, S','1 minute','12,000 ft.','One creature, or up to a 10-foot cube of nonliving matter',NULL,NULL,'Instantaneous','Fortitude half','Yes',NULL,NULL,NULL,NULL,NULL,'\n      <p>This seed deals 20d6 points of damage to the target. The damage is of no particular type or energy. For each additional 1d6 points of damage dealt, increase the Spellcraft DC by +2. If the target is reduced to -10 hit points or less (or a construct, object, or undead is reduced to 0 hit points), it is utterly destroyed as if disintegrated, leaving behind only a trace of fine dust. Up to a 10-foot cube of nonliving matter is affected, so a spell using the <i>Destroy</i> seed destroys only part of any very large object or structure targeted. The <i>Destroy</i> seed affects even magical matter, energy fields, and force effects that are normally only affected by the <i>disintegrate</i> spell. Such effects are automatically destroyed. Epic spells using the <i>Ward</i> seed may also be destroyed, though the caster must succeed at an opposed caster level check against the other spellcaster to bring down a <i>Ward</i> spell.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Seed: Destroy\" level=\"3\"><p><h3>Seed: Destroy</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>29<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 minute<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>12,000 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One creature, or up to a 10-foot cube of nonliving matter<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Fortitude half<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>This seed deals 20d6 points of damage to the target. The damage is of no particular type or energy. For each additional 1d6 points of damage dealt, increase the Spellcraft DC by +2. If the target is reduced to -10 hit points or less (or a construct, object, or undead is reduced to 0 hit points), it is utterly destroyed as if disintegrated, leaving behind only a trace of fine dust. Up to a 10-foot cube of nonliving matter is affected, so a spell using the <i>Destroy</i> seed destroys only part of any very large object or structure targeted. The <i>Destroy</i> seed affects even magical matter, energy fields, and force effects that are normally only affected by the <i>disintegrate</i> spell. Such effects are automatically destroyed. Epic spells using the <i>Ward</i> seed may also be destroyed, though the caster must succeed at an opposed caster level check against the other spellcaster to bring down a <i>Ward</i> spell.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (72,'Seed: Dispel','seed: dispel','Abjuration',NULL,NULL,'19',NULL,'V, S','1 minute','300 ft.','One creature, object, or spell',NULL,NULL,'Instantaneous','None','No',NULL,NULL,NULL,NULL,NULL,'\n      <p>This seed can end ongoing spells that have been cast on a creature or object, temporarily suppress the magical abilities of a magic item, or end ongoing spells (or at least their effects) within an area. A dispelled spell ends as if its duration had expired. The <i>Dispel</i> seed can defeat all spells, even those not normally subject to <i>dispel magic</i>. The <i>Dispel</i> seed can dispel (but not counter) the ongoing effects of supernatural abilities as well as spells, and it affects spell-like effects just as it affects spells. One creature, object, or spell is the target of the <i>Dispel</i> seed. The caster makes a dispel check against the spell or against each ongoing spell currently in effect on the object or creature. A dispel check is 1d20 + 10 against a DC of 11 + the target spell\'s caster level. For each additional +1 on the dispel check, increase the Spellcraft DC by +1. If targeting an object or creature that is the effect of an ongoing spell, make a dispel check to end the spell that affects the object or creature. If the object targeted is a magic item, make a dispel check against the item\'s caster level. If succeessful, all the item\'s magical properties are suppressed for 1d4 rounds, after which the item recovers on its own. A suppressed item becomes nonmagical for the duration of the effect. An interdimensional interface is temporarily closed. A magic item\'s physical properties are unchanged. Any creature, object, or spell is potentially subject to the <i>Dispel</i> seed, even the spells of gods and the abilities of artifacts. A character automatically succeeds on the dispel check against any spell that he or she cast him or her self.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Seed: Dispel\" level=\"3\"><p><h3>Seed: Dispel</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Abjuration<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>19<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 minute<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>300 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One creature, object, or spell<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>This seed can end ongoing spells that have been cast on a creature or object, temporarily suppress the magical abilities of a magic item, or end ongoing spells (or at least their effects) within an area. A dispelled spell ends as if its duration had expired. The <i>Dispel</i> seed can defeat all spells, even those not normally subject to <i>dispel magic</i>. The <i>Dispel</i> seed can dispel (but not counter) the ongoing effects of supernatural abilities as well as spells, and it affects spell-like effects just as it affects spells. One creature, object, or spell is the target of the <i>Dispel</i> seed. The caster makes a dispel check against the spell or against each ongoing spell currently in effect on the object or creature. A dispel check is 1d20 + 10 against a DC of 11 + the target spell\'s caster level. For each additional +1 on the dispel check, increase the Spellcraft DC by +1. If targeting an object or creature that is the effect of an ongoing spell, make a dispel check to end the spell that affects the object or creature. If the object targeted is a magic item, make a dispel check against the item\'s caster level. If succeessful, all the item\'s magical properties are suppressed for 1d4 rounds, after which the item recovers on its own. A suppressed item becomes nonmagical for the duration of the effect. An interdimensional interface is temporarily closed. A magic item\'s physical properties are unchanged. Any creature, object, or spell is potentially subject to the <i>Dispel</i> seed, even the spells of gods and the abilities of artifacts. A character automatically succeeds on the dispel check against any spell that he or she cast him or her self.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (73,'Seed: Energy','seed: energy','Evocation',NULL,'Acid, Fire, Electricity, Cold, or Sonic','19',NULL,'V, S','1 minute','300 ft. or touched creature or object of 2,000 lb. or less',NULL,'A bolt 5 ft. wide to 300 ft. long; or a 10-ft. -radius emanation; or a wall whose area is up to one 200-ft. square; or a sphere or hemi-sphere with a radius of up to 20 ft.',NULL,'Instantaneous or 20 hours (see text)','Reflex half','Yes',NULL,NULL,NULL,NULL,NULL,'\n      <p>This seed uses whichever one of five energy types the caster chooses: acid, cold, electricity, fire, or sonic. The caster can cast the energy forth as a bolt, imbue an object with the energy, or create a freestanding manifestation of the energy. If the spell developed using the <i>energy</i> seed releases a bolt, that bolt instantaneously deals 10d6 points of damage of the appropriate energy type, and all in the bolt\'s area must make a Reflex save for half damage. For each additional 1d6 points of damage dealt, increase the Spellcraft DC by +2. The bolt begins at the caster\'s fingertips. To imbue another creature with the ability to use an energy bolt as a spell-like ability at its option or when a particular condition is met, increase the Spellcraft DC by +25. The caster can also cause a creature or object to emanate the specific energy type out to a radius of 10 feet for 20 hours. The emanated energy deals 2d6 points of energy damage per round against unprotected creatures (the target creature is susceptible if not separately warded or otherwise resistant to the energy). For each additional 1d6 points of damage emanated, increase the Spellcraft DC by +2. The caster may also create a wall, half-circle, circle, dome, or sphere of the desired energy that emanates the energy for up to 20 hours. One side of the wall, selected by the caster, sends forth waves of energy, dealing 2d4 points of energy damage to creatures within 10 feet and 1d4 points of energy damage to those past 10 feet but within 20 feet. The wall deals this damage when it appears and in each round that a creature enters or remains in the area. In addition, the wall deals 2d6+20 points of energy damage to any creature passing through it. The wall deals double damage to undead creatures. For each additional 1d4 points of damage, increase the Spellcraft DC by +2.</p>\n      <p>The caster can also use the <i>energy</i> seed to create a spell that carefully releases and balances the emanation of cold, electricity, and fire, creating specific weather effects for a period of 20 hours. Using the <i>energy</i> seed this way has a base Spellcraft DC of 25. The area extends to a two-mile-radius centered on the caster. Once the spell is cast, the weather takes 10 minutes to manifest. Ordinarily, a caster can\'t directly target a creature or object, though indirect effects are possible. This seed can create cold snaps, heat waves, thunderstorms, fogs, blizzards-even a tornado that moves randomly in the affected area. Creating targeted damaging effects requires an additional use of the <i>energy</i> seed.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Seed: Energy\" level=\"3\"><p><h3>Seed: Energy</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Acid, Fire, Electricity, Cold, or Sonic]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>19<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 minute<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>300 ft. or touched creature or object of 2,000 lb. or less<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>A bolt 5 ft. wide to 300 ft. long; or a 10-ft. -radius emanation; or a wall whose area is up to one 200-ft. square; or a sphere or hemi-sphere with a radius of up to 20 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous or 20 hours (see text)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Reflex half<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>This seed uses whichever one of five energy types the caster chooses: acid, cold, electricity, fire, or sonic. The caster can cast the energy forth as a bolt, imbue an object with the energy, or create a freestanding manifestation of the energy. If the spell developed using the <i>energy</i> seed releases a bolt, that bolt instantaneously deals 10d6 points of damage of the appropriate energy type, and all in the bolt\'s area must make a Reflex save for half damage. For each additional 1d6 points of damage dealt, increase the Spellcraft DC by +2. The bolt begins at the caster\'s fingertips. To imbue another creature with the ability to use an energy bolt as a spell-like ability at its option or when a particular condition is met, increase the Spellcraft DC by +25. The caster can also cause a creature or object to emanate the specific energy type out to a radius of 10 feet for 20 hours. The emanated energy deals 2d6 points of energy damage per round against unprotected creatures (the target creature is susceptible if not separately warded or otherwise resistant to the energy). For each additional 1d6 points of damage emanated, increase the Spellcraft DC by +2. The caster may also create a wall, half-circle, circle, dome, or sphere of the desired energy that emanates the energy for up to 20 hours. One side of the wall, selected by the caster, sends forth waves of energy, dealing 2d4 points of energy damage to creatures within 10 feet and 1d4 points of energy damage to those past 10 feet but within 20 feet. The wall deals this damage when it appears and in each round that a creature enters or remains in the area. In addition, the wall deals 2d6+20 points of energy damage to any creature passing through it. The wall deals double damage to undead creatures. For each additional 1d4 points of damage, increase the Spellcraft DC by +2.</p><p>The caster can also use the <i>energy</i> seed to create a spell that carefully releases and balances the emanation of cold, electricity, and fire, creating specific weather effects for a period of 20 hours. Using the <i>energy</i> seed this way has a base Spellcraft DC of 25. The area extends to a two-mile-radius centered on the caster. Once the spell is cast, the weather takes 10 minutes to manifest. Ordinarily, a caster can\'t directly target a creature or object, though indirect effects are possible. This seed can create cold snaps, heat waves, thunderstorms, fogs, blizzards-even a tornado that moves randomly in the affected area. Creating targeted damaging effects requires an additional use of the <i>energy</i> seed.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (74,'Seed: Foresee','seed: foresee','Divination',NULL,NULL,'17',NULL,'V, S','1 minute','Personal','You',NULL,NULL,'Instantaneous or concentration (see text)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <p>The caster can foretell the immediate future, or gain information about specific questions. He or she is 90% likely to receive a meaningful reading of the future of the next 30 minutes. If successful, the caster knows if a particular action will bring good results, bad results, or no result. For each additional 30 minutes into the future, multiply the Spellcraft DC by x2. For better results, the caster can pose up to ten specific questions (one per round while he or she concentrates) to unknown powers of other planes, but the base Spellcraft DC for such an attempt is 23.  The answers return in a language the caster understands, but use only one-word replies: \'yes,\' \'no,\' \'maybe,\' \'never,\' \'irrelevant,\' or some other one-word answer. Unlike 0- to 9th-level spells of similar type, all questions answered are 90% likely to be answered truthfully. However, a specific spell using the <i>foresee</i> seed can only be cast once every five weeks. The <i>foresee</i> seed is also useful for epic spells requiring specific information before functioning, such as spells using the <i>reveal</i> and <i>Transport</i> seeds. The <i>foresee</i> seed can also be used to gain one basic piece of information about a living target: level, class, alignment, or some special ability (or one of an object\'s magical abilities, if any). For each additional piece of information revealed, increase the Spellcraft DC by +2.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Seed: Foresee\" level=\"3\"><p><h3>Seed: Foresee</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Divination<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>17<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 minute<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous or concentration (see text)<br/></td></tr></table><p>The caster can foretell the immediate future, or gain information about specific questions. He or she is 90% likely to receive a meaningful reading of the future of the next 30 minutes. If successful, the caster knows if a particular action will bring good results, bad results, or no result. For each additional 30 minutes into the future, multiply the Spellcraft DC by x2. For better results, the caster can pose up to ten specific questions (one per round while he or she concentrates) to unknown powers of other planes, but the base Spellcraft DC for such an attempt is 23.  The answers return in a language the caster understands, but use only one-word replies: \'yes,\' \'no,\' \'maybe,\' \'never,\' \'irrelevant,\' or some other one-word answer. Unlike 0- to 9th-level spells of similar type, all questions answered are 90% likely to be answered truthfully. However, a specific spell using the <i>foresee</i> seed can only be cast once every five weeks. The <i>foresee</i> seed is also useful for epic spells requiring specific information before functioning, such as spells using the <i>reveal</i> and <i>Transport</i> seeds. The <i>foresee</i> seed can also be used to gain one basic piece of information about a living target: level, class, alignment, or some special ability (or one of an object\'s magical abilities, if any). For each additional piece of information revealed, increase the Spellcraft DC by +2.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (75,'Seed: Fortify','seed: fortify','Transmutation',NULL,NULL,'17 (see text)',NULL,'V, S','1 minute','Touch','Creature touched',NULL,NULL,'20 hours; permanent for age adjustment','Will negates (harmless)','Yes (harmless)',NULL,NULL,NULL,NULL,NULL,'\n      <p>Spells using the <i>fortify</i> seed grant a +1 enhancement bonus to whichever one of the following the caster chooses:</p>\n      <ul>\n <li>Any one ability score.</li>\n <li>Any one kind of saving throw.</li>\n <li>Spell resistance.</li>\n <li>Natural armor.</li>\n</ul>\n      <p>The <i>fortify</i> seed can also grant energy resistance 1 for one energy type or 1 temporary hit point. For each additional +1 bonus, point of energy resistance, or hit point, increase the Spellcraft DC by +2.</p>\n      <p>The <i>fortify</i> seed has a base Spellcraft DC of 23 if it grants a +1 bonus of a type other than enhancement. For each additional +1 bonus of a type other than enhancement, increase the Spellcraft DC by +6. If the caster applies a factor to make the duration permanent, the bonus must be an inherent bonus, and the maximum inherent bonus allowed is +5.</p>\n      <p>The <i>fortify</i> seed has a base Spellcraft DC of 27 if it grants a creature a +1 bonus to an ability score or other statistic it does not possess. For each additional +1 bonus, increase the Spellcraft DC by +4. If a spell with the <i>fortify</i> seed grants an inanimate object an ability score it would not normally possess (such as Intelligence), the spell must also incorporate the <i>life</i> seed.</p>\n      <p>Granting spell resistance to a creature that doesn\'t already have it is a special case; the base Spellcraft DC of 27 grants spell resistance 25, and each additional point of spell resistance increases the Spellcraft DC by +4 (each -1 to spell resistance reduces the Spellcraft DC by -2).</p>\n      <p>The <i>fortify</i> seed can also grant damage reduction 1/magic. For each additional point of damage reduction, increase the Spellcraft DC by +2. To increase the damage reduction value to epic, increase the Spellcraft DC by +15.</p>\n      <p>A special use of the <i>fortify</i> seed grants the target a permanent +1 year to its current age category. For each additional +1 year added to the creature\'s current age category, increase the Spellcraft DC by +2. Incremental adjustments to a creature\'s maximum age do not stack; they overlap. When a spell increases a creature\'s current age category, all higher age categories are also adjusted accordingly.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Seed: Fortify\" level=\"3\"><p><h3>Seed: Fortify</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>17 (see text)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 minute<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>20 hours; permanent for age adjustment<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr></table><p>Spells using the <i>fortify</i> seed grant a +1 enhancement bonus to whichever one of the following the caster chooses:</p><ul>\n <li>Any one ability score.</li>\n <li>Any one kind of saving throw.</li>\n <li>Spell resistance.</li>\n <li>Natural armor.</li>\n</ul><p>The <i>fortify</i> seed can also grant energy resistance 1 for one energy type or 1 temporary hit point. For each additional +1 bonus, point of energy resistance, or hit point, increase the Spellcraft DC by +2.</p><p>The <i>fortify</i> seed has a base Spellcraft DC of 23 if it grants a +1 bonus of a type other than enhancement. For each additional +1 bonus of a type other than enhancement, increase the Spellcraft DC by +6. If the caster applies a factor to make the duration permanent, the bonus must be an inherent bonus, and the maximum inherent bonus allowed is +5.</p><p>The <i>fortify</i> seed has a base Spellcraft DC of 27 if it grants a creature a +1 bonus to an ability score or other statistic it does not possess. For each additional +1 bonus, increase the Spellcraft DC by +4. If a spell with the <i>fortify</i> seed grants an inanimate object an ability score it would not normally possess (such as Intelligence), the spell must also incorporate the <i>life</i> seed.</p><p>Granting spell resistance to a creature that doesn\'t already have it is a special case; the base Spellcraft DC of 27 grants spell resistance 25, and each additional point of spell resistance increases the Spellcraft DC by +4 (each -1 to spell resistance reduces the Spellcraft DC by -2).</p><p>The <i>fortify</i> seed can also grant damage reduction 1/magic. For each additional point of damage reduction, increase the Spellcraft DC by +2. To increase the damage reduction value to epic, increase the Spellcraft DC by +15.</p><p>A special use of the <i>fortify</i> seed grants the target a permanent +1 year to its current age category. For each additional +1 year added to the creature\'s current age category, increase the Spellcraft DC by +2. Incremental adjustments to a creature\'s maximum age do not stack; they overlap. When a spell increases a creature\'s current age category, all higher age categories are also adjusted accordingly.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (76,'Seed: Heal','seed: heal','Conjuration','Healing',NULL,'25',NULL,'V, S, DF','1 minute','Touch','Creature touched',NULL,NULL,'Instantaneous','Yes (harmless; see text)','Yes (harmless)',NULL,NULL,NULL,NULL,NULL,'\n      <p>Spells developed with the <i>heal</i> seed channel positive energy into a creature to wipe away disease and injury. Such a spell completely cures all diseases, blindness, deafness, hit point damage, and temporary ability damage. To restore permanently drained ability score points, increase the Spellcraft DC by +6. The <i>heal</i> seed neutralizes poisons in the subject\'s system so that no additional damage or effects are suffered. It offsets feeblemindedness and cures mental disorders caused by spells or injury to the brain. It dispels all magical effects penalizing the character\'s abilities, including effects caused by spells, even epic spells developed with the <i>afflict</i> seed. Only a single application of the spell is needed to simultaneously achieve all these effects. This seed does not restore levels or Constitution points lost due to death. To dispel all negative levels afflicting the target, increase the Spellcraft DC by +2. This reverses level drains by a force or creature. The drained levels are restored only if the creature lost the levels within the last 20 weeks. For each additional week since the levels were drained, increase the Spellcraft DC by +2.</p>\n      <p>Against undead, the influx of positive energy causes the loss of all but 1d4 hit points if the undead fails a Fortitude saving throw.</p>\n      <p>An epic caster with 24 ranks in Knowledge (arcana), Knowledge (nature), or Knowledge (religion) can cast a spell developed with a special version of the heal seed that flushes negative energy into the subject, healing undead completely but causing the loss of all but 1d4 hit points in living creatures if they fail a Fortitude saving throw. Alternatively, a living target that fails its Fortitude saving throw could gain four negative levels for the next 8 hours. For each additional negative level bestowed, increase the Spellcraft DC by +4, and for each extra hour the negative levels persist, increase the Spellcraft DC by +2. If the subject has at least as many negative levels as Hit Dice, it dies. If the subject survives and the negative levels persist for 24 hours or longer, the subject must make another Fortitude saving throw, or the negative levels are converted to actual level loss.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Seed: Heal\" level=\"3\"><p><h3>Seed: Heal</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Healing)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>25<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 minute<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Yes (harmless; see text)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr></table><p>Spells developed with the <i>heal</i> seed channel positive energy into a creature to wipe away disease and injury. Such a spell completely cures all diseases, blindness, deafness, hit point damage, and temporary ability damage. To restore permanently drained ability score points, increase the Spellcraft DC by +6. The <i>heal</i> seed neutralizes poisons in the subject\'s system so that no additional damage or effects are suffered. It offsets feeblemindedness and cures mental disorders caused by spells or injury to the brain. It dispels all magical effects penalizing the character\'s abilities, including effects caused by spells, even epic spells developed with the <i>afflict</i> seed. Only a single application of the spell is needed to simultaneously achieve all these effects. This seed does not restore levels or Constitution points lost due to death. To dispel all negative levels afflicting the target, increase the Spellcraft DC by +2. This reverses level drains by a force or creature. The drained levels are restored only if the creature lost the levels within the last 20 weeks. For each additional week since the levels were drained, increase the Spellcraft DC by +2.</p><p>Against undead, the influx of positive energy causes the loss of all but 1d4 hit points if the undead fails a Fortitude saving throw.</p><p>An epic caster with 24 ranks in Knowledge (arcana), Knowledge (nature), or Knowledge (religion) can cast a spell developed with a special version of the heal seed that flushes negative energy into the subject, healing undead completely but causing the loss of all but 1d4 hit points in living creatures if they fail a Fortitude saving throw. Alternatively, a living target that fails its Fortitude saving throw could gain four negative levels for the next 8 hours. For each additional negative level bestowed, increase the Spellcraft DC by +4, and for each extra hour the negative levels persist, increase the Spellcraft DC by +2. If the subject has at least as many negative levels as Hit Dice, it dies. If the subject survives and the negative levels persist for 24 hours or longer, the subject must make another Fortitude saving throw, or the negative levels are converted to actual level loss.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (77,'Seed: Life','seed: life','Conjuration','Healing',NULL,'27',NULL,'V, S, DF','1 minute','Touch','Dead creature touched',NULL,NULL,'Instantaneous','None (see text)','Yes (harmless)',NULL,NULL,NULL,NULL,NULL,'\n      <p>A spell developed with the <i>life</i> seed will restore life and complete vigor to any deceased creature. The condition of the remains is not a factor. So long as some small portion of the creature\'s body still exists, it can be returned to life, but the portion receiving the spell must have been part of the creature\'s body at the time of death. (The remains of a creature hit by a <i>disintegrate</i> spell count as a small portion of its body.) The creature can have been dead for no longer than two hundred years. For each additional ten years, increase the Spellcraft DC by +1. The creature is immediately restored to full hit points, vigor, and health, with no loss of prepared spells. However, the subject loses one level (or 1 point of Constitution if the subject was 1st level). The life seed cannot revive someone who has died of old age.</p>\n      <p>An epic caster with 24 ranks in Knowledge (arcana), Knowledge (nature), or Knowledge (religion) can cast a spell developed with a special version of the life seed that gives actual life to normally inanimate objects. The caster can give inanimate plants and animals a soul, personality, and humanlike sentience. To succeed, the caster must make a Will save (DC 10 + the target\'s Hit Dice, or the Hit Dice a plant will have once it comes to life).</p>\n      <p>The newly living object, intelligent animal, or sentient plant is friendly toward the caster. An object or plant has characteristics as if it were an animated object, except that its Intelligence, Wisdom, and Charisma scores are all 3d6. Animated objects and plants gain the ability to move their limbs, projections, roots, carved legs and arms, or other appendages, and have senses similar to a human\'s. A newly intelligent animal gets 3d6 Intelligence, +1d3 Charisma, and +2 HD. Objects, animals, and plants speak one language that the caster knows, plus one additional language that he or she knows per point of Intelligence bonus (if any).</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Seed: Life\" level=\"3\"><p><h3>Seed: Life</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Healing)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>27<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 minute<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Dead creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None (see text)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr></table><p>A spell developed with the <i>life</i> seed will restore life and complete vigor to any deceased creature. The condition of the remains is not a factor. So long as some small portion of the creature\'s body still exists, it can be returned to life, but the portion receiving the spell must have been part of the creature\'s body at the time of death. (The remains of a creature hit by a <i>disintegrate</i> spell count as a small portion of its body.) The creature can have been dead for no longer than two hundred years. For each additional ten years, increase the Spellcraft DC by +1. The creature is immediately restored to full hit points, vigor, and health, with no loss of prepared spells. However, the subject loses one level (or 1 point of Constitution if the subject was 1st level). The life seed cannot revive someone who has died of old age.</p><p>An epic caster with 24 ranks in Knowledge (arcana), Knowledge (nature), or Knowledge (religion) can cast a spell developed with a special version of the life seed that gives actual life to normally inanimate objects. The caster can give inanimate plants and animals a soul, personality, and humanlike sentience. To succeed, the caster must make a Will save (DC 10 + the target\'s Hit Dice, or the Hit Dice a plant will have once it comes to life).</p><p>The newly living object, intelligent animal, or sentient plant is friendly toward the caster. An object or plant has characteristics as if it were an animated object, except that its Intelligence, Wisdom, and Charisma scores are all 3d6. Animated objects and plants gain the ability to move their limbs, projections, roots, carved legs and arms, or other appendages, and have senses similar to a human\'s. A newly intelligent animal gets 3d6 Intelligence, +1d3 Charisma, and +2 HD. Objects, animals, and plants speak one language that the caster knows, plus one additional language that he or she knows per point of Intelligence bonus (if any).</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (78,'Seed: Reflect','seed: reflect','Abjuration',NULL,NULL,'27',NULL,'V, S','1 minute','Personal','You',NULL,NULL,'Until expended or 12 hours',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <p>Attacks targeted against the caster rebound on the original attacker. Each use of the <i>reflect</i> seed in an epic spell is effective against one type of attack only: spells (and spell-like effects), ranged attacks, or melee attacks. To reflect an area spell, where the caster is not the target but are caught in the vicinity, increase the Spellcraft DC by +20. A single successful use of <i>reflect</i> expends its protection. Spells developed with the <i>reflect</i> seed against spells and spell-like effects return all spell effects of up to 1st level. For each additional level of spells to be reflected, increase the Spellcraft DC by +20. Epic spells are treated as 10th-level spells for this purpose.</p>\n      <p>The desired effect is automatically reflected if the spell in question is 9th level or lower. An opposed caster level check is required when the reflect seed is used against another epic spell. If the enemy spellcaster gets his or her spell through by winning the caster level check, the epic spell using the reflect seed is not expended, just momentarily suppressed.</p>\n      <p>If the <i>reflect</i> seed is used against a melee attack or ranged attack, five such attacks are automatically reflected back on the original attacker. For each additional attack reflected, increase the Spellcraft DC by +4. The reflected attack rebounds on the attacker using the same attack roll. Once the allotted attacks are reflected, the spell using the <i>reflect</i> seed is expended.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Seed: Reflect\" level=\"3\"><p><h3>Seed: Reflect</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Abjuration<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>27<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 minute<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Until expended or 12 hours<br/></td></tr></table><p>Attacks targeted against the caster rebound on the original attacker. Each use of the <i>reflect</i> seed in an epic spell is effective against one type of attack only: spells (and spell-like effects), ranged attacks, or melee attacks. To reflect an area spell, where the caster is not the target but are caught in the vicinity, increase the Spellcraft DC by +20. A single successful use of <i>reflect</i> expends its protection. Spells developed with the <i>reflect</i> seed against spells and spell-like effects return all spell effects of up to 1st level. For each additional level of spells to be reflected, increase the Spellcraft DC by +20. Epic spells are treated as 10th-level spells for this purpose.</p><p>The desired effect is automatically reflected if the spell in question is 9th level or lower. An opposed caster level check is required when the reflect seed is used against another epic spell. If the enemy spellcaster gets his or her spell through by winning the caster level check, the epic spell using the reflect seed is not expended, just momentarily suppressed.</p><p>If the <i>reflect</i> seed is used against a melee attack or ranged attack, five such attacks are automatically reflected back on the original attacker. For each additional attack reflected, increase the Spellcraft DC by +4. The reflected attack rebounds on the attacker using the same attack roll. Once the allotted attacks are reflected, the spell using the <i>reflect</i> seed is expended.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (79,'Seed: Reveal','seed: reveal','Divination',NULL,NULL,'19 (see text)',NULL,'V, S','1 minute','See text',NULL,NULL,'Magical sensor','20 minutes (D)','None','No',NULL,NULL,NULL,NULL,NULL,'\n      <p>The caster of this seed can see some distant location or hear the sounds at some distant location almost as if he or she was there. To both hear and see, increase the Spellcraft DC by +2. Distance is not a factor, but the locale must be known-a place familiar to the caster or an obvious one. The spell creates an invisible sensor that can be dispelled. Lead sheeting or magical protection blocks the spell, and the caster senses that the spell is so blocked. If the caster prefers to create a mobile sensor (speed 30 feet) that he or she controls, increase the Spellcraft DC by +2. To use the <i>reveal</i> seed to reach one specific different plane of existence, increase the Spellcraft DC by +8. To allow magically enhanced senses to work through a spell built with the <i>reveal</i> seed, increase the Spellcraft DC by +4. To cast any spell from the sensor whose range is touch or greater, increase the Spellcraft DC by +6; however, the caster must maintain line of effect to the sensor at all times. If the line of effect is obstructed, the spell ends. To free the caster of the line of effect restriction for casting spells through the sensor, multiply the Spellcraft DC by x10.</p>\n      <p>The <i>reveal</i> seed has a base Spellcraft DC of 25 if used to pierce illusions and see things as they really are. The caster can see through normal and magical darkness, notice secret doors hidden by magic, see the exact locations of creatures or objects under <i>blur</i> or <i>displacement</i> effects, see invisible creatures or objects normally, see through illusions, see onto the Ethereal Plane (but not into extradimensional spaces), and see the true form of polymorphed, changed, or transmuted things. The range of such sight is 120 feet.</p>\n      <p>The <i>reveal</i> seed can also be used to develop spells that will do any one of the following: duplicate the <i>read magic</i> spell, comprehend the written and verbal language of another, or speak in the written or verbal language of another. To both comprehend and speak a language, increase the Spellcraft DC by +4.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Seed: Reveal\" level=\"3\"><p><h3>Seed: Reveal</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Divination<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>19 (see text)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 minute<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>See text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>Magical sensor<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>20 minutes (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>The caster of this seed can see some distant location or hear the sounds at some distant location almost as if he or she was there. To both hear and see, increase the Spellcraft DC by +2. Distance is not a factor, but the locale must be known-a place familiar to the caster or an obvious one. The spell creates an invisible sensor that can be dispelled. Lead sheeting or magical protection blocks the spell, and the caster senses that the spell is so blocked. If the caster prefers to create a mobile sensor (speed 30 feet) that he or she controls, increase the Spellcraft DC by +2. To use the <i>reveal</i> seed to reach one specific different plane of existence, increase the Spellcraft DC by +8. To allow magically enhanced senses to work through a spell built with the <i>reveal</i> seed, increase the Spellcraft DC by +4. To cast any spell from the sensor whose range is touch or greater, increase the Spellcraft DC by +6; however, the caster must maintain line of effect to the sensor at all times. If the line of effect is obstructed, the spell ends. To free the caster of the line of effect restriction for casting spells through the sensor, multiply the Spellcraft DC by x10.</p><p>The <i>reveal</i> seed has a base Spellcraft DC of 25 if used to pierce illusions and see things as they really are. The caster can see through normal and magical darkness, notice secret doors hidden by magic, see the exact locations of creatures or objects under <i>blur</i> or <i>displacement</i> effects, see invisible creatures or objects normally, see through illusions, see onto the Ethereal Plane (but not into extradimensional spaces), and see the true form of polymorphed, changed, or transmuted things. The range of such sight is 120 feet.</p><p>The <i>reveal</i> seed can also be used to develop spells that will do any one of the following: duplicate the <i>read magic</i> spell, comprehend the written and verbal language of another, or speak in the written or verbal language of another. To both comprehend and speak a language, increase the Spellcraft DC by +4.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (80,'Seed: Slay','seed: slay','Necromancy',NULL,'Death','25',NULL,'V, S','1 minute','300 ft.','One living creature',NULL,NULL,'Instantaneous','Fortitude partial or half (see text)','Yes',NULL,NULL,NULL,NULL,NULL,'\n      <p>A spell developed using the <i>Slay</i> seed snuffs out the life force of a living creature, killing it instantly. The <i>Slay</i> seed kills a creature of up to 80 HD. The subject is entitled to a Fortitude saving throw to survive the attack. If the save is successful, it instead takes 3d6+20 points of damage. For each additional 80 HD affected (or each additional creature affected), increase the Spellcraft DC by +8. Alternatively, a caster can use the <i>Slay</i> seed in an epic spell to suppress the life force of the target by bestowing 2d4 negative levels on the target (or half as many negative levels on a successful Fortitude save). For each additional 1d4 negative levels bestowed, increase the Spellcraft DC by +4. If the subject has at least as many negative levels as Hit Dice, it dies. If the subject survives and the negative levels persist for 24 hours or longer, the subject must make another Fortitude saving throw, or the negative levels are converted to actual level loss.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Seed: Slay\" level=\"3\"><p><h3>Seed: Slay</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Necromancy [Death]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>25<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 minute<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>300 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One living creature<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Fortitude partial or half (see text)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>A spell developed using the <i>Slay</i> seed snuffs out the life force of a living creature, killing it instantly. The <i>Slay</i> seed kills a creature of up to 80 HD. The subject is entitled to a Fortitude saving throw to survive the attack. If the save is successful, it instead takes 3d6+20 points of damage. For each additional 80 HD affected (or each additional creature affected), increase the Spellcraft DC by +8. Alternatively, a caster can use the <i>Slay</i> seed in an epic spell to suppress the life force of the target by bestowing 2d4 negative levels on the target (or half as many negative levels on a successful Fortitude save). For each additional 1d4 negative levels bestowed, increase the Spellcraft DC by +4. If the subject has at least as many negative levels as Hit Dice, it dies. If the subject survives and the negative levels persist for 24 hours or longer, the subject must make another Fortitude saving throw, or the negative levels are converted to actual level loss.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (81,'Seed: Summon','seed: summon','Conjuration','Summoning',NULL,'14',NULL,'V, S','1 minute','75 ft.',NULL,NULL,'One summoned creature','20 rounds (D)','Will negates (see text)','Yes (see text)',NULL,NULL,NULL,NULL,NULL,'\n      <p>This seed can summon an outsider. It appears where the caster designates and acts immediately, on his or her turn, if its spell resistance is overcome and it fails a Will saving throw. It attacks the caster\'s opponents to the best of its ability. If the caster can communicate with the outsider, he or she can direct it not to attack, to attack particular enemies, or to perform other actions. The spell conjures an outsider the caster selects of CR 2 or less. For each +1 CR of the summoned outsider, increase the Spellcraft DC by +2. For each additional outsider of the same Challenge Rating summoned, multiply the Spellcraft DC by x2. When a caster develops a spell with the <i>summon</i> seed that summons an air, chaotic, earth, evil, fire, good, lawful, or water creature, the completed spell is also of that type.</p>\n      <p>If the caster increases the Spellcraft DC by +10, he or she can summon a creature of CR 2 or less from another monster type or subtype. The summoned creature is assumed to have been plucked from some other plane (or somewhere on the same plane). The summoned creature attacks the caster\'s opponents to the best of its ability; or, if the caster can communicate with it, it will perform other actions. However, the summoning ends if the creature is asked to perform a task inimical to its nature. For each +1 CR of the summoned creature, increase the Spellcraft DC by +2.</p>\n      <p>Finally, by increasing the Spellcraft DC by +60, the caster can summon a unique individual he or she specifies from anywhere in the multiverse. The caster must know the target\'s name and some facts about its life, defeat any magical protection against discovery or other protection possessed by the target, and overcome the target\'s spell resistance, and it must fail a Will saving throw. The target is under no special compulsion to serve the caster.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Seed: Summon\" level=\"3\"><p><h3>Seed: Summon</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Summoning)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>14<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 minute<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>75 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>One summoned creature<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>20 rounds (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (see text)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (see text)<br/></td></tr></table><p>This seed can summon an outsider. It appears where the caster designates and acts immediately, on his or her turn, if its spell resistance is overcome and it fails a Will saving throw. It attacks the caster\'s opponents to the best of its ability. If the caster can communicate with the outsider, he or she can direct it not to attack, to attack particular enemies, or to perform other actions. The spell conjures an outsider the caster selects of CR 2 or less. For each +1 CR of the summoned outsider, increase the Spellcraft DC by +2. For each additional outsider of the same Challenge Rating summoned, multiply the Spellcraft DC by x2. When a caster develops a spell with the <i>summon</i> seed that summons an air, chaotic, earth, evil, fire, good, lawful, or water creature, the completed spell is also of that type.</p><p>If the caster increases the Spellcraft DC by +10, he or she can summon a creature of CR 2 or less from another monster type or subtype. The summoned creature is assumed to have been plucked from some other plane (or somewhere on the same plane). The summoned creature attacks the caster\'s opponents to the best of its ability; or, if the caster can communicate with it, it will perform other actions. However, the summoning ends if the creature is asked to perform a task inimical to its nature. For each +1 CR of the summoned creature, increase the Spellcraft DC by +2.</p><p>Finally, by increasing the Spellcraft DC by +60, the caster can summon a unique individual he or she specifies from anywhere in the multiverse. The caster must know the target\'s name and some facts about its life, defeat any magical protection against discovery or other protection possessed by the target, and overcome the target\'s spell resistance, and it must fail a Will saving throw. The target is under no special compulsion to serve the caster.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (82,'Seed: Transform','seed: transform','Transmutation',NULL,NULL,'21',NULL,'V, S','1 minute','300 ft.','One creature or inanimate, nonmagical object',NULL,NULL,'Permanent','Fortitude negates (see text)','Yes',NULL,NULL,NULL,NULL,NULL,'\n      <p>Spells using the <i>transform</i> seed change the subject into another form of creature or object. The new form can range in size from Diminutive to one size larger than the subject\'s normal form. For each additional increment of size change, increase the Spellcraft DC by +6. If the caster wants to transform a nonmagical, inanimate object into a creature of his or her type or transform a creature into a nonmagical, inanimate object, increase the Spellcraft DC by +10. To change a creature of one type into another type increase the Spellcraft DC by +5.</p>\n      <p>Transformations involving nonmagical, inanimate substances with hardness are more difficult; for each 2 points of hardness, increase the Spellcraft DC by +1.</p>\n      <p>To transform a creature into an incorporeal or gaseous form, increase the Spellcraft DC by +10. Conversely, to overcome the natural immunity of a gaseous or incorporeal creature to transformation, increase the Spellcraft DC by +10.</p>\n      <p>The <i>transform</i> seed can also change its target into someone specific. To transform an object or creature into the specific likeness of another individual (including memories and mental abilities), increase the Spellcraft DC by +25. If the transformed creature doesn\'t have the level or Hit Dice of its new likeness, it can only use the abilities of the creature at its own level or Hit Dice. If slain or destroyed, the transformed creature or object reverts to its original form. The subject\'s equipment, if any, remains untransformed or melds into the new form\'s body, at the caster\'s option. The transformed creature or object acquires the physical and natural abilities of the creature or object it has been changed into while retaining its own memories and mental ability scores. Mental abilities include personality, Intelligence, Wisdom, and Charisma scores, level and class, hit points (despite any change in its Constitution score), alignment, base attack bonus, base saves, extraordinary abilities, spells, and spell-like abilities, but not its supernatural abilities. Physical abilities include natural size and Strength, Dexterity, and Constitution scores. Natural abilities include armor, natural weapons, and similar gross physical qualities (presence or absence of wings, number of extremities, and so forth), and possibly hardness. Creatures transformed into inanimate objects do not gain the benefit of their untransformed physical abilities, and may well be blind, deaf, dumb, and unfeeling. Objects transformed into creatures gain that creature\'s average physical ability scores, but are considered to have mental ability scores of 0 (the <i>fortify</i> seed can add points to each mental ability, if desired). For each normal extraordinary ability or supernatural ability granted to the transformed creature, increase the Spellcraft DC by +10. The transformed subject can have no more Hit Dice than the caster has or than the subject has (whichever is greater). In any case, for each Hit Die the assumed form has above 15, increase the Spellcraft DC by +2.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Seed: Transform\" level=\"3\"><p><h3>Seed: Transform</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>21<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 minute<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>300 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One creature or inanimate, nonmagical object<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Permanent<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Fortitude negates (see text)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>Spells using the <i>transform</i> seed change the subject into another form of creature or object. The new form can range in size from Diminutive to one size larger than the subject\'s normal form. For each additional increment of size change, increase the Spellcraft DC by +6. If the caster wants to transform a nonmagical, inanimate object into a creature of his or her type or transform a creature into a nonmagical, inanimate object, increase the Spellcraft DC by +10. To change a creature of one type into another type increase the Spellcraft DC by +5.</p><p>Transformations involving nonmagical, inanimate substances with hardness are more difficult; for each 2 points of hardness, increase the Spellcraft DC by +1.</p><p>To transform a creature into an incorporeal or gaseous form, increase the Spellcraft DC by +10. Conversely, to overcome the natural immunity of a gaseous or incorporeal creature to transformation, increase the Spellcraft DC by +10.</p><p>The <i>transform</i> seed can also change its target into someone specific. To transform an object or creature into the specific likeness of another individual (including memories and mental abilities), increase the Spellcraft DC by +25. If the transformed creature doesn\'t have the level or Hit Dice of its new likeness, it can only use the abilities of the creature at its own level or Hit Dice. If slain or destroyed, the transformed creature or object reverts to its original form. The subject\'s equipment, if any, remains untransformed or melds into the new form\'s body, at the caster\'s option. The transformed creature or object acquires the physical and natural abilities of the creature or object it has been changed into while retaining its own memories and mental ability scores. Mental abilities include personality, Intelligence, Wisdom, and Charisma scores, level and class, hit points (despite any change in its Constitution score), alignment, base attack bonus, base saves, extraordinary abilities, spells, and spell-like abilities, but not its supernatural abilities. Physical abilities include natural size and Strength, Dexterity, and Constitution scores. Natural abilities include armor, natural weapons, and similar gross physical qualities (presence or absence of wings, number of extremities, and so forth), and possibly hardness. Creatures transformed into inanimate objects do not gain the benefit of their untransformed physical abilities, and may well be blind, deaf, dumb, and unfeeling. Objects transformed into creatures gain that creature\'s average physical ability scores, but are considered to have mental ability scores of 0 (the <i>fortify</i> seed can add points to each mental ability, if desired). For each normal extraordinary ability or supernatural ability granted to the transformed creature, increase the Spellcraft DC by +10. The transformed subject can have no more Hit Dice than the caster has or than the subject has (whichever is greater). In any case, for each Hit Die the assumed form has above 15, increase the Spellcraft DC by +2.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (83,'Seed: Transport','seed: transport','Conjuration',NULL,'Teleportation','27',NULL,'V, S','1 minute','Touch','You and touched objects or other touched willing creatures weighing up to 1,000 lb.',NULL,NULL,'Instantaneous, or 5 rounds for temporal transport','None or Will negates (see text)','No or Yes (see text)',NULL,NULL,NULL,NULL,NULL,'\n      <p>Spells using the <i>Transport</i> seed instantly take the caster to a designated destination, regardless of distance. For interplanar travel, increase the Spellcraft DC by +4. For each additional 50 pounds in objects and willing creatures beyond the base 1,000 pounds, increase the Spellcraft DC by +2. The base use of the <i>Transport</i> seed provides instantaneous travel through the Astral Plane. To shift the transportation medium to another medium increase the Spellcraft DC by +2. The caster does not need to make a saving throw, nor is spell resistance applicable to him or her. Only objects worn or carried (attended) by another person receive saving throws and spell resistance. For a spell intended to transport unwilling creatures, increase the Spellcraft DC by +4. The caster must have at least a reliable description of the place to which he or she is transporting. If the caster attempts to use the <i>Transport</i> seed with insufficient or misleading information, the character disappears and simply reappear in his or her original location.</p>\n      <p>As a special use of the <i>Transport</i> seed, a caster can develop a spell that temporarily transports him or her into a different time stream (leaving the caster in the same physical location); this increases the Spellcraft DC by +8. If the caster moves him or herself, or the subject, into a slower time stream for 5 rounds, time ceases to flow for the subject, and its condition becomes fixed-no force or effect can harm it until the duration expires. If the caster moves him or her self into a faster time stream, the caster speeds up so greatly that all other creatures seem frozen, though they are actually still moving at their normal speeds. The caster is free to act for 5 rounds of apparent time. Fire, cold, poison gas, and similar effects can still harm the caster. While the caster is in the fast time stream, other creatures are invulnerable to his or her attacks and spells; however, the caster can create spell effects and leave them to take effect when he or she reenters normal time. Because of the branching nature of time, epic spells used to transport a subject into a faster time stream cannot be made permanent, nor can the duration of 5 rounds be extended. More simply, the seed can <i>haste</i> or <i>slow</i> a subject for 20 rounds by transporting it to the appropriate time stream. This decreases the Spellcraft DC by -4.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Seed: Transport\" level=\"3\"><p><h3>Seed: Transport</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration [Teleportation]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>27<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 minute<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You and touched objects or other touched willing creatures weighing up to 1,000 lb.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous, or 5 rounds for temporal transport<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None or Will negates (see text)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No or Yes (see text)<br/></td></tr></table><p>Spells using the <i>Transport</i> seed instantly take the caster to a designated destination, regardless of distance. For interplanar travel, increase the Spellcraft DC by +4. For each additional 50 pounds in objects and willing creatures beyond the base 1,000 pounds, increase the Spellcraft DC by +2. The base use of the <i>Transport</i> seed provides instantaneous travel through the Astral Plane. To shift the transportation medium to another medium increase the Spellcraft DC by +2. The caster does not need to make a saving throw, nor is spell resistance applicable to him or her. Only objects worn or carried (attended) by another person receive saving throws and spell resistance. For a spell intended to transport unwilling creatures, increase the Spellcraft DC by +4. The caster must have at least a reliable description of the place to which he or she is transporting. If the caster attempts to use the <i>Transport</i> seed with insufficient or misleading information, the character disappears and simply reappear in his or her original location.</p><p>As a special use of the <i>Transport</i> seed, a caster can develop a spell that temporarily transports him or her into a different time stream (leaving the caster in the same physical location); this increases the Spellcraft DC by +8. If the caster moves him or herself, or the subject, into a slower time stream for 5 rounds, time ceases to flow for the subject, and its condition becomes fixed-no force or effect can harm it until the duration expires. If the caster moves him or her self into a faster time stream, the caster speeds up so greatly that all other creatures seem frozen, though they are actually still moving at their normal speeds. The caster is free to act for 5 rounds of apparent time. Fire, cold, poison gas, and similar effects can still harm the caster. While the caster is in the fast time stream, other creatures are invulnerable to his or her attacks and spells; however, the caster can create spell effects and leave them to take effect when he or she reenters normal time. Because of the branching nature of time, epic spells used to transport a subject into a faster time stream cannot be made permanent, nor can the duration of 5 rounds be extended. More simply, the seed can <i>haste</i> or <i>slow</i> a subject for 20 rounds by transporting it to the appropriate time stream. This decreases the Spellcraft DC by -4.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (84,'Seed: Ward','seed: ward','Abjuration',NULL,NULL,'14',NULL,'V, S','1 minute','Touch','Touched creature or object of 2,000 lb. or less; or 10-ft. -radius spherical emanation, centered on you',NULL,'Touched creature or object of 2,000 lb. or less; or 10-ft. -radius spherical emanation, centered on you','24 hours','None','Yes',NULL,NULL,NULL,NULL,NULL,'\n      <p>This seed can grant a creature protection from damage of a specified type. The caster can protect a creature from standard damage or from energy damage. The caster can protect a creature or area from magic. Alternatively, he or she can hedge out a type of creature from a specified area. A ward against standard damage protects a creature from whichever two the caster selects of the three damage types: bludgeoning, piercing, and slashing. For a ward against all three types, increase the Spellcraft DC by +4. Each round, the spell created with the <i>Ward</i> seed absorbs the first 5 points of damage the creature would otherwise take, regardless of whether the source of the damage is natural or magical. For each additional point of protection, increase the Spellcraft DC by +2.</p>\n      <p>A ward against energy grants a creature protection from whichever one the caster selects of the five energy types: acid, cold, electricity, fire, or sonic. Each round, the spell absorbs the first 5 points of damage the creature would otherwise take from the specified energy type, regardless of whether the source of damage is natural or magical. The spell protects the recipient\'s equipment as well. For each additional point of protection, increase the Spellcraft DC by +1.</p>\n      <p>A ward against a specific type of creature prevents bodily contact from whichever one of several monster types the caster selects. This causes the natural weapon attacks of such creatures to fail and the creatures to recoil if such attacks require touching the warded creature. The protection ends if the warded creature makes an attack against or intentionally moves within 5 feet of the blocked creature. Spell resistance can allow a creature to overcome this protection and touch the warded creature.</p>\n      <p>A ward against magic creates an immobile, faintly shimmering magical sphere (with radius 10 feet) that surrounds the caster and excludes all spell effects of up to 1st level. Alternatively, the caster can ward just the target and not create the radius effect. For each additional level of spells to be excluded, increase the Spellcraft DC by +20 (but see below). The area or effect of any such spells does not include the area of the ward, and such spells fail to affect any target within the ward. This includes spell-like abilities and spells or spell-like effects from magic items. However, any type of spell can be cast through or out of the ward. The caster can leave and return to the protected area without penalty (unless the spell specifically targets a creature and does not provide a radius effect). The ward could be brought down by a targeted <i>dispel magic</i> spell. Epic spells using the <i>Dispel</i> seed may bring down a ward if the enemy spellcaster succeeds at a caster level check. The ward may also be brought down with a targeted epic spell using the <i>Destroy</i> seed if the enemy spellcaster succeeds at a caster level check.</p>\n      <p>Instead of creating an epic spell that uses the <i>Ward</i> seed to nullify all spells of a given level and lower, the caster can create a ward that nullifies a specific spell (or specific set of spells). For each specific spell so nullified, increase the Spellcraft DC by +2 per spell level above 1st.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Seed: Ward\" level=\"3\"><p><h3>Seed: Ward</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Abjuration<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spellcraft DC:</b><br/></td><td>14<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 minute<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target or Effect:</b><br/></td><td>Touched creature or object of 2,000 lb. or less; or 10-ft. -radius spherical emanation, centered on you<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>24 hours<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>This seed can grant a creature protection from damage of a specified type. The caster can protect a creature from standard damage or from energy damage. The caster can protect a creature or area from magic. Alternatively, he or she can hedge out a type of creature from a specified area. A ward against standard damage protects a creature from whichever two the caster selects of the three damage types: bludgeoning, piercing, and slashing. For a ward against all three types, increase the Spellcraft DC by +4. Each round, the spell created with the <i>Ward</i> seed absorbs the first 5 points of damage the creature would otherwise take, regardless of whether the source of the damage is natural or magical. For each additional point of protection, increase the Spellcraft DC by +2.</p><p>A ward against energy grants a creature protection from whichever one the caster selects of the five energy types: acid, cold, electricity, fire, or sonic. Each round, the spell absorbs the first 5 points of damage the creature would otherwise take from the specified energy type, regardless of whether the source of damage is natural or magical. The spell protects the recipient\'s equipment as well. For each additional point of protection, increase the Spellcraft DC by +1.</p><p>A ward against a specific type of creature prevents bodily contact from whichever one of several monster types the caster selects. This causes the natural weapon attacks of such creatures to fail and the creatures to recoil if such attacks require touching the warded creature. The protection ends if the warded creature makes an attack against or intentionally moves within 5 feet of the blocked creature. Spell resistance can allow a creature to overcome this protection and touch the warded creature.</p><p>A ward against magic creates an immobile, faintly shimmering magical sphere (with radius 10 feet) that surrounds the caster and excludes all spell effects of up to 1st level. Alternatively, the caster can ward just the target and not create the radius effect. For each additional level of spells to be excluded, increase the Spellcraft DC by +20 (but see below). The area or effect of any such spells does not include the area of the ward, and such spells fail to affect any target within the ward. This includes spell-like abilities and spells or spell-like effects from magic items. However, any type of spell can be cast through or out of the ward. The caster can leave and return to the protected area without penalty (unless the spell specifically targets a creature and does not provide a radius effect). The ward could be brought down by a targeted <i>dispel magic</i> spell. Epic spells using the <i>Dispel</i> seed may bring down a ward if the enemy spellcaster succeeds at a caster level check. The ward may also be brought down with a targeted epic spell using the <i>Destroy</i> seed if the enemy spellcaster succeeds at a caster level check.</p><p>Instead of creating an epic spell that uses the <i>Ward</i> seed to nullify all spells of a given level and lower, the caster can create a ward that nullifies a specific spell (or specific set of spells). For each specific spell so nullified, increase the Spellcraft DC by +2 per spell level above 1st.</p><p/>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (85,'Genesis','genesis','Conjuration','Creation',NULL,NULL,'Sorcerer/Wizard 9, Creation 9','V, S, M, XP','1 week (8 hours/day)','180 ft. (see text)',NULL,NULL,'A demiplane coterminous with the Ethereal Plane, centered on your location','Instantaneous','None','No',NULL,NULL,'A crystalline sphere',NULL,NULL,'\n      <p>The spellcaster creates a finite plane with limited access: a demiplane. Demiplanes created by this power are very small, very minor planes.</p>\n      <p>A character can only cast this spell while on the Ethereal Plane. When he or she casts the spell, a local density fluctuation precipitates the creation of a demiplane. At first, the fledgling plane grows at a rate of 1 foot in radius per day to an initial maximum radius of 180 feet as it rapidly draws substance from surrounding ethereal vapors and protomatter.</p>\n      <p>The spellcaster determines the environment within the demiplane when he or she first casts <i>genesis</i>,  reflecting most any desire the spellcaster can visualize. The spellcaster determines factors such as atmosphere, water, temperature, and the general shape of the terrain. This spell cannot create life (including vegetation), nor can it create construction (such as buildings, roads, wells, dungeons, and so forth). The spellcaster must add these things in some other fashion if he or she desires. Once the basic demiplane reaches its maximum size, the spellcaster can continue to cast this spell to enlarge the demiplane, adding another 180 feet of radius to the demiplane each time.</p>\n    ','5,000 XP.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Genesis\" level=\"5\"><p><h5>Genesis</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Creation)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 9, Creation 9<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M, XP<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 week (8 hours/day)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>180 ft. (see text)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>A demiplane coterminous with the Ethereal Plane, centered on your location<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>The spellcaster creates a finite plane with limited access: a demiplane. Demiplanes created by this power are very small, very minor planes.</p><p>A character can only cast this spell while on the Ethereal Plane. When he or she casts the spell, a local density fluctuation precipitates the creation of a demiplane. At first, the fledgling plane grows at a rate of 1 foot in radius per day to an initial maximum radius of 180 feet as it rapidly draws substance from surrounding ethereal vapors and protomatter.</p><p>The spellcaster determines the environment within the demiplane when he or she first casts <i>genesis</i>,  reflecting most any desire the spellcaster can visualize. The spellcaster determines factors such as atmosphere, water, temperature, and the general shape of the terrain. This spell cannot create life (including vegetation), nor can it create construction (such as buildings, roads, wells, dungeons, and so forth). The spellcaster must add these things in some other fashion if he or she desires. Once the basic demiplane reaches its maximum size, the spellcaster can continue to cast this spell to enlarge the demiplane, adding another 180 feet of radius to the demiplane each time.</p><div topic=\"Material Component: A Crystalline Sphere\" level=\"8\"><p><i>Material Component:</i> A crystalline sphere</p><p><i>XP Cost:</i> 5,000 XP.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 EpicSpells');
INSERT INTO spell VALUES (86,'Brain Spider','brain spider','Divination',NULL,'Mind-Affecting',NULL,'Cleric 8, Mind 7','V, S, M, DF','1 round','Long (400 ft. + 40 ft./level)','Up to eight living creatures',NULL,NULL,'1 min./level','Will negates','Yes','Eavesdrop on thoughts of up to eight other creatures.',NULL,'A spider of any size or kind. It can be dead, but must still have all eight legs.',NULL,NULL,'\n      <p>This spell allows you to eavesdrop as a standard action on the thoughts of up to eight other creatures at once, hearing as desired:</p>\n      <ul>\n <li> Individual trains of thought in whatever order you desire.</li>\n <li> Information from all minds about one particular topic, thing, or being, one nugget of information per caster level.</li>\n <li> A study of the thoughts and memories of one creature of the group in detail.</li>\n</ul>\n      <p>Once per round, if you do not perform a detailed study of one creature\'s mind, you can attempt (as a standard action) to implant a <i>suggestion</i> in the mind of any one of the affected creatures. The creature can make another Will saving throw to resist the <i>suggestion</i>,  using the save DC of the <i>brain spider</i> spell. (Creatures with special resistance to enchantment spells can use this resistance to keep from being affected by the <i>suggestion</i>.) Success on this saving throw does not negate the other effects of the <i>brain spider</i> spell for that creature.</p>\n      <p>You can affect all intelligent beings of your choice within range (up to the limit of eight), beginning with known or named beings. Language is not a barrier, and you need not personally know the beings The spell cannot reach those who make a successful Will save.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Brain Spider\" level=\"5\"><p><h5>Brain Spider</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Divination [Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 8, Mind 7<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 round<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Long (400 ft. + 40 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Targets:</b><br/></td><td>Up to eight living creatures<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>This spell allows you to eavesdrop as a standard action on the thoughts of up to eight other creatures at once, hearing as desired:</p><ul>\n <li> Individual trains of thought in whatever order you desire.</li>\n <li> Information from all minds about one particular topic, thing, or being, one nugget of information per caster level.</li>\n <li> A study of the thoughts and memories of one creature of the group in detail.</li>\n</ul><p>Once per round, if you do not perform a detailed study of one creature\'s mind, you can attempt (as a standard action) to implant a <i>suggestion</i> in the mind of any one of the affected creatures. The creature can make another Will saving throw to resist the <i>suggestion</i>,  using the save DC of the <i>brain spider</i> spell. (Creatures with special resistance to enchantment spells can use this resistance to keep from being affected by the <i>suggestion</i>.) Success on this saving throw does not negate the other effects of the <i>brain spider</i> spell for that creature.</p><p>You can affect all intelligent beings of your choice within range (up to the limit of eight), beginning with known or named beings. Language is not a barrier, and you need not personally know the beings The spell cannot reach those who make a successful Will save.</p><p><i>Material Component:</i> A spider of any size or kind. It can be dead, but must still have all eight legs.</p><p/>\n</div>\n    ','SRD 3.5 PsionicSpells');
INSERT INTO spell VALUES (87,'Dweomer of Transference','dweomer of transference','Evocation',NULL,NULL,NULL,'Cleric 4, Sorcerer/Wizard 4','V, S','1 minute','Close (25 ft. + 5 ft./2 levels)','One willing psionic creature',NULL,NULL,'1 round/level','Will negates (harmless)','Yes (harmless)','Convert spellcasting into psionic power points.',NULL,NULL,NULL,NULL,'\n      <p>With this spell, you form a radiating corona around the head of a psionic ally, then convert some of your spells into psionic power points. When you finish casting <i>dweomer of transference</i>,  a red-orange glow surrounds the psionic creature\'s head. For the duration of the spell, any spells cast at the subject don\'t have their usual effect, instead converting themselves harmlessly into psionic energy that the subject can use as energy for psionic powers. You can cast any spell you like at the subject, even area spells, effect spells, and spells for whom the subject would ordinarily not be a legitimate target. The spells don\'t do anything other than provide the subject with power points, but you must still cast them normally, obeying the component and range requirements listed in the description of each spell.</p>\n      <p>For each spell you cast into the <i>dweomer of transference</i>,  the psionic creature gets temporary power points, according to the following table. The transference isn\'t perfectly efficient. The temporary power points acquired through a <i>dweomer of transference</i> dissipate after 1 hour if they haven\'t already been spent.</p>\n      <p/>\n      <table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Spell Level</b><br/></td> <td><b>Power Points Acquired</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>0<br/></td>\n<td>0<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>1st<br/></td>\n<td>1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>2nd<br/></td>\n<td>2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>3rd<br/></td>\n<td>4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>4th<br/></td>\n<td>6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>5th<br/></td>\n<td>8<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>6th<br/></td>\n<td>10<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>7th<br/></td>\n<td>12<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>8th<br/></td>\n<td>14<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>9th<br/></td>\n<td>16<br/></td>\n\n</tr>\n</table>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Dweomer of Transference\" level=\"5\"><p><h5>Dweomer of Transference</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 4, Sorcerer/Wizard 4<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 minute<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One willing psionic creature<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round/level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr></table><p>With this spell, you form a radiating corona around the head of a psionic ally, then convert some of your spells into psionic power points. When you finish casting <i>dweomer of transference</i>,  a red-orange glow surrounds the psionic creature\'s head. For the duration of the spell, any spells cast at the subject don\'t have their usual effect, instead converting themselves harmlessly into psionic energy that the subject can use as energy for psionic powers. You can cast any spell you like at the subject, even area spells, effect spells, and spells for whom the subject would ordinarily not be a legitimate target. The spells don\'t do anything other than provide the subject with power points, but you must still cast them normally, obeying the component and range requirements listed in the description of each spell.</p><p>For each spell you cast into the <i>dweomer of transference</i>,  the psionic creature gets temporary power points, according to the following table. The transference isn\'t perfectly efficient. The temporary power points acquired through a <i>dweomer of transference</i> dissipate after 1 hour if they haven\'t already been spent.</p><p/><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Spell Level</b><br/></td> <td><b>Power Points Acquired</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>0<br/></td>\n<td>0<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>1st<br/></td>\n<td>1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>2nd<br/></td>\n<td>2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>3rd<br/></td>\n<td>4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>4th<br/></td>\n<td>6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>5th<br/></td>\n<td>8<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>6th<br/></td>\n<td>10<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>7th<br/></td>\n<td>12<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>8th<br/></td>\n<td>14<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>9th<br/></td>\n<td>16<br/></td>\n\n</tr>\n</table><p/>\n</div>\n    ','SRD 3.5 PsionicSpells');
INSERT INTO spell VALUES (88,'Glossolalia','glossolalia','Evocation',NULL,'Sonic, Mind-Affecting',NULL,'Bard 2','V','1 standard action','60 ft.',NULL,'Cone-shaped burst',NULL,'Instantaneous','Fortitude partial; see text','Yes','Cone-shaped shriek distracts smart foes, makes concentrating difficult.',NULL,NULL,NULL,NULL,'\n      <p>You utter shrieks of nonsense and gibberish that thinking creatures find distracting and confusing. The spell affects only creatures with Intelligence scores of 3 or higher. Any such creatures within the spell\'s area must succeed on Fortitude saves or be stunned for 1 round (if they have Intelligence scores of 20 or higher), dazed for 1 round (if they have Intelligence scores between 10 and 19), or shaken for 1 round (if they have Intelligence scores between 3 and 9). In addition, a creature within the spell\'s area loses any psionic focus it might have had and takes a -4 penalty on Concentration checks for 1 round. These effects happen whether or not the creature succeeded on its save.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Glossolalia\" level=\"5\"><p><h5>Glossolalia</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Sonic, Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>60 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>Cone-shaped burst<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Fortitude partial; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>You utter shrieks of nonsense and gibberish that thinking creatures find distracting and confusing. The spell affects only creatures with Intelligence scores of 3 or higher. Any such creatures within the spell\'s area must succeed on Fortitude saves or be stunned for 1 round (if they have Intelligence scores of 20 or higher), dazed for 1 round (if they have Intelligence scores between 10 and 19), or shaken for 1 round (if they have Intelligence scores between 3 and 9). In addition, a creature within the spell\'s area loses any psionic focus it might have had and takes a -4 penalty on Concentration checks for 1 round. These effects happen whether or not the creature succeeded on its save.</p><p/>\n</div>\n    ','SRD 3.5 PsionicSpells');
INSERT INTO spell VALUES (89,'Mental Pinnacle','mental pinnacle','Transmutation',NULL,NULL,NULL,'Sorcerer/Wizard 6','V, S, M','1 standard action','Personal','You',NULL,NULL,'1 round/level',NULL,NULL,'You gain the mental powers of a psion.',NULL,'A potion of fox\'s cunning, which you drink (its effect is overridden by the effect of this spell).',NULL,NULL,'\n      <p>For a brief time, you achieve the mental dominance of a powerful psion, able to lash out at enemies using only the power of your mind. Your revel in your new mental powers to the point that you disdain using spells, even in the form of effects from magic items. You gain a +4 enhancement bonus to Intelligence and Wisdom, 3 power points per caster level, and access to the following powers.</p>\n      <ul>\n <li> Mind Thrust<b>A</b>: Deal 1d10 damage.</li>\n <li> Ego Whip<b>A</b>: Deal 1d4 Cha damage and daze for 1 round.</li>\n <li> Psionic Blast<b>A</b>: Stun creatures in 30-ft. cone for 1 round.</li>\n <li> Id Insinuation: Swift tendrils of thought disrupt and confuse your target.</li>\n <li> Psychic Crush<b>A</b>: Brutally crush subject\'s mental essence, reducing subject to -1 hit points.</li>\n</ul>\n      <p>You manifest the powers as a psion of your caster level does, creating displays as described in each power\'s description. You lose your spellcasting ability, including your ability to use spell activation or spell completion magic items, just as if those spells were no longer on your class list. For the duration of this spell, you use magic items and psionic items as if you were a psion with only the five powers given above on your class list.</p>\n      <p>Any unspent power points dissipate when the spell ends.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Mental Pinnacle\" level=\"5\"><p><h5>Mental Pinnacle</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 6<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round/level<br/></td></tr></table><p>For a brief time, you achieve the mental dominance of a powerful psion, able to lash out at enemies using only the power of your mind. Your revel in your new mental powers to the point that you disdain using spells, even in the form of effects from magic items. You gain a +4 enhancement bonus to Intelligence and Wisdom, 3 power points per caster level, and access to the following powers.</p><ul>\n <li> Mind Thrust<b>A</b>: Deal 1d10 damage.</li>\n <li> Ego Whip<b>A</b>: Deal 1d4 Cha damage and daze for 1 round.</li>\n <li> Psionic Blast<b>A</b>: Stun creatures in 30-ft. cone for 1 round.</li>\n <li> Id Insinuation: Swift tendrils of thought disrupt and confuse your target.</li>\n <li> Psychic Crush<b>A</b>: Brutally crush subject\'s mental essence, reducing subject to -1 hit points.</li>\n</ul><p>You manifest the powers as a psion of your caster level does, creating displays as described in each power\'s description. You lose your spellcasting ability, including your ability to use spell activation or spell completion magic items, just as if those spells were no longer on your class list. For the duration of this spell, you use magic items and psionic items as if you were a psion with only the five powers given above on your class list.</p><p>Any unspent power points dissipate when the spell ends.</p><p><i>Material Component:</i> A <i>potion of fox\'s cunning</i>,  which you drink (its effect is overridden by the effect of this spell).</p><p/>\n</div>\n    ','SRD 3.5 PsionicSpells');
INSERT INTO spell VALUES (90,'Probe Thoughts','probe thoughts','Divination',NULL,'Mind-Affecting',NULL,'Mind 6, Sorcerer/Wizard 6','V, S','1 minute','Close (25 ft. + 5 ft./2 levels)','One living creature',NULL,NULL,'Concentration','Fortitude negates; see text','Yes','Read subject\'s memories, one question/round.',NULL,NULL,NULL,NULL,'\n      <p>All the subject\'s memories and knowledge are accessible to you, ranging from memories deep below the surface to those still easily called to mind. You can learn the answer to one question per round, to the best of the subject\'s knowledge. You can also probe a sleeping subject, though the subject may make a Will save against the DC of the <i>probe thoughts</i> spell to wake after each question. Subjects who do not wish to be probed can attempt to move beyond the power\'s range, unless somehow hindered. You pose the questions telepathically, and the answers to those questions are imparted directly to your mind. You and the target do not need to speak the same language, though less intelligent creatures may yield up only appropriate visual images in answer to your questions.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Probe Thoughts\" level=\"5\"><p><h5>Probe Thoughts</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Divination [Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Mind 6, Sorcerer/Wizard 6<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 minute<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One living creature<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Concentration<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Fortitude negates; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>All the subject\'s memories and knowledge are accessible to you, ranging from memories deep below the surface to those still easily called to mind. You can learn the answer to one question per round, to the best of the subject\'s knowledge. You can also probe a sleeping subject, though the subject may make a Will save against the DC of the <i>probe thoughts</i> spell to wake after each question. Subjects who do not wish to be probed can attempt to move beyond the power\'s range, unless somehow hindered. You pose the questions telepathically, and the answers to those questions are imparted directly to your mind. You and the target do not need to speak the same language, though less intelligent creatures may yield up only appropriate visual images in answer to your questions.</p><p/>\n</div>\n    ','SRD 3.5 PsionicSpells');
INSERT INTO spell VALUES (91,'Psychic Turmoil','psychic turmoil','Abjuration',NULL,NULL,NULL,'Cleric 5, Sorcerer/Wizard 5','V, S, M','1 standard action','Close (25 ft. + 5 ft./2 levels)',NULL,'40-ft. -radius emanation centered on a point in space',NULL,'1 round/level','Will partial; see text','Yes','Invisible field leeches psionic power points away.',NULL,'Five playing cards, which are torn in half when the spell is cast.',NULL,NULL,'\n      <p>With this spell, you create an invisible field that leeches away the power points of psionic characters standing within the emanation. Nonpsionic characters are unaffected.</p>\n      <p>When the spell is cast and at the beginning of each of your subsequent turns, psionic creatures within the area of the <i>psychic turmoil</i> lose 1 power point per manifester level they have. Characters who succeed on a Will save when they first come into contact with the emanation lose only half as many power points (round down) each round. Characters get only one save attempt against any particular <i>psychic turmoil</i> effect, even if they leave the spell\'s area and later return.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Psychic Turmoil\" level=\"5\"><p><h5>Psychic Turmoil</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Abjuration<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 5, Sorcerer/Wizard 5<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>40-ft. -radius emanation centered on a point in space<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round/level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will partial; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>With this spell, you create an invisible field that leeches away the power points of psionic characters standing within the emanation. Nonpsionic characters are unaffected.</p><p>When the spell is cast and at the beginning of each of your subsequent turns, psionic creatures within the area of the <i>psychic turmoil</i> lose 1 power point per manifester level they have. Characters who succeed on a Will save when they first come into contact with the emanation lose only half as many power points (round down) each round. Characters get only one save attempt against any particular <i>psychic turmoil</i> effect, even if they leave the spell\'s area and later return.</p><p><i>Material Component:</i> Five playing cards, which are torn in half when the spell is cast.</p><p/>\n</div>\n    ','SRD 3.5 PsionicSpells');
INSERT INTO spell VALUES (92,'Psychic Turmoil, Greater','greater psychic turmoil','Abjuration',NULL,NULL,NULL,'Cleric 7, Sorcerer/Wizard 7','V, S, M','1 standard action','Close (25 ft. + 5 ft./2 levels)',NULL,'40-ft. -radius emanation centered on a point in space',NULL,'1 round/level','Will partial; see text','Yes','As psychic turmoil, but you gain power points as temporary hit points.',NULL,'Five playing cards, which are torn in half when the spell is cast.',NULL,NULL,'\n      <p>As <i>psychic turmoil</i>,  except you gain 1 temporary hit point for each power point the spell takes from a psionic creature. The temporary hit points last for 1 hour.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Psychic Turmoil, Greater\" level=\"5\"><p><h5>Psychic Turmoil, Greater</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Abjuration<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 7, Sorcerer/Wizard 7<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round/level<br/></td></tr></table><p>As <i>psychic turmoil</i>,  except you gain 1 temporary hit point for each power point the spell takes from a psionic creature. The temporary hit points last for 1 hour.</p><p/>\n</div>\n    ','SRD 3.5 PsionicSpells');
INSERT INTO spell VALUES (93,'Telepathic Bond, Lesser','lesser telepathic bond','Divination',NULL,'Mind-Affecting',NULL,'Cleric 3, Mind 3, Sorcerer/Wizard 3','V, S','1 standard action','30 ft.','You and one willing creature within 30 ft.',NULL,NULL,'10 min./level','None','No','As telepathic bond, but you and one other creature.',NULL,NULL,NULL,NULL,'\n      <p>You forge a telepathic bond with another creature with an Intelligence score of 6 or higher. The bond can be established only with a willing subject. You can communicate telepathically through the bond regardless of language. No special power or influence is established as a result of the bond. Once the bond is formed, it works over any distance (although not from one plane to another).</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Telepathic Bond, Lesser\" level=\"5\"><p><h5>Telepathic Bond, Lesser</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Divination [Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 3, Mind 3, Sorcerer/Wizard 3<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>30 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Targets:</b><br/></td><td>You and one willing creature within 30 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>10 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>You forge a telepathic bond with another creature with an Intelligence score of 6 or higher. The bond can be established only with a willing subject. You can communicate telepathically through the bond regardless of language. No special power or influence is established as a result of the bond. Once the bond is formed, it works over any distance (although not from one plane to another).</p><p/>\n</div>\n    ','SRD 3.5 PsionicSpells');
INSERT INTO spell VALUES (94,'Acid Arrow','acid arrow','Conjuration','Creation','Acid',NULL,'Sorcerer/Wizard 2','V, S, M, F','1 standard action','Long (400 ft. + 40 ft./level)',NULL,NULL,'One arrow of acid','1 round + 1 round per three levels','None','No','Ranged touch attack; 2d4 damage for 1 round +1 round/three levels.',NULL,'Powdered rhubarb leaf and an adder\'s stomach.',NULL,'A dart.','\n      <p>A magical arrow of acid springs from your hand and speeds to its target. You must succeed on a ranged touch attack to hit your target. The arrow deals 2d4 points of acid damage with no splash damage. For every three caster levels (to a maximum of 18th), the acid, unless somehow neutralized, lasts for another round, dealing another 2d4 points of damage in that round.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Acid Arrow\" level=\"5\"><p><h5>Acid Arrow</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Creation) [Acid]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M, F<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Long (400 ft. + 40 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>One arrow of acid<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round + 1 round per three levels<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>A magical arrow of acid springs from your hand and speeds to its target. You must succeed on a ranged touch attack to hit your target. The arrow deals 2d4 points of acid damage with no splash damage. For every three caster levels (to a maximum of 18th), the acid, unless somehow neutralized, lasts for another round, dealing another 2d4 points of damage in that round.</p><p><i>Material Component:</i> Powdered rhubarb leaf and an adder\'s stomach.</p><p><i>Focus:</i> A dart.</p><p/>\n</div>\n    ','SRD 3.5 SpellsA-B');
INSERT INTO spell VALUES (95,'Acid Fog','acid fog','Conjuration','Creation','Acid',NULL,'Sorcerer/Wizard 6, Water 7','V, S, M/DF','1 standard action','Medium (100 ft. + 10 ft./level)',NULL,NULL,'Fog spreads in 20-ft. radius, 20 ft. high','1 round/level','None','No','Fog deals acid damage.',NULL,NULL,'A pinch of dried, powdered peas combined with powdered animal hoof.',NULL,'\n      <p><i>Acid fog</i> creates a billowing mass of misty vapors similar to that produced by a <i>solid fog</i> spell. In addition to slowing creatures down and obscuring sight, this spell\'s vapors are highly acidic. Each round on your turn, starting when you cast the spell, the fog deals 2d6 points of acid damage to each creature and object within it.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Acid Fog\" level=\"5\"><p><h5>Acid Fog</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Creation) [Acid]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 6, Water 7<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M/DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>Fog spreads in 20-ft. radius, 20 ft. high<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round/level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p><i>Acid fog</i> creates a billowing mass of misty vapors similar to that produced by a <i>solid fog</i> spell. In addition to slowing creatures down and obscuring sight, this spell\'s vapors are highly acidic. Each round on your turn, starting when you cast the spell, the fog deals 2d6 points of acid damage to each creature and object within it.</p><p><i>Arcane Material Component:</i> A pinch of dried, powdered peas combined with powdered animal hoof.</p><p/>\n</div>\n    ','SRD 3.5 SpellsA-B');
INSERT INTO spell VALUES (96,'Acid Splash','acid splash','Conjuration','Creation','Acid',NULL,'Sorcerer/Wizard 0','V, S','1 standard action','Close (25 ft. + 5 ft./2 levels)',NULL,NULL,'One missile of acid','Instantaneous','None','No','Orb deals 1d3 acid damage.',NULL,NULL,NULL,NULL,'\n      <p>You fire a small orb of acid at the target. You must succeed on a ranged touch attack to hit your target. The orb deals 1d3 points of acid damage.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Acid Splash\" level=\"5\"><p><h5>Acid Splash</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Creation) [Acid]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 0<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>One missile of acid<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>You fire a small orb of acid at the target. You must succeed on a ranged touch attack to hit your target. The orb deals 1d3 points of acid damage.</p><p/>\n</div>\n    ','SRD 3.5 SpellsA-B');
INSERT INTO spell VALUES (97,'Aid','aid','Enchantment','Compulsion','Mind-Affecting',NULL,'Cleric 2, Good 2, Luck 2','V, S, DF','1 standard action','Touch','Living creature touched',NULL,NULL,'1 min./level','None','Yes (harmless)','+1 on attack rolls, +1 against fear, 1d8 temporary hp +1/level (max +10).',NULL,NULL,NULL,NULL,'\n      <p><i>Aid</i> grants the target a +1 morale bonus on attack rolls and saves against fear effects, plus temporary hit points equal to 1d8 + caster level (to a maximum of 1d8+10 temporary hit points at caster level 10th).</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Aid\" level=\"5\"><p><h5>Aid</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Enchantment (Compulsion) [Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 2, Good 2, Luck 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Living creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr></table><p><i>Aid</i> grants the target a +1 morale bonus on attack rolls and saves against fear effects, plus temporary hit points equal to 1d8 + caster level (to a maximum of 1d8+10 temporary hit points at caster level 10th).</p><p/>\n</div>\n    ','SRD 3.5 SpellsA-B');
INSERT INTO spell VALUES (98,'Air Walk','air walk','Transmutation',NULL,'Air',NULL,'Air 4, Cleric 4, Druid 4','V, S, DF','1 standard action','Touch','Creature (Gargantuan or smaller) touched',NULL,NULL,'10 min./level','None','Yes (harmless)','Subject treads on air as if solid (climb at 45-degree angle).',NULL,NULL,NULL,NULL,'\n      <p>The subject can tread on air as if walking on solid ground. Moving upward is similar to walking up a hill. The maximum upward or downward angle possible is 45 degrees, at a rate equal to one-half the air walker\'s normal speed.</p>\n      <p>A strong wind (21+ mph) can push the subject along or hold it back. At the end of its turn each round, the wind blows the air walker 5 feet for each 5 miles per hour of wind speed. The creature may be subject to additional penalties in exceptionally strong or turbulent winds, such as loss of control over movement or physical damage from being buffeted about.</p>\n      <p>Should the spell duration expire while the subject is still aloft, the magic fails slowly. The subject floats downward 60 feet per round for 1d6 rounds. If it reaches the ground in that amount of time, it lands safely. If not, it falls the rest of the distance, taking 1d6 points of damage per 10 feet of fall. Since dispelling a spell effectively ends it, the subject also descends in this way if the <i>air walk</i> spell is dispelled, but not if it is negated by an <i>antimagic field</i>.</p>\n      <p>You can cast <i>air walk</i> on a specially trained mount so it can be ridden through the air. You can train a mount to move with the aid of <i>air walk</i> (counts as a trick; see Handle Animal skill) with one week of work and a DC 25 Handle Animal check.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Air Walk\" level=\"5\"><p><h5>Air Walk</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation [Air]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Air 4, Cleric 4, Druid 4<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Creature (Gargantuan or smaller) touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>10 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr></table><p>The subject can tread on air as if walking on solid ground. Moving upward is similar to walking up a hill. The maximum upward or downward angle possible is 45 degrees, at a rate equal to one-half the air walker\'s normal speed.</p><p>A strong wind (21+ mph) can push the subject along or hold it back. At the end of its turn each round, the wind blows the air walker 5 feet for each 5 miles per hour of wind speed. The creature may be subject to additional penalties in exceptionally strong or turbulent winds, such as loss of control over movement or physical damage from being buffeted about.</p><p>Should the spell duration expire while the subject is still aloft, the magic fails slowly. The subject floats downward 60 feet per round for 1d6 rounds. If it reaches the ground in that amount of time, it lands safely. If not, it falls the rest of the distance, taking 1d6 points of damage per 10 feet of fall. Since dispelling a spell effectively ends it, the subject also descends in this way if the <i>air walk</i> spell is dispelled, but not if it is negated by an <i>antimagic field</i>.</p><p>You can cast <i>air walk</i> on a specially trained mount so it can be ridden through the air. You can train a mount to move with the aid of <i>air walk</i> (counts as a trick; see Handle Animal skill) with one week of work and a DC 25 Handle Animal check.</p><p/>\n</div>\n    ','SRD 3.5 SpellsA-B');
INSERT INTO spell VALUES (99,'Alarm','alarm','Abjuration',NULL,NULL,NULL,'Bard 1, Ranger 1, Sorcerer/Wizard 1','V, S, F/DF','1 standard action','Close (25 ft. + 5 ft./2 levels)',NULL,'20-ft. -radius emanation centered on a point in space',NULL,'2 hours/level (D)','None','No','Wards an area for 2 hours/level.',NULL,NULL,NULL,NULL,'\n      <p>A<i>larm</i> sounds a mental or audible alarm each time a creature of Tiny or larger size enters the warded area or touches it. A creature that speaks the password (determined by you at the time of casting) does not set off the <i>alarm</i>. You decide at the time of casting whether the <i>alarm</i> will be mental or audible.</p>\n      <p><i>Mental Alarm:</i> A mental <i>alarm</i> alerts you (and only you) so long as you remain within 1 mile of the warded area. You note a single mental \'ping\' that awakens you from normal sleep but does not otherwise disturb concentration. A <i>silence</i> spell has no effect on a mental <i>alarm</i>.</p>\n      <p><i>Audible Alarm:</i> An audible <i>alarm</i> produces the sound of a hand bell, and anyone within 60 feet of the warded area can hear it clearly. Reduce the distance by 10 feet for each interposing closed door and by 20 feet for each substantial interposing wall.</p>\n      <p>In quiet conditions, the ringing can be heard faintly as far as 180 feet away. The sound lasts for 1 round. Creatures within a <i>silence</i> spell cannot hear the ringing.</p>\n      <p>Ethereal or astral creatures do not trigger the <i>alarm</i>.</p>\n      <p><i>alarm</i> can be made permanent with a <i>permanency</i> spell.</p>\n      <p/>\n    ',NULL,'A tiny bell and a piece of very fine silver wire',NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Alarm\" level=\"5\"><p><h5>Alarm</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Abjuration<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 1, Ranger 1, Sorcerer/Wizard 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, F/DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>20-ft. -radius emanation centered on a point in space<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>2 hours/level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>A<i>larm</i> sounds a mental or audible alarm each time a creature of Tiny or larger size enters the warded area or touches it. A creature that speaks the password (determined by you at the time of casting) does not set off the <i>alarm</i>. You decide at the time of casting whether the <i>alarm</i> will be mental or audible.</p><p><i>Mental Alarm:</i> A mental <i>alarm</i> alerts you (and only you) so long as you remain within 1 mile of the warded area. You note a single mental \'ping\' that awakens you from normal sleep but does not otherwise disturb concentration. A <i>silence</i> spell has no effect on a mental <i>alarm</i>.</p><p><i>Audible Alarm:</i> An audible <i>alarm</i> produces the sound of a hand bell, and anyone within 60 feet of the warded area can hear it clearly. Reduce the distance by 10 feet for each interposing closed door and by 20 feet for each substantial interposing wall.</p><p>In quiet conditions, the ringing can be heard faintly as far as 180 feet away. The sound lasts for 1 round. Creatures within a <i>silence</i> spell cannot hear the ringing.</p><p>Ethereal or astral creatures do not trigger the <i>alarm</i>.</p><p><i>alarm</i> can be made permanent with a <i>permanency</i> spell.</p><p><i>Arcane Focus:</i> A tiny bell and a piece of very fine silver wire</p><p/>\n</div>\n    ','SRD 3.5 SpellsA-B');
INSERT INTO spell VALUES (100,'Align Weapon','align weapon','Transmutation',NULL,'see text',NULL,'Cleric 2','V, S, DF','1 standard action','Touch','Weapon touched or fifty projectiles (all of which must be in contact with each other at the time of casting)',NULL,NULL,'1 min./level','Will negates (harmless, object)','Yes (harmless, object)','Weapon becomes good, evil, lawful, or chaotic.',NULL,NULL,NULL,NULL,'\n      <p><i>Align weapon</i> makes a weapon good, evil, lawful, or chaotic, as you choose. A weapon that is aligned can bypass the damage reduction of certain creatures. This spell has no effect on a weapon that already has an alignment.</p>\n      <p>You can\'t cast this spell on a natural weapon, such as an unarmed strike.</p>\n      <p>When you make a weapon good, evil, lawful, or chaotic, <i>Align weapon</i> is a good, evil, lawful, or chaotic spell, respectively.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Align Weapon\" level=\"5\"><p><h5>Align Weapon</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation [see text]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Weapon touched or fifty projectiles (all of which must be in contact with each other at the time of casting)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (harmless, object)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless, object)<br/></td></tr></table><p><i>Align weapon</i> makes a weapon good, evil, lawful, or chaotic, as you choose. A weapon that is aligned can bypass the damage reduction of certain creatures. This spell has no effect on a weapon that already has an alignment.</p><p>You can\'t cast this spell on a natural weapon, such as an unarmed strike.</p><p>When you make a weapon good, evil, lawful, or chaotic, <i>Align weapon</i> is a good, evil, lawful, or chaotic spell, respectively.</p><p/>\n</div>\n    ','SRD 3.5 SpellsA-B');
INSERT INTO spell VALUES (101,'Alter Self','alter self','Transmutation',NULL,NULL,NULL,'Bard 2, Sorcerer/Wizard 2','V, S','1 standard action','Personal','You',NULL,NULL,'10 min./level (D)',NULL,NULL,'Assume form of a similar creature.',NULL,NULL,NULL,NULL,'\n      <p>You assume the form of a creature of the same type as your normal form. The new form must be within one size category of your normal size. The maximum HD of an assumed form is equal to your caster level, to a maximum of 5 HD at 5th level. You can change into a member of your own kind or even into yourself.</p>\n      <p>You retain your own ability scores. Your class and level, hit points, alignment, base attack bonus, and base save bonuses all remain the same. You retain all supernatural and spell-like special attacks and qualities of your normal form, except for those requiring a body part that the new form does not have (such as a mouth for a breath weapon or eyes for a gaze attack).</p>\n      <p>You keep all extraordinary special attacks and qualities derived from class levels, but you lose any from your normal form that are not derived from class levels.</p>\n      <p>If the new form is capable of speech, you can communicate normally. You retain any spellcasting ability you had in your original form, but the new form must be able to speak intelligibly (that is, speak a language) to use verbal components and must have limbs capable of fine manipulation to use somatic or material components.</p>\n      <p>You acquire the physical qualities of the new form while retaining your own mind. Physical qualities include natural size, mundane movement capabilities (such as burrowing, climbing, walking, swimming, and flight with wings, to a maximum speed of 120 feet for flying or 60 feet for nonflying movement), natural armor bonus, natural weapons (such as claws, bite, and so on), racial skill bonuses, racial bonus feats, and any gross physical qualities (presence or absence of wings, number of extremities, and so forth). A body with extra limbs does not allow you to make more attacks (or more advantageous two-weapon attacks) than normal.</p>\n      <p>You do not gain any extraordinary special attacks or special qualities not noted above under physical qualities, such as darkvision, low-light vision, blindsense, blindsight, fast healing, regeneration, scent, and so forth.</p>\n      <p>You do not gain any supernatural special attacks, special qualities, or spell-like abilities of the new form. Your creature type and subtype (if any) remain the same regardless of your new form. You cannot take the form of any creature with a template, even if that template doesn\'t change the creature type or subtype.</p>\n      <p>You can freely designate the new form\'s minor physical qualities (such as hair color, hair texture, and skin color) within the normal ranges for a creature of that kind. The new form\'s significant physical qualities (such as height, weight, and gender) are also under your control, but they must fall within the norms for the new form\'s kind. You are effectively disguised as an average member of the new form\'s race. If you use this spell to create a disguise, you get a +10 bonus on your Disguise check.</p>\n      <p>When the change occurs, your equipment, if any, either remains worn or held by the new form (if it is capable of wearing or holding the item), or melds into the new form and becomes nonfunctional. When you revert to your true form, any objects previously melded into the new form reappear in the same location on your body they previously occupied and are once again functional. Any new items you wore in the assumed form and can\'t wear in your normal form fall off and land at your feet; any that you could wear in either form or carry in a body part common to both forms at the time of reversion are still held in the same way. Any part of the body or piece of equipment that is separated from the whole reverts to its true form.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Alter Self\" level=\"5\"><p><h5>Alter Self</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 2, Sorcerer/Wizard 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>10 min./level (D)<br/></td></tr></table><p>You assume the form of a creature of the same type as your normal form. The new form must be within one size category of your normal size. The maximum HD of an assumed form is equal to your caster level, to a maximum of 5 HD at 5th level. You can change into a member of your own kind or even into yourself.</p><p>You retain your own ability scores. Your class and level, hit points, alignment, base attack bonus, and base save bonuses all remain the same. You retain all supernatural and spell-like special attacks and qualities of your normal form, except for those requiring a body part that the new form does not have (such as a mouth for a breath weapon or eyes for a gaze attack).</p><p>You keep all extraordinary special attacks and qualities derived from class levels, but you lose any from your normal form that are not derived from class levels.</p><p>If the new form is capable of speech, you can communicate normally. You retain any spellcasting ability you had in your original form, but the new form must be able to speak intelligibly (that is, speak a language) to use verbal components and must have limbs capable of fine manipulation to use somatic or material components.</p><p>You acquire the physical qualities of the new form while retaining your own mind. Physical qualities include natural size, mundane movement capabilities (such as burrowing, climbing, walking, swimming, and flight with wings, to a maximum speed of 120 feet for flying or 60 feet for nonflying movement), natural armor bonus, natural weapons (such as claws, bite, and so on), racial skill bonuses, racial bonus feats, and any gross physical qualities (presence or absence of wings, number of extremities, and so forth). A body with extra limbs does not allow you to make more attacks (or more advantageous two-weapon attacks) than normal.</p><p>You do not gain any extraordinary special attacks or special qualities not noted above under physical qualities, such as darkvision, low-light vision, blindsense, blindsight, fast healing, regeneration, scent, and so forth.</p><p>You do not gain any supernatural special attacks, special qualities, or spell-like abilities of the new form. Your creature type and subtype (if any) remain the same regardless of your new form. You cannot take the form of any creature with a template, even if that template doesn\'t change the creature type or subtype.</p><p>You can freely designate the new form\'s minor physical qualities (such as hair color, hair texture, and skin color) within the normal ranges for a creature of that kind. The new form\'s significant physical qualities (such as height, weight, and gender) are also under your control, but they must fall within the norms for the new form\'s kind. You are effectively disguised as an average member of the new form\'s race. If you use this spell to create a disguise, you get a +10 bonus on your Disguise check.</p><p>When the change occurs, your equipment, if any, either remains worn or held by the new form (if it is capable of wearing or holding the item), or melds into the new form and becomes nonfunctional. When you revert to your true form, any objects previously melded into the new form reappear in the same location on your body they previously occupied and are once again functional. Any new items you wore in the assumed form and can\'t wear in your normal form fall off and land at your feet; any that you could wear in either form or carry in a body part common to both forms at the time of reversion are still held in the same way. Any part of the body or piece of equipment that is separated from the whole reverts to its true form.</p><p/>\n</div>\n    ','SRD 3.5 SpellsA-B');
INSERT INTO spell VALUES (102,'Analyze Dweomer','analyze dweomer','Divination',NULL,NULL,NULL,'Bard 6, Sorcerer/Wizard 6','V, S, F','1 standard action','Close (25 ft. + 5 ft./2 levels)','One object or creature per caster level',NULL,NULL,'1 round/level (D)','None or Will negates; see text','No','Reveals magical aspects of subject.',NULL,NULL,NULL,'A tiny lens of ruby or sapphire set in a small golden loop. The gemstone must be worth at least 1,500 gp.','\n      <p>You discern all spells and magical properties present in a number of creatures or objects. Each round, you may examine a single creature or object that you can see as a free action. In the case of a magic item, you learn its functions, how to activate its functions (if appropriate), and how many charges are left (if it uses charges). In the case of an object or creature with active spells cast upon it, you learn each spell, its effect, and its caster level.</p>\n      <p>An attended object may attempt a Will save to resist this effect if its holder so desires. If the save succeeds, you learn nothing about the object except what you can discern by looking at it. An object that makes its save cannot be affected by any other <i>analyze dweomer</i> spells for 24 hours.</p>\n      <p><i>analyze dweomer</i> does not function when used on an artifact.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Analyze Dweomer\" level=\"5\"><p><h5>Analyze Dweomer</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Divination<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 6, Sorcerer/Wizard 6<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, F<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Targets:</b><br/></td><td>One object or creature per caster level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round/level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None or Will negates; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>You discern all spells and magical properties present in a number of creatures or objects. Each round, you may examine a single creature or object that you can see as a free action. In the case of a magic item, you learn its functions, how to activate its functions (if appropriate), and how many charges are left (if it uses charges). In the case of an object or creature with active spells cast upon it, you learn each spell, its effect, and its caster level.</p><p>An attended object may attempt a Will save to resist this effect if its holder so desires. If the save succeeds, you learn nothing about the object except what you can discern by looking at it. An object that makes its save cannot be affected by any other <i>analyze dweomer</i> spells for 24 hours.</p><p><i>analyze dweomer</i> does not function when used on an artifact.</p><p><i>Focus:</i> A tiny lens of ruby or sapphire set in a small golden loop. The gemstone must be worth at least 1,500 gp.</p><p/>\n</div>\n    ','SRD 3.5 SpellsA-B');
INSERT INTO spell VALUES (103,'Animal Growth','animal growth','Transmutation',NULL,NULL,NULL,'Druid 5, Ranger 4, Sorcerer/Wizard 5','V, S','1 standard action','Medium (100 ft. + 10 ft./level)','Up to one animal (Gargantuan or smaller) per two levels, no two of which can be more than 30 ft. apart',NULL,NULL,'1 min./level','Fortitude negates','Yes','One animal/two levels doubles in size.',NULL,NULL,NULL,NULL,'\n      <p>A number of animals grow to twice their normal size and eight times their normal weight. This alteration changes each animal\'s size category to the next largest, grants it a +8 size bonus to Strength and a +4 size bonus to Constitution (and thus an extra 2 hit points per HD), and imposes a -2 size penalty to Dexterity. The creature\'s existing natural armor bonus increases by 2. The size change also affects the animal\'s modifier to AC and attack rolls and its base damage. The animal\'s space and reach change as appropriate to the new size, but its speed does not change.</p>\n      <p>The spell also grants each subject damage reduction 10/magic and a +4 resistance bonus on saving throws. If insufficient room is available for the desired growth, the creature attains the maximum possible size and may make a Strength check (using its increased Strength) to burst any enclosures in the process. If it fails, it is constrained without harm by the materials enclosing it- the spell cannot be used to crush a creature by increasing its size.</p>\n      <p>All equipment worn or carried by an animal is similarly enlarged by the spell, though this change has no effect on the magical properties of any such equipment.</p>\n      <p>Any enlarged item that leaves the enlarged creature\'s possession instantly returns to its normal size.</p>\n      <p>The spell gives no means of command or influence over the enlarged animals.</p>\n      <p>Multiple magical effects that increase size do not stack.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Animal Growth\" level=\"5\"><p><h5>Animal Growth</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 5, Ranger 4, Sorcerer/Wizard 5<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Targets:</b><br/></td><td>Up to one animal (Gargantuan or smaller) per two levels, no two of which can be more than 30 ft. apart<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Fortitude negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>A number of animals grow to twice their normal size and eight times their normal weight. This alteration changes each animal\'s size category to the next largest, grants it a +8 size bonus to Strength and a +4 size bonus to Constitution (and thus an extra 2 hit points per HD), and imposes a -2 size penalty to Dexterity. The creature\'s existing natural armor bonus increases by 2. The size change also affects the animal\'s modifier to AC and attack rolls and its base damage. The animal\'s space and reach change as appropriate to the new size, but its speed does not change.</p><p>The spell also grants each subject damage reduction 10/magic and a +4 resistance bonus on saving throws. If insufficient room is available for the desired growth, the creature attains the maximum possible size and may make a Strength check (using its increased Strength) to burst any enclosures in the process. If it fails, it is constrained without harm by the materials enclosing it- the spell cannot be used to crush a creature by increasing its size.</p><p>All equipment worn or carried by an animal is similarly enlarged by the spell, though this change has no effect on the magical properties of any such equipment.</p><p>Any enlarged item that leaves the enlarged creature\'s possession instantly returns to its normal size.</p><p>The spell gives no means of command or influence over the enlarged animals.</p><p>Multiple magical effects that increase size do not stack.</p><p/>\n</div>\n    ','SRD 3.5 SpellsA-B');
INSERT INTO spell VALUES (104,'Animal Messenger','animal messenger','Enchantment','Compulsion','Mind-Affecting',NULL,'Bard 2, Druid 2, Ranger 1','V, S, M','1 standard action','Close (25 ft. + 5 ft./2 levels)','One Tiny animal',NULL,NULL,'One day/level','None; see text','Yes','Sends a Tiny animal to a specific place.',NULL,'A morsel of food the animal likes.',NULL,NULL,'\n      <p>You compel a Tiny animal to go to a spot you designate. The most common use for this spell is to get an animal to carry a message to your allies. The animal cannot be one tamed or trained by someone else, including such creatures as familiars and animal companions.</p>\n      <p>Using some type of food desirable to the animal as a lure, you call the animal to you. It advances and awaits your bidding. You can mentally impress on the animal a certain place well known to you or an obvious landmark. The directions must be simple, because the animal depends on your knowledge and can\'t find a destination on its own. You can attach some small item or note to the messenger. The animal then goes to the designated location and waits there until the duration of the spell expires, whereupon it resumes its normal activities.</p>\n      <p>During this period of waiting, the messenger allows others to approach it and remove any scroll or token it carries. The intended recipient gains no special ability to communicate with the animal or read any attached message (if it\'s written in a language he or she doesn\'t know, for example).</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Animal Messenger\" level=\"5\"><p><h5>Animal Messenger</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Enchantment (Compulsion) [Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 2, Druid 2, Ranger 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One Tiny animal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>One day/level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>You compel a Tiny animal to go to a spot you designate. The most common use for this spell is to get an animal to carry a message to your allies. The animal cannot be one tamed or trained by someone else, including such creatures as familiars and animal companions.</p><p>Using some type of food desirable to the animal as a lure, you call the animal to you. It advances and awaits your bidding. You can mentally impress on the animal a certain place well known to you or an obvious landmark. The directions must be simple, because the animal depends on your knowledge and can\'t find a destination on its own. You can attach some small item or note to the messenger. The animal then goes to the designated location and waits there until the duration of the spell expires, whereupon it resumes its normal activities.</p><p>During this period of waiting, the messenger allows others to approach it and remove any scroll or token it carries. The intended recipient gains no special ability to communicate with the animal or read any attached message (if it\'s written in a language he or she doesn\'t know, for example).</p><p><i>Material Component:</i> A morsel of food the animal likes.</p><p/>\n</div>\n    ','SRD 3.5 SpellsA-B');
INSERT INTO spell VALUES (105,'Animal Shapes','animal shapes','Transmutation',NULL,NULL,NULL,'Animal 7, Druid 8','V, S, DF','1 standard action','Close (25 ft. + 5 ft./2 levels)','Up to one willing creature per level, all within 30 ft. of each other',NULL,NULL,'1 hour/level (D)','None; see text','Yes (harmless)','One ally/level polymorphs into chosen animal.',NULL,'An empty cocoon.',NULL,NULL,'\n      <p>As <i>polymorph</i>,  except you polymorph up to one willing creature per caster level into an animal of your choice; the spell has no effect on unwilling creatures. All creatures must take the same kind of animal form. Recipients remain in the animal form until the spell expires or until you dismiss it for all recipients. In addition, an individual subject may choose to resume its normal form as a full-round action; doing so ends the spell for that subject alone. The maximum HD of an assumed form is equal to the subject\'s HD or your caster level, whichever is lower, to a maximum of 20 HD at 20th level.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Animal Shapes\" level=\"5\"><p><h5>Animal Shapes</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Animal 7, Druid 8<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Targets:</b><br/></td><td>Up to one willing creature per level, all within 30 ft. of each other<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 hour/level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr></table><p>As <i>polymorph</i>,  except you polymorph up to one willing creature per caster level into an animal of your choice; the spell has no effect on unwilling creatures. All creatures must take the same kind of animal form. Recipients remain in the animal form until the spell expires or until you dismiss it for all recipients. In addition, an individual subject may choose to resume its normal form as a full-round action; doing so ends the spell for that subject alone. The maximum HD of an assumed form is equal to the subject\'s HD or your caster level, whichever is lower, to a maximum of 20 HD at 20th level.</p><p/>\n</div>\n    ','SRD 3.5 SpellsA-B');
INSERT INTO spell VALUES (106,'Animal Trance','animal trance','Enchantment','Compulsion','Mind-Affecting, Sonic',NULL,'Bard 2, Druid 2','V, S','1 standard action','Close (25 ft. + 5 ft./2 levels)','Animals or magical beasts with Intelligence 1 or 2',NULL,NULL,'Concentration','Will negates; see text','Yes','Fascinates 2d6 HD of animals.',NULL,NULL,NULL,NULL,'\n      <p>Your swaying motions and music (or singing, or chanting) compel animals and magical beasts to do nothing but watch you. Only a creature with an Intelligence score of 1 or 2 can be fascinated by this spell. Roll 2d6 to determine the total number of HD worth of creatures that you fascinate. The closest targets are selected first until no more targets within range can be affected.</p>\n      <p>A magical beast, a dire animal, or an animal trained to attack or guard is allowed a saving throw; an animal not trained to attack or guard is not.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Animal Trance\" level=\"5\"><p><h5>Animal Trance</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Enchantment (Compulsion) [Mind-Affecting, Sonic]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 2, Druid 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Targets:</b><br/></td><td>Animals or magical beasts with Intelligence 1 or 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Concentration<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>Your swaying motions and music (or singing, or chanting) compel animals and magical beasts to do nothing but watch you. Only a creature with an Intelligence score of 1 or 2 can be fascinated by this spell. Roll 2d6 to determine the total number of HD worth of creatures that you fascinate. The closest targets are selected first until no more targets within range can be affected.</p><p>A magical beast, a dire animal, or an animal trained to attack or guard is allowed a saving throw; an animal not trained to attack or guard is not.</p><p/>\n</div>\n    ','SRD 3.5 SpellsA-B');
INSERT INTO spell VALUES (107,'Animate Dead','animate dead','Necromancy',NULL,'Evil',NULL,'Cleric 3, Death 3, Sorcerer/Wizard 4','V, S, M','1 standard action','Touch','One or more corpses touched',NULL,NULL,'Instantaneous','None','No','Creates undead skeletons and zombies.',NULL,'You must place a black onyx gem worth at least 25 gp per Hit Die of the undead into the mouth or eye socket of each corpse you intend to animate. The magic of the spell turns these gems into worthless, burned-out shells.',NULL,NULL,'\n      <p>This spell turns the bones or bodies of dead creatures into undead skeletons or zombies that follow your spoken commands.</p>\n      <p>The undead can follow you, or they can remain in an area and attack any creature (or just a specific kind of creature) entering the place. They remain animated until they are destroyed. (A destroyed skeleton or zombie can\'t be animated again.)</p>\n      <p>Regardless of the type of undead you create with this spell, you can\'t create more HD of undead than twice your caster level with a single casting of <i>animate dead</i>. (The <i>desecrate</i> spell doubles this limit)</p>\n      <p>The undead you create remain under your control indefinitely. No matter how many times you use this spell, however, you can control only 4 HD worth of undead creatures per caster level. If you exceed this number, all the newly created creatures fall under your control, and any excess undead from previous castings become uncontrolled. (You choose which creatures are released.) If you are a cleric, any undead you might command by virtue of your power to command or rebuke undead do not count toward the limit.</p>\n      <p><i>Skeletons:</i> A skeleton can be created only from a mostly intact corpse or skeleton. The corpse must have bones. If a skeleton is made from a corpse, the flesh falls off the bones.</p>\n      <p><i>Zombies:</i> A zombie can be created only from a mostly intact corpse. The corpse must be that of a creature with a true anatomy.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Animate Dead\" level=\"5\"><p><h5>Animate Dead</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Necromancy [Evil]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 3, Death 3, Sorcerer/Wizard 4<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Targets:</b><br/></td><td>One or more corpses touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>This spell turns the bones or bodies of dead creatures into undead skeletons or zombies that follow your spoken commands.</p><p>The undead can follow you, or they can remain in an area and attack any creature (or just a specific kind of creature) entering the place. They remain animated until they are destroyed. (A destroyed skeleton or zombie can\'t be animated again.)</p><p>Regardless of the type of undead you create with this spell, you can\'t create more HD of undead than twice your caster level with a single casting of <i>animate dead</i>. (The <i>desecrate</i> spell doubles this limit)</p><p>The undead you create remain under your control indefinitely. No matter how many times you use this spell, however, you can control only 4 HD worth of undead creatures per caster level. If you exceed this number, all the newly created creatures fall under your control, and any excess undead from previous castings become uncontrolled. (You choose which creatures are released.) If you are a cleric, any undead you might command by virtue of your power to command or rebuke undead do not count toward the limit.</p><p><i>Skeletons:</i> A skeleton can be created only from a mostly intact corpse or skeleton. The corpse must have bones. If a skeleton is made from a corpse, the flesh falls off the bones.</p><p><i>Zombies:</i> A zombie can be created only from a mostly intact corpse. The corpse must be that of a creature with a true anatomy.</p><p><i>Material Component:</i> You must place a black onyx gem worth at least 25 gp per Hit Die of the undead into the mouth or eye socket of each corpse you intend to animate. The magic of the spell turns these gems into worthless, burned-out shells.</p><p/>\n</div>\n    ','SRD 3.5 SpellsA-B');
INSERT INTO spell VALUES (108,'Animate Objects','animate objects','Transmutation',NULL,NULL,NULL,'Bard 6, Chaos 6, Cleric 6','V, S','1 standard action','Medium (100 ft. + 10 ft./level)','One Small object per caster level; see text',NULL,NULL,'1 round/level','None','No','Objects attack your foes.',NULL,NULL,NULL,NULL,'\n      <p>You imbue inanimate objects with mobility and a semblance of life. Each such animated object then immediately attacks whomever or whatever you initially designate.</p>\n      <p>An animated object can be of any nonmagical material. You may animate one Small or smaller object or an equivalent number of larger objects per caster level. A Medium object counts as two Small or smaller objects, a Large object as four, a Huge object as eight, a Gargantuan object as sixteen, and a Colossal object as thirty-two. You can change the designated target or targets as a move action, as if directing an active spell.</p>\n      <p>This spell cannot animate objects carried or worn by a creature.</p>\n      <p><i>Animate objects</i> can be made permanent with a <i>permanency</i> spell.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Animate Objects\" level=\"5\"><p><h5>Animate Objects</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 6, Chaos 6, Cleric 6<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Targets:</b><br/></td><td>One Small object per caster level; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round/level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>You imbue inanimate objects with mobility and a semblance of life. Each such animated object then immediately attacks whomever or whatever you initially designate.</p><p>An animated object can be of any nonmagical material. You may animate one Small or smaller object or an equivalent number of larger objects per caster level. A Medium object counts as two Small or smaller objects, a Large object as four, a Huge object as eight, a Gargantuan object as sixteen, and a Colossal object as thirty-two. You can change the designated target or targets as a move action, as if directing an active spell.</p><p>This spell cannot animate objects carried or worn by a creature.</p><p><i>Animate objects</i> can be made permanent with a <i>permanency</i> spell.</p><p/>\n</div>\n    ','SRD 3.5 SpellsA-B');
INSERT INTO spell VALUES (109,'Animate Plants','animate plants','Transmutation',NULL,NULL,NULL,'Druid 7, Plant 7','V','1 standard action','Close (25 ft. + 5 ft./2 levels)','One Large plant per three caster levels or all plants within range; see text',NULL,NULL,'1 round/level or 1 hour/level; see text','None','No','One or more plants animate and fight for you.',NULL,NULL,NULL,NULL,'\n      <p>You imbue inanimate plants with mobility and a semblance of life. Each animated plant then immediately attacks whomever or whatever you initially designate as though it were an animated object of the appropriate size category. You may animate one Large or smaller plant, or an equivalent number of larger plants, per three caster levels. A Huge plant counts as two Large or smaller plants, a Gargantuan plant as four, and a Colossal plant as eight. You can change the designated target or targets as a move action, as if directing an active spell.</p>\n      <p>Use the statistics for animated objects,  except that plants smaller than Large usually don\'t have hardness.</p>\n      <p><i>Animate plants</i> cannot affect plant creatures, nor does it affect nonliving vegetable material.</p>\n      <p><i>Entangle:</i> Alternatively, you may imbue all plants within range with a degree of mobility, which allows them to entwine around creatures in the area. This usage of the spell duplicates the effect of an <i>entangle</i> spell. Spell resistance does not keep creatures from being entangled. This effect lasts 1 hour per caster level.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Animate Plants\" level=\"5\"><p><h5>Animate Plants</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 7, Plant 7<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Targets:</b><br/></td><td>One Large plant per three caster levels or all plants within range; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round/level or 1 hour/level; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>You imbue inanimate plants with mobility and a semblance of life. Each animated plant then immediately attacks whomever or whatever you initially designate as though it were an animated object of the appropriate size category. You may animate one Large or smaller plant, or an equivalent number of larger plants, per three caster levels. A Huge plant counts as two Large or smaller plants, a Gargantuan plant as four, and a Colossal plant as eight. You can change the designated target or targets as a move action, as if directing an active spell.</p><p>Use the statistics for animated objects,  except that plants smaller than Large usually don\'t have hardness.</p><p><i>Animate plants</i> cannot affect plant creatures, nor does it affect nonliving vegetable material.</p><p><i>Entangle:</i> Alternatively, you may imbue all plants within range with a degree of mobility, which allows them to entwine around creatures in the area. This usage of the spell duplicates the effect of an <i>entangle</i> spell. Spell resistance does not keep creatures from being entangled. This effect lasts 1 hour per caster level.</p><p/>\n</div>\n    ','SRD 3.5 SpellsA-B');
INSERT INTO spell VALUES (110,'Animate Rope','animate rope','Transmutation',NULL,NULL,NULL,'Bard 1, Sorcerer/Wizard 1','V, S','1 standard action','Medium (100 ft. + 10 ft./level)','One ropelike object, length up to 50 ft. + 5 ft./level; see text',NULL,NULL,'1 round/level','None','No','Makes a rope move at your command.',NULL,NULL,NULL,NULL,'\n      <p>You can animate a nonliving ropelike object. The maximum length assumes a rope with a 1-inch diameter.</p>\n      <p>Reduce the maximum length by 50% for every additional inch of thickness, and increase it by 50% for each reduction of the rope\'s diameter by half.</p>\n      <p>The possible commands are \'coil\' (form a neat, coiled stack), \'coil and knot,\' \'loop,\' \'loop and knot,\' \'tie and knot,\' and the opposites of all of the above (\'uncoil,\' and so forth). You can give one command each round as a move action, as if directing an active spell.</p>\n      <p>The rope can enwrap only a creature or an object within 1 foot of it-it does not snake outward-so it must be thrown near the intended target. Doing so requires a successful ranged touch attack roll (range increment 10 feet). A typical 1- inch-diameter hempen rope has 2 hit points, AC 10, and requires a DC 23 Strength check to burst it. The rope does not deal damage, but it can be used as a trip line or to cause a single opponent that fails a Reflex saving throw to become entangled. A creature capable of spellcasting that is bound by this spell must make a DC 15 Concentration check to cast a spell. An entangled creature can slip free with a DC 20 Escape Artist check.</p>\n      <p>The rope itself and any knots tied in it are not magical.</p>\n      <p>This spell grants a +2 bonus on any Use Rope checks you make when using the transmuted rope.</p>\n      <p>The spell cannot animate objects carried or worn by a creature.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Animate Rope\" level=\"5\"><p><h5>Animate Rope</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 1, Sorcerer/Wizard 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One ropelike object, length up to 50 ft. + 5 ft./level; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round/level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>You can animate a nonliving ropelike object. The maximum length assumes a rope with a 1-inch diameter.</p><p>Reduce the maximum length by 50% for every additional inch of thickness, and increase it by 50% for each reduction of the rope\'s diameter by half.</p><p>The possible commands are \'coil\' (form a neat, coiled stack), \'coil and knot,\' \'loop,\' \'loop and knot,\' \'tie and knot,\' and the opposites of all of the above (\'uncoil,\' and so forth). You can give one command each round as a move action, as if directing an active spell.</p><p>The rope can enwrap only a creature or an object within 1 foot of it-it does not snake outward-so it must be thrown near the intended target. Doing so requires a successful ranged touch attack roll (range increment 10 feet). A typical 1- inch-diameter hempen rope has 2 hit points, AC 10, and requires a DC 23 Strength check to burst it. The rope does not deal damage, but it can be used as a trip line or to cause a single opponent that fails a Reflex saving throw to become entangled. A creature capable of spellcasting that is bound by this spell must make a DC 15 Concentration check to cast a spell. An entangled creature can slip free with a DC 20 Escape Artist check.</p><p>The rope itself and any knots tied in it are not magical.</p><p>This spell grants a +2 bonus on any Use Rope checks you make when using the transmuted rope.</p><p>The spell cannot animate objects carried or worn by a creature.</p><p/>\n</div>\n    ','SRD 3.5 SpellsA-B');
INSERT INTO spell VALUES (111,'Antilife Shell','antilife shell','Abjuration',NULL,NULL,NULL,'Animal 6, Cleric 6, Druid 6','V, S, DF','1 round','10 ft.',NULL,'10-ft. -radius emanation, centered on you',NULL,'10 min./level (D)','None','Yes','10-ft. -radius field hedges out living creatures.',NULL,NULL,NULL,NULL,'\n      <p>You bring into being a mobile, hemispherical energy field that prevents the entrance of most types of living creatures.</p>\n      <p>The effect hedges out animals, aberrations, dragons, fey, giants, humanoids, magical beasts, monstrous humanoids, oozes, plants, and vermin, but not constructs, elementals, outsiders, or undead.</p>\n      <p>This spell may be used only defensively, not aggressively. Forcing an abjuration barrier against creatures that the spell keeps at bay collapses the barrier.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Antilife Shell\" level=\"5\"><p><h5>Antilife Shell</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Abjuration<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Animal 6, Cleric 6, Druid 6<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 round<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>10 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>10-ft. -radius emanation, centered on you<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>10 min./level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>You bring into being a mobile, hemispherical energy field that prevents the entrance of most types of living creatures.</p><p>The effect hedges out animals, aberrations, dragons, fey, giants, humanoids, magical beasts, monstrous humanoids, oozes, plants, and vermin, but not constructs, elementals, outsiders, or undead.</p><p>This spell may be used only defensively, not aggressively. Forcing an abjuration barrier against creatures that the spell keeps at bay collapses the barrier.</p><p/>\n</div>\n    ','SRD 3.5 SpellsA-B');
INSERT INTO spell VALUES (112,'Antimagic Field','antimagic field','Abjuration',NULL,NULL,NULL,'Cleric 8, Magic 6, Protection 6, Sorcerer/Wizard 6','V, S, M/DF','1 standard action','10 ft.',NULL,'10-ft. -radius emanation, centered on you',NULL,'10 min./level (D)','None','See text','Negates magic within 10 ft.',NULL,NULL,'A pinch of powdered iron or iron filings.',NULL,'\n      <p>An invisible barrier surrounds you and moves with you. The space within this barrier is impervious to most magical effects, including spells, spell-like abilities, and supernatural abilities. Likewise, it prevents the functioning of any magic items or spells within its confines.</p>\n      <p>An <i>antimagic field</i> suppresses any spell or magical effect used within, brought into, or cast into the area, but does not dispel it. Time spent within an <i>antimagic field</i> counts against the suppressed spell\'s duration.</p>\n      <p>Summoned creatures of any type and incorporeal undead wink out if they enter an <i>antimagic field</i>. They reappear in the same spot once the field goes away. Time spent winked out counts normally against the duration of the conjuration that is maintaining the creature. If you cast <i>antimagic field</i> in an area occupied by a summoned creature that has spell resistance, you must make a caster level check (1d20 + caster level) against the creature\'s spell resistance to make it wink out. (The effects of instantaneous conjurations are not affected by an <i>antimagic field</i> because the conjuration itself is no longer in effect, only its result.)</p>\n      <p>A normal creature can enter the area, as can normal missiles. Furthermore, while a magic sword does not function magically within the area, it is still a sword (and a masterwork sword at that). The spell has no effect on golems and other constructs that are imbued with magic during their creation process and are thereafter self-supporting (unless they have been summoned, in which case they are treated like any other summoned creatures). Elementals, corporeal undead, and outsiders are likewise unaffected unless summoned. These creatures\' spell-like or supernatural abilities, however, may be temporarily nullified by the field. <i>dispel magic</i> does not remove the field.</p>\n      <p>Two or more <i>antimagic fields</i> sharing any of the same space have no effect on each other. Certain spells, such as <i>wall of force</i>,  <i>prismatic sphere</i>, and <i>prismatic wall</i>,  remain unaffected by <i>antimagic field</i> (see the individual spell descriptions). Artifacts and deities are unaffected by mortal magic such as this.</p>\n      <p>Should a creature be larger than the area enclosed by the barrier, any part of it that lies outside the barrier is unaffected by the field.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Antimagic Field\" level=\"5\"><p><h5>Antimagic Field</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Abjuration<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 8, Magic 6, Protection 6, Sorcerer/Wizard 6<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M/DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>10 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>10-ft. -radius emanation, centered on you<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>10 min./level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>See text<br/></td></tr></table><p>An invisible barrier surrounds you and moves with you. The space within this barrier is impervious to most magical effects, including spells, spell-like abilities, and supernatural abilities. Likewise, it prevents the functioning of any magic items or spells within its confines.</p><p>An <i>antimagic field</i> suppresses any spell or magical effect used within, brought into, or cast into the area, but does not dispel it. Time spent within an <i>antimagic field</i> counts against the suppressed spell\'s duration.</p><p>Summoned creatures of any type and incorporeal undead wink out if they enter an <i>antimagic field</i>. They reappear in the same spot once the field goes away. Time spent winked out counts normally against the duration of the conjuration that is maintaining the creature. If you cast <i>antimagic field</i> in an area occupied by a summoned creature that has spell resistance, you must make a caster level check (1d20 + caster level) against the creature\'s spell resistance to make it wink out. (The effects of instantaneous conjurations are not affected by an <i>antimagic field</i> because the conjuration itself is no longer in effect, only its result.)</p><p>A normal creature can enter the area, as can normal missiles. Furthermore, while a magic sword does not function magically within the area, it is still a sword (and a masterwork sword at that). The spell has no effect on golems and other constructs that are imbued with magic during their creation process and are thereafter self-supporting (unless they have been summoned, in which case they are treated like any other summoned creatures). Elementals, corporeal undead, and outsiders are likewise unaffected unless summoned. These creatures\' spell-like or supernatural abilities, however, may be temporarily nullified by the field. <i>dispel magic</i> does not remove the field.</p><p>Two or more <i>antimagic fields</i> sharing any of the same space have no effect on each other. Certain spells, such as <i>wall of force</i>,  <i>prismatic sphere</i>, and <i>prismatic wall</i>,  remain unaffected by <i>antimagic field</i> (see the individual spell descriptions). Artifacts and deities are unaffected by mortal magic such as this.</p><p>Should a creature be larger than the area enclosed by the barrier, any part of it that lies outside the barrier is unaffected by the field.</p><p><i>Arcane Material Component:</i> A pinch of powdered iron or iron filings.</p><p/>\n</div>\n    ','SRD 3.5 SpellsA-B');
INSERT INTO spell VALUES (113,'Antipathy','antipathy','Enchantment','Compulsion','Mind-Affecting',NULL,'Druid 9, Sorcerer/Wizard 8','V, S, M/DF','1 hour','Close (25 ft. + 5 ft./2 levels)','One location (up to a 10-ft. cube/level) or one object',NULL,NULL,'2 hours/level (D)','Will partial','Yes','Object or location affected by spell repels certain creatures.',NULL,NULL,'A lump of alum soaked in vinegar.',NULL,'\n      <p>You cause an object or location to emanate magical vibrations that repel either a specific kind of intelligent creature or creatures of a particular alignment, as defined by you. The kind of creature to be affected must be named specifically. A creature subtype is not specific enough. Likewise, the specific alignment to be repelled must be named.</p>\n      <p>Creatures of the designated kind or alignment feel an overpowering urge to leave the area or to avoid the affected item.</p>\n      <p>A compulsion forces them to abandon the area or item, shunning it and never willingly returning to it while the spell is in effect. A creature that makes a successful saving throw can stay in the area or touch the item but feels uncomfortable doing so. This distracting discomfort reduces the creature\'s Dexterity score by 4 points.</p>\n      <p><i>Antipathy</i> counters and dispels <i>sympathy</i>.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Antipathy\" level=\"5\"><p><h5>Antipathy</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Enchantment (Compulsion) [Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 9, Sorcerer/Wizard 8<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M/DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 hour<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One location (up to a 10-ft. cube/level) or one object<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>2 hours/level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will partial<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>You cause an object or location to emanate magical vibrations that repel either a specific kind of intelligent creature or creatures of a particular alignment, as defined by you. The kind of creature to be affected must be named specifically. A creature subtype is not specific enough. Likewise, the specific alignment to be repelled must be named.</p><p>Creatures of the designated kind or alignment feel an overpowering urge to leave the area or to avoid the affected item.</p><p>A compulsion forces them to abandon the area or item, shunning it and never willingly returning to it while the spell is in effect. A creature that makes a successful saving throw can stay in the area or touch the item but feels uncomfortable doing so. This distracting discomfort reduces the creature\'s Dexterity score by 4 points.</p><p><i>Antipathy</i> counters and dispels <i>sympathy</i>.</p><p><i>Arcane Material Component:</i> A lump of alum soaked in vinegar.</p><p/>\n</div>\n    ','SRD 3.5 SpellsA-B');
